(window.GIM_TS=window.GIM_TS||{})["Kiddushin.3"]={"from":72,"a":[["\u0003אקרוב עומר והדר אכול\u0004 \u0005[הקריבו עומר ו\u0006רק \u0005אחר כך אכלו].\u0006","\u0003אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שממה שנאמר \"מושב\" אנו למדים שרק \u0003לאחר ירושה וישיבה\u0004 חל איסור החדש, אם כן \u0003ניכול לאלתר\u0004 \u0005[שיאכלו\u0006 מתבואת הארץ \u0005מיד]!\u0006 ומשיבים: \u0003לא הוו צריכי\u0004 \u0005[היו צריכים]\u0006 לכך, שעדיין היה להם מן, ולכן לא אכלו מתבואת הארץ, ולא מחמת האיסור,","\u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ובני ישראל אכלו את המן ארבעים שנה עד באם אל ארץ נושבת, את המן אכלו עד באם אל קצה ארץ כנען\"\u0004 (שמות טז, לה). ומבררים את פירוש הפסוק: \u0003אי אפשר לומר\u0004 שאכלו את המן דווקא \u0003\"עד באם אל ארץ נושבת\",\u0004 כלומר, שכשנכנסו לארץ ישראל עדיין אכלו מן, \u0003ש\u0004הרי \u0003כבר נאמר \"אל קצה ארץ כנען\",\u0004 שמשמעו לפני שנכנסו לארץ ישראל, בעת שהיו עדיין בערבות מואב. \u0003ואי אפשר לומר\u0004 שאכלו רק עד בואם \u0003\"אל קצה ארץ כנען\"\u0004 — \u0003שהרי כבר נאמר \"עד באם אל ארץ נושבת\". הא כיצד\u0004 יש להבין את הסתירה בפסוק? — אלא \u0003בשבעה באדר מת משה ופסק מן מלירד\u0004 בהיותם בעבר הירדן, \u0003והיו מסתפקין\u0004 (משתמשים) \u0003ממן ש\u0004נשאר \u0003בכליהם עד ששה עשר בניסן\u0004 ואף לאחר שנכנסו לארץ.","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 באותו ענין: על מה שנאמר \u0003\"ובני ישראל אכלו את המן ארבעים שנה\"\u0004 יש להקשות: \u0003וכי ארבעים שנה אכלו? והלא ארבעים שנה חסר שלשים יום אכלו,\u0004 שהרי בשישה עשר באייר לשנתם הראשונה במדבר, החל המן לרדת ובשישה עשר בניסן לשנת הארבעים פסקו מלאכול אותו! \u0003אלא לומר לך: עוגות\u0004 מצות \u0003שהוציאו ממצרים\u0004 בחמישה עשר בניסן בשנתם הראשונה וניזונו מהם עד שירד המן, \u0003טעמו בהם טעם מן.\u0004","\u0003תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]:\u0006 \u0003בשבעה באדר מת משה, ובשבעה באדר נולד. מנין שבשבעה באדר מת\u0004 — \u0003שנאמר: \"וימת שם משה עבד ה'\"\u0004 (דברים לד, ה), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויבכו בני ישראל את משה בערבת מואב שלשים יום\"\u0004 (שם ח), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"ויהי אחרי\u0004 \u0003מות משה עבד ה'\"\u0004 (יהושע א, א), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"משה עבדי מת ועתה קום עבר\u0004 את הירדן","\u0003\"\u0004(שם ב), \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"עברו בקרב המחנה וצוו את העם לאמר הכינו לכם צדה כי בעוד שלשת ימים תעברו את הירדן\"\u0004 (שם יא) \u0003וכתיב\u0004 \u0005[ונאמר]:\u0006 \u0003\"והעם עלו מן הירדן בעשור לחדש הראשון\"\u0004 (שם ד, יט), אם כן \u0003צא\u0004 (הוצא) \u0003מהן,\u0004 מהימים הללו עד עשור לחודש הראשון, שהוא עשרה בניסן, \u0003שלשים ושלשה ימים למפרע\u0004 (אחורנית) שהם: שלושים יום של אבל משה, ושלושת ימי ההכנה לפני חציית הירדן, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003למדת\u0004 מכאן \u0003שבשבעה באדר מת משה.\u0004","\u0003ומנין שבשבעה באדר נולד משה\u0004 — \u0003שנאמר: \"ויאמר אלהם בן מאה ועשרים שנה אנכי היום לא אוכל עוד לצאת ולבוא\"\u0004 (דברים לא, ב), \u0003שאין תלמוד לומר \"היום\"\u0004 ודי היה לומר \"בן מאה ועשרים שנה אנוכי\", ו\u0003מה\u0004 בכל זאת \u0003תלמוד לומר \"היום\"\u0004 — הרי זה בא לדייק: היום בדיוק. \u0003מלמד שהקדוש ברוך הוא יושב וממלא שנותיהם של צדיקים מיום ליום ומחדש לחדש, שנאמר: \"את מספר ימיך אמלא\"\u0004 (שמות כג, כו).","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' שמעון בן יוחי אומר: שלש מצות\u0004 (חדש, כלאיים וערלה) \u0003נצטוו ישראל\u0004 מיד \u0003בכניסתן לארץ, ו\u0004הן \u0003נוהגות בין בארץ בין בחוצה לארץ.\u0004","\u0003והוא הדין,\u0004 כלומר, יש סברה של קל וחומר בכל אחת מהן \u0003שינהגו\u0004 כן; \u0003ומה חדש שאין איסורו איסור עולם,\u0004 שהרי הוא פג לאחר הקרבת העומר בשישה עשר בניסן \u0003ואין איסורו איסור הנאה,\u0004 שהרי החדש אסור רק באכילה עד הקרבת העומר, \u0003ויש היתר לאיסורו,\u0004 שאחרי הקרבת העומר, החדש שהיה אסור נעשה מותר, ובכל זאת הוא \u0003נוהג בין בארץ בין בחוצה לארץ\u0004 —","\u0003כלאים שאיסורן איסור עולם,\u0004 שאין זמן בו פג האיסור, \u0003ואיסורן איסור הנאה,\u0004 שכלאי הכרם אסורים בהנאה, \u0003ואין\u0004 אופן של \u0003היתר לאיסורן\u0004 — \u0003אינו דין שינהגו בין בארץ בין בחוצה לארץ? והוא הדין לערלה בשתים,\u0004 כלומר, אף על פי שאין איסורה איסור עולם (שהרי איסורה הוא לשלוש שנים בלבד), מכל מקום הרי היא איסור הנאה, ואין היתר לאיסורה, שפירות ערלה עצמן אינם מותרים לעולם.","\u0003ר' אלעזר בר' שמעון אומר:\u0004"],["\u0003כל מצוה שנצטוו\u0004 עליה \u0003ישראל קודם כניסתן לארץ,\u0004 שלא נאמר בה שהיא תלויה בביאת ישראל לארצם — \u0003נוהגת בין בארץ בין בחוצה לארץ.\u0004 וכל מצוה שנצטוו עליה \u0003לאחר כניסתן לארץ\u0004 — \u0003אינה נוהגת אלא בארץ, חוץ מן השמטת כספים\u0004 (חובות) בשנת השמיטה \u0003ושילוח עבדים\u0004 ביובל, \u0003שאף על פי שנצטוו עליהם לאחר כניסתן לארץ\u0004 — \u0003נוהגת בין בארץ בין בחוצה לארץ.\u0004","ותוהים: \u0003השמטת כספים\u0004 הרי \u0003חובת הגוף היא\u0004 ומה החידוש שבדבר שנוהגת גם בחוץ לארץ?","ומשיבים: \u0003לא נצרכא\u0004 \u0005[נצרכה]\u0006 השמטת כספים להיאמר \u0003אלא לכדתניא\u0004 \u0005[לכפי ששנינו\u0006 בברייתא\u0005],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003רבי אומר:\u0004 נאמר \"\u0003וזה דבר השמטה שמוט\"\u0004 (דברים טו, ב) בלשון כפולה, ללמדך כי \u0003בשתי שמיטות הכתוב מדבר: אחת שמיטת קרקע,\u0004 שאסור לעבד את הקרקע בשביעית, \u0003ואחת שמיטת כספים.\u0004 ולהקישן זו לזו ולומר: \u0003בזמן שאתה משמט קרקע\u0004 כלומר: כאשר היובל נוהג — \u0003אתה משמט כספים, בזמן שאי\u0004 (אין) \u0003אתה משמט קרקע\u0004 — \u0003אי אתה משמט כספים\u0004","\u0003ואימא\u0004 \u0005[ואמור]\u0006 איפוא גם את ההיקש לדבר אחר: \u0003במקום שאתה משמט קרקע,\u0004 כלומר, בארץ ישראל — \u0003אתה משמט כספים, ובמקום שאין אתה משמט קרקע\u0004 — \u0003אין אתה משמט כספים\u0004 ותהא שמיטת כספים נוהגת רק בארץ ישראל למרות שהיא חובת הגוף — \u0003תלמוד לומר: \"כי קרא שמטה לה'\"\u0004 (שם) — \u0003מכל מקום\u0004 ואף בחוץ לארץ, וזהו מה שחידש ר' אלעזר בר' שמעון.","על מה שר' אלעזר בר' שמעון אומר ש\u0003שילוח עבדים\u0004 ביובל נוהג בכל מקום, תוהים: גם זו \u0003חובת הגוף היא!\u0004 ומה החידוש בדבריו? ומשיבים: \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל וכתיב\u0004 \u0005[ונאמר]\u0006 \u0003\"וקראתם דרור בארץ\u0004 לכל יושביה\u0003\"\u0004 (ויקרא כה, י) שמא תאמר: \u0003בארץ\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 אבל \u0003בחוצה לארץ\u0004 — \u0003לא, תלמוד לומר: \"יובל היא\"\u0004 (שם), \u0003מכל מקום.\u0004","ומקשים: \u0003אם כן מה תלמוד לומר: \"בארץ\"\u0004 ומשיבים: לומר לך: \u0003בזמן שהדרור נוהג בארץ\u0004 — \u0003נוהג\u0004 גם \u0003בחוצה לארץ, אין דרור נוהג בארץ\u0004 — \u0003אינו נוהג בחוצה לארץ,\u0004 שהדבר תלוי בזמן שהיובל נוהג ולא במקום.","\u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003החדש אסור מן התורה בכל מקום, ערלה\u0004 אסורה בחוץ לארץ על פי \u0003הלכה, והכלאים\u0004 אסורים בחוץ לארץ \u0003מדברי סופרים.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 היא\u0005]\u0006 \u0003הלכה\u0004 זו שאמרנו בערלה? \u0003אמר רב יהודה אמר שמואל: הלכתא מדינה\u0004 \u0005[הלכות מדינה],\u0006 כלומר, כך נהגו ישראל במקומות שישבו בהם. ו\u0003עולא אמר\u0004 בשם \u0003ר' יוחנן\u0004 פירוש אחר: \u0003הלכה למשה מסיני.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003עולא לרב יהודה: בשלמא לדידי\u0004 \u0005[נניח לשיטתי]\u0006 \u0003דאמינא\u0004 \u0005[שאני אומר]\u0006 בשם ר' יוחנן שהלכה שאמרו במשנה הכוונה ל\u0003הלכה למשה מסיני\u0004 — \u0003היינו דשני לן\u0004 \u0005[זה\u0006 הטעם \u0005ששונה לנו]\u0006 הדין \u0003בין ספק ערלה\u0004 שאסורה בחוץ לארץ מהלכה למשה מסיני \u0003לספק כלאים\u0004 שאסורים רק מדברי סופרים.","כמו \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 הקונה מגוי פרי שהוא \u0003ספק ערלה,\u0004 כגון שלקט פירות משדה שיש בו גם אילנות האסורים באיסור ערלה ואין ידוע ממה לקט, \u0003בארץ\u0004 ישראל — \u0003אסור\u0004 לאכול מפירות אלו אף בדיעבד, \u0003בסוריא\u0004 — \u0003מותר,\u0004 בדיעבד לאכול מהפירות הללו. \u0003בחוצה לארץ יורד\u0004 היהודי \u0003ולוקח\u0004 מן הגוי אפילו לכתחילה, \u0003ובלבד שלא יראנו\u0004 שהוא \u0003לוקט\u0004 מעצי הערלה, שאין זה ספק אלא ודאי.","\u0003ואילו\u0004 ל\u0003גבי\u0004 דיני \u0003כלאים תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003כרם הנטוע ירק,\u0004 שזרעו ירקות בתוך הכרם, \u0003ו\u0004רואים \u0003ירק נמכר חוצה לו\u0004 לכרם, אבל אין הוכחה גמורה שירקות אלה באו מכרם זה; \u0003בארץ\u0004 — \u0003אסור,\u0004 שהרי יש ספק שמא הירקות באים משם, ובכל ספק של איסור תורה הולכים לחומרה, \u0003בסוריא\u0004 — \u0003מותר,\u0004","\u0003בחוצה לארץ\u0004 — \u0003יורד\u0004 בעל הכרם הגוי \u0003ולוקט\u0004 ומוכר ליהודי. \u0003ובלבד שלא ילקוט\u0004 היהודי עצמו \u0003ביד.\u0004 אם כן רואים שיש הבדל בחוץ לארץ בין ספק ערלה לספק כלאים והוא מובן אם ערלה היא הלכה למשה מסיני ולכן מחמירים בה, בעוד כלאיים הם רק מדברי סופרים.","\u0003אלא לדידך\u0004 \u0005[ל\u0006שיטתך \u0005שלך]\u0006 בשם שמואל ששניהם אסורים מדברי סופרים ומפני המנהג, אם כן אין הבדל בהלכה בין ערלה לכלאיים."],["\u0003ניתני\u0004 \u0005[שישנה]\u0006 אם כן בשניהם באותה לשון — \u0003או\u0004 שיאמר: \u0003\"זה וזה יורד ולוקח\", או\u0004 שיאמר: \u0003\"זה וזה יורד ולוקט\"!\u0004 ומשיבים: \u0003האמר ליה\u0004 \u0005[הרי אמר לו]\u0006 \u0003שמואל לרב ענן: תני\u0004 \u0005[שנה]\u0006 באמת, \u0003או \"זה וזה יורד ולוקח\" או \"זה וזה יורד ולוקט\". מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבנא מתני ליה לקולא\u0004 \u0005[היה\u0006 באמת \u0005שונה\u0006 למשנה \u0005זו\u0006 בלשון שמשמעה \u0005להקל],\u0006 \u0003\"זה וזה יורד ולוקט, ובלבד שלא ילקוט\u0004 עבור עצמו \u0003ביד\".\u0004","ומסופר בענין ערלה בחוץ לארץ: \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003לוי לשמואל: אריוך\u0004 (כך היה כינויו של שמואל), \u0003ספק\u0004 \u0005[הבא]\u0006 \u0003לי,\u0004 שאני עצמי לא אלקט פירות אלה, \u0003ואנא איכול\u0004 \u0005[ואני אוכל],\u0006 שאין לחשוש לכך בחוצה לארץ. \u0003רב אויא ורבה בר רב חנן מספקו ספוקי להדדי\u0004 \u0005[היו מביאים זה לזה],\u0006 שכל זמן שהוא עצמו אינו לוקח מן הערלה אין בכך איסור. \u0003אמרי\u0004 \u0005[אמרו]\u0006 \u0003חריפי\u0004 העיר \u0003פומבדיתא:\u0004 אין איסור \u0003ערלה\u0004 נו הג \u0003בחוצה לארץ\u0004 כלל.","\u0003שלחה רב יהודה\u0004 את הבעיה הזו \u0003לקמיה\u0004 \u0005[לפני]\u0006 \u0003ר' יוחנן. שלח ליה\u0004 \u0005[לו]\u0006 כתשובה: \u0003סתום\u0004 (השאר סתום, אל תפרסם) את דינו של \u0003ספיקא\u0004 \u0005[ספק]\u0006 ערלה להיתר, \u0003ואבד\u0004 ואסור לחלוטין \u0003ודאה\u0004 \u0005[ודאי]\u0006 ערלה, \u0003והכרז על פירותיהן\u0004 של המקילים בה \u0003שטעונים גניזה\u0004 (קבורה), שאין להנות מהם. \u0003וכל האומר אין\u0004 איסור \u0003ערלה בחוצה לארץ\u0004 — \u0003לא יהא לו נין ונכד, \"משליך חבל\u0004 (משתתף) \u0003בגורל בקהל ה'\"\u0004 (מיכה ב, ה).","ושואלים: \u0003ואינהו כמאן סברוה\u0004 \u0005[והם,\u0006 חריפי פומבדיתא, \u0005כמי סברו,\u0006 על מי הסתמכו כשפסקו הלכה \u0005זו]\u0006 ומשיבים: \u0003כי הא דתניא\u0004 \u0005[כמו\u0006 דעה \u0005זו ששנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' אלעזר בר' יוסי אומר משום\u0004 (בשם) \u0003ר' יוסי בן דורמסקה, שאמר משום ר' יוסי הגלילי, שאמר משום ר' יוחנן בן נורי, שאמר משום ר' אליעזר הגדול: אין ערלה בחוצה לארץ\u0004 כלל.","ותוהים: \u0003ולא,\u0004 וכי סבור ר' אליעזר שאין ערלה בחוץ לארץ? \u0003והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנתנו\u0005]\u0006 ש\u0003ר' אליעזר אומר: אף החדש,\u0004 משמע שהוא מודה בערלה ובכלאים שאסורים בחוץ לארץ! ומשיבים: \u0003תני\u0004 \u0005[שנה]:\u0006 לא \"אף החדש\" אלא: \u0003\"חדש\",\u0004 כלומר, שרק בזה סבור הוא שהוא נוהג בחוץ לארץ.","\u0003אמר ר' אסי אמר ר' יוחנן: ערלה בחוצה לארץ\u0004 אסורה ב\u0003הלכה למשה מסיני. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' זירא לר' אסי: והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ספק ערלה, בארץ\u0004 — \u0003אסור, בסוריא\u0004 — \u0003מותר, בחוצה לארץ\u0004 — \u0003יורד ולוקט.\u0004 ואם היתה הערלה אסורה בחוץ לארץ הלכה למשה מסיני, איך מותר ספיקה בסוריה? \u0003\"אשתומם כשעה חדה\"\u0004 \u0005[השתומם,\u0006 שתק \u0005כשעה אחת]\u0006 (כלשון הכתוב דניאל ד, טז) ואחר כך \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אימא\u0004 \u0005[אמור]\u0006 \u0003כך נאמר\u0004 ונתפרש בהלכה זו למשה מסיני: שבחוץ לארץ \u0003ספיקא מותר, ודאה\u0004 — \u0003אסור.\u0004","\u0003אמר ר' אסי אמר ר' יוחנן: לוקין על\u0004 איסור \u0003הכלאים\u0004 בחוץ לארץ מ\u0003דבר תורה. אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אלעזר בר' יוסי: והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכלאים מדברי סופרים!\u0004 ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003כאן\u0004 במשנה מדובר \u0003בכלאי הכרם\u0004 שהם אסורים בחוץ לארץ מדברי סופרים, \u0003כאן\u0004 בדברי ר' יוחנן מדובר \u0003בהרכבת האילן\u0004 במין אחר.","ומקור הלכה זו הוא \u0003כ\u0004דברי \u0003שמואל,\u0004 ש\u0003אמר שמואל:\u0004 נאמר \u0003\"את חקתי תשמרו\"\u0004 (ויקרא יט, יט) כוונתו: עליך לשמור אף על \u0003חוקים שחקקתי לך כבר\u0004 שנאסרו לבני נוח עוד לפני מתן תורה, והם: \u0003\"בהמתך לא תרביע כלאים שדך לא תזרע\u0004 כלאים","\u0003\"\u0004(שם). והוקשו האיסורים זה לזה ללמד: \u0003מה\u0004 איסור כלאים האמור לגבי \u0003בהמתך\u0004 הוא דווקא \u0003בהרבעה\u0004 של מין בשאינו מינו, \u0003אף\u0004 איסור כלאים ב\u0003שדך\u0004 הוא דווקא \u0003בהרכבה\u0004 של אילן זה באילן מסוג אחר, ולא בזריעת מינים שונים יחד. ועוד אפשר ללמוד מכאן: \u0003ומה\u0004 איסור כלאים לגבי \u0003בהמתך נוהג בין בארץ בין בחוצה לארץ\u0004 (שהרי חובת הגוף הוא ואינו תלוי בארץ), \u0003אף\u0004 איסור הרכבה של \u0003שדך נוהג בין בארץ בין בחוצה לארץ.\u0004","ושואלים: \u0003ואלא הכתיב\u0004 \u0005[והרי נאמר]\u0006 שם \u0003\"שדך\"\u0004 שמשמעו השדה שלך, כלומר, נחלת ישראל בארץ ישראל! ומשיבים: הכתוב \u0003ההוא\u0004 נדרש \u0003למעוטי\u0004 \u0005[למעט]\u0006 כלאי \u0003זרעים ש\u0004אינם נוהגים \u0003בחוצה לארץ,\u0004 שזריעת זרעים שונים יחד אין בה איסור אלא בארץ בלבד.","מסופר: \u0003רב חנן ורב ענן הוו שקלי ואזלי באורחא\u0004 \u0005[היו מהלכים בדרך]\u0006 בחוץ לארץ \u0003חזיוהו לההוא גברא דקא זרע זרעים בהדי הדדי\u0004 \u0005[ראו אדם אחד שהיה זורע זרעים\u0006 שונים \u0005ביחד].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אחד לחבירו: \u0003ניתי מר נשמתיה\u0004 \u0005[יבוא אדוני\u0006 ו\u0005ינדה אותו]\u0006 על שעושה איסור. \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא חווריתו\u0004 \u0005[אין\u0006 ההלכות הללו \u0005מחוורות לכם].\u0006","\u0003ותו, חזיוהו לההוא גברא דקא זרע חטי ושערי בי גופני\u0004 \u0005[ועוד, ראו אדם אחד שהיה זורע חטים ושעורים בין הגפנים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003ניתי מר נשמתיה\u0004 \u0005[יבוא אדוני\u0006 ו\u0005ינדה אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא צהריתו\u0004 \u0005[אין\u0006 ההלכות הללו \u0005בהירות לכם].\u0006 והסביר לו: וכי \u0003לא קיימא לן\u0004 \u0005[מוחזק לנו,\u0006 בידינו\u0005]\u0006 \u0003כר' יאשיה\u0004 ש\u0003אמר:\u0004 אין אדם חייב מלקות מן התורה על כלאים \u0003עד שיזרע חטה ושעורה וחרצן\u0004 של גפן, שלשתם \u0003במפולת יד\u0004 (בזריעה) אחת?! ואדם זה שלא עשה כן, אין מקום לנדותו.","מסופר: \u0003רב יוסף\u0004 היה \u0003מערב ביזרני\u0004 \u0005[זרעים\u0006 שונים\u0005]\u0006 \u0003וזרע\u0004 \u0005[וזורע].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: והאנן תנן\u0004 \u0005[והרי אנו שנינו\u0006 במשנה\u0005]:\u0006 \u0003הכלאים\u0004 אסורים בחוץ לארץ על כל פנים \u0003מדברי סופרים! אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה],\u0006 \u0003כאן\u0004 במשנה מדובר \u0003בכלאי הכרם, כאן\u0004 שאני נוהג היתר גמור הוא \u0003בכלאי זרעים.\u0004 וזה טעם הדבר: \u0003כלאי הכרם\u0004 ש\u0003בארץ אסורים\u0004 אפילו \u0003בהנאה\u0004 — \u0003בחוצה לארץ נמי גזרו בהו רבנן\u0004 \u0005[גם כן גזרו בהם חכמים]\u0006 איסור. ואילו \u0003כלאי זרעים\u0004 ש\u0003בארץ לא אסירי\u0004 \u0005[אינם אסורים]\u0006 \u0003בהנאה\u0004 — \u0003בחוצה לארץ נמי\u0004 \u0005[גם כן]\u0006 \u0003לא גזרו בהו רבנן\u0004 \u0005[בהם חכמים]\u0006 כלל.","\u0003הדר\u0004 \u0005[חזר]\u0006 ו\u0003אמר רב יוסף: לאו מלתא היא דאמרי\u0004 \u0005[אין זה דבר\u0006 שיש בו ממש מה \u0005שאמרתי]\u0006 שכלאי זרעים הותרו לגמרי בחוץ לארץ, וראיה לדבר ממה ש\u0003רב זרע גינתא דבי\u0004 \u0005[\u0006את \u0005הגינה של בית]\u0006 \u0003רב\u0004 מסביב לבית המדרש \u0003משארי משארי\u0004 \u0005[ערוגות ערוגות]\u0006 של מינים שונים, \u0003מאי טעמא\u0004 \u0005[מה הטעם]\u0006 עשה כן, ולא זרע מינים שונים יחד, \u0003לאו\u0004 \u0005[האם לא]\u0006 \u0003משום\u0004 שחשש לאיסור של \u0003עירוב עירובי כלאים? אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 זו איננה ראיה, \u0003בשלמא אי אשמעינן\u0004 \u0005[נניח אם היה משמיע לנו]\u0006 הלכה על ידי מעשיו,"],["\u0003ארבע\u0004 סוגים שונים \u0003על ארבע רוחות\u0004 (קצוות) \u0003הערוגה ואחת באמצע\u0004 הערוגה, כדי להרחיקם זה מזה — \u0003שפיר\u0004 \u0005[יפה]\u0006 אתה אומר, שמזה מוכח שהוא מקפיד שלא לזרוע כלאים. \u0003אלא הכא\u0004 \u0005[כאן]\u0006 שזרע רב כל מין בערוגה נפרדת, מה שעשה היה רק \u0003משום נוי\u0004 ליפות את גינת בית המדרש. \u0003ואי נמי\u0004 \u0005[או גם כן]\u0006 \u0003משום טרחא דשמעא\u0004 \u0005[של השמש]\u0006 \u0003היא,\u0004 שזרע כך על מנת שכאשר ישלח את שמשו להביא מין ירק מסויים מהגינה לא יצטרך השמש לחפש, וידע באיזה ערוגה הוא. ואין להוכיח מכאן שחשש לאיסור כלאי זרעים בחוץ לארץ.","\u0003כל העושה מצוה אחת\u0004 — \u0003מטיבין לו, ומאריכין לו ימיו, ונוחל את הארץ\u0004 העליונה, לחיי עולם הבא. \u0003וכל שאינו עושה מצוה אחת\u0004 — \u0003אין מטיבין לו, ואין מאריכין לו ימיו, ואינו נוחל את הארץ.\u0004","\u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו במשנה אחרת: \u0003אלו דברים שאדם אוכל פירותיהן בעולם הזה והקרן קיימת לו לעולם הבא, אלו הן: כבוד אב ואם, וגמילות חסדים, והכנסת אורחים, והבאת שלום בין אדם לחבירו, ותלמוד תורה כנגד כולם.\u0004 משמע שרק על מצוות אלה מטיבים לו בעולם הזה ולא על כל המצוות כולן!","\u0003אמר רב יהודה: הכי קאמר\u0004 \u0005[כך אמר],\u0006 כך צריך להבין את משנתנו: \u0003כל העושה מצוה אחת יתירה על זכיותיו\u0004 ועל ידי כך נהיה הוא מי שרובו זכויות \u0003מטיבים לו, ודומה כמי שמקיים כל התורה כולה.\u0004 ושואלים: \u0003מכלל\u0004 הדברים אתה למד \u0003דהנך\u0004 \u0005[ש\u0006המצוות המיוחדות \u0005הללו]\u0006 שנמנו במשנה האחרת \u0003אפילו בחדא נמי\u0004 \u0005[באחת\u0006 מהן \u0005גם כן]\u0006 זוכה לכל אלה, גם אם עוונותיו מרובים? \u0003אמר רב שמעיה:\u0004 המשנה האחרת באה \u0003לומר שאם היתה שקולה,\u0004 שכלל עוונותיו שקולים כנגד זכויותיו — הרי מצוה שכזו כשהיא בין הזכויות \u0003מכרעת\u0004 לזכותו.","ועוד שואלים: \u0003וכל העושה מצוה אחת יתירה על זכיותיו מטיבין לו\u0004 בעולם הזה? \u0003ורמינהו\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 מברייתא, ששנינו בה: \u0003כל שזכיותיו מרובין מעונותיו\u0004 — \u0003מריעין לו,\u0004 שכך נוהגים בו בעולם הזה כדי למרק את עוונותיו בחייו ויזכה לשכר שלם על מצוותיו בעולם הבא. \u0003ודומה כמי ששרף\u0004 את \u0003כל התורה כולה ולא שייר ממנה אפילו אות אחת.\u0004 ולהיפך, \u0003וכל שעונותיו מרובין מזכיותיו מטיבין לו\u0004 בעולם הזה, \u0003ודומה כמי שקיים\u0004 את \u0003כל התורה כולה ולא חיסר אות אחת ממנה!\u0004","\u0003אמר אביי:\u0004 מה שאמרה \u0003מתניתין\u0004 \u0005[משנתנו]\u0006 שמטיבין לו הכוונה \u0003דעבדין ליה\u0004 \u0005[שעושים לו]\u0006 \u0003יום טב\u0004 \u0005[טוב]\u0006 \u0003ויום ביש\u0004 \u0005[רע],\u0006 שבשכר המצוות זוכה לטוב, אבל מפעם לפעם באים עליו גם ימים רעים כדי למרק את עוונותיו, ועל אותם ימים דיברה הברייתא. \u0003רבא אמר:\u0004 משנתנו והברייתא מציגות שתי שיטות שונות. \u0003הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — שיטת \u0003ר' יעקב היא,\u0004 ש\u0003אמר\u0004 בכלל: \u0003שכר מצוה בהאי עלמא ליכא\u0004 \u0005[בעולם הזה אין]\u0006 כלל, וכל שכר המצוות הוא רק לעתיד לבוא.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יעקב אומר: אין לך כל מצוה ומצוה שכתובה בתורה\u0004 ו\u0003שמתן שכרה\u0004 כתוב \u0003בצדה, שאין תחיית המתים תלויה בה,\u0004 כלומר, השכר מגיע לאדם רק בעולם הבא, לאחר תחיית המתים. כיצד? \u0003בכיבוד אב ואם כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"למען יאריכן ימיך ולמען ייטב לך\"\u0004 (דברים ה, טז), \u0003בשילוח הקן כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"למען ייטב לך והארכת ימים\"\u0004 (שם כב, ז).","ואם כן, \u0003הרי שאמר לו אביו: עלה לבירה\u0004 (לראש הבית, המגדל) \u0003והבא לי גוזלות. ועלה לבירה ושלח את האם, ונטל את הבנים\u0004 וקיים איפוא מצוות שילוח הקן וכיבוד אב גם יחד \u0003ובחזירתו נפל ומת\u0004 — \u0003היכן טובת ימיו של זה, והיכן אריכות ימיו של זה? אלא: \"למען ייטב לך\"\u0004 כוונתו \u0003לעולם שכולו טוב, ו\"למען יאריכן ימיך\"\u0004 — \u0003לעולם שכולו ארוך.\u0004","ותוהים: \u0003ודלמא לאו הכי הוה\u0004 \u0005[ושמא לא כך היה]?\u0006 שמא באמת כל אדם שעושה מצוות אלה מקבל שכרן בעולם הזה ולא תיתכן מציאות כמו זו שהזכיר ר' יעקב! ומשיבים: \u0003ר' יעקב מעשה חזא\u0004 \u0005[ראה],\u0006 שכך אירע לאדם אחד. ושואלים עוד: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 אותו אדם \u0003מהרהר בעבירה הוה\u0004 \u0005[היה]\u0006 באותה שעה, ובגלל זה נענש? ומשיבים: כלל נקוט בידינו כי \u0003מחשבה רעה אין הקדוש ברוך הוא מצרפה ל\u0004היות כ\u0003מעשה,\u0004 ולא היה נענש על מחשבה בלבד.","ושואלים: \u0003ודלמא\u0004 \u0005[ושמא]\u0006 \u0003מהרהר בעבודה זרה הוה\u0004 \u0005[היה]\u0006 אז, \u0003וכתיב\u0004 \u0005[ונאמר]\u0006 בענין עבודה זרה \u0003\"למען תפש את בית ישראל בלבם\"\u0004 (יחזקאל יד, ה), שעל עבירה זו נענשים אף על הרהור הלב?! ומשיבים: \u0003איהו נמי הכי קאמר\u0004 \u0005[הוא,\u0006 ר' יעקב, \u0005גם כן כך אמר]:\u0006 \u0003אי סלקא דעתך\u0004 \u0005[אם עולה על דעתך]\u0006 לומר שיש \u0003שכר מצוה בהאי עלמא\u0004 \u0005[בעולם הזה]\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003לא אגין\u0004 \u0005[הגנו]\u0006 ה\u0003מצות עליה כי היכי דלא ליתי\u0004 \u0005[עליו כדי שלא יבוא]\u0006 \u0003לידי הרהור\u0004 עבירה? ואם בכל זאת הירהר בעבודה זרה באותה שעה — משמע שאין המצוה מועילה בעולם הזה.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר: שלוחי מצוה אין נזוקין!\u0004 והרי היה אדם זה שליח מצוה וכיצד קרה הדבר שמת?! ומשיבים: \u0003התם\u0004 \u0005[שם],\u0006 \u0003בהליכתן\u0004 של שליחי מצוה \u0003שאני\u0004 \u0005[שונה\u0006 הדבר\u0005]\u0006 שאינם ניזוקים, אבל מעשה זה אירע לו לאותו אדם בחזרתו משם, ולאחר שכבר עשה את המצוה אינו נשמר.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003אמר ר' אלעזר\u0004 במפורש: \u0003שלוחי מצוה אינן נזוקין לא בהליכתן ולא בחזירתן!\u0004 ומשיבים: \u0003סולם רעוע הוה\u0004 \u0005[היה]\u0006 שם, \u0003דקביע היזיקא\u0004 \u0005[שקבוע\u0006 בו \u0005הנזק]\u0006 \u0003וכל היכא דקביע היזיקא לא סמכינן אניסא\u0004 \u0005[וכל מקום ש\u0006יש \u0005היזק קבוע\u0006 וברור \u0005אין אנו סומכים על הנס].\u0006 וראיה לדבר זה ממה \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003\"ויאמר שמואל איך אלך ושמע שאול והרגני\"\u0004 (שמואל א טז, ב), שאף שה' ציווה אותו ללכת, מכל מקום כיון שהיתה סכנה ברורה בדבר לא יכול היה לסמוך על הנס שיינצל.","\u0003אמר רב יוסף: אילמלי דרשיה\u0004 \u0005[אילו היה דורש]\u0006 \u0003אחר,\u0004 אלישע בן אבויה, \u0003להאי קרא\u0004 \u0005[את הפסוק הזה]\u0006 \"למען ייטב לך\" לעולם הבא כמו שדרש \u0003ר' יעקב בר ברתיה\u0004 \u0005[בן בתו]\u0006 — \u0003לא חטא.\u0004 ושואלים: \u0003ואחר מאי הוא\u0004 \u0005[מה הוא]\u0006 המקרה שבגללו חטא? \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003כי האי גוונא חזא\u0004 \u0005[כגון זה ראה]\u0006 שעלה הבן במצות אביו להביא גוזלות, ושילח את האם ונפל ומת, ומשום כך התפקר.","\u0003ואיכא דאמרי\u0004 \u0005[ויש אומרים]:\u0006 \u0003לישנא\u0004 \u0005[\u0006את \u0005הלשון]\u0006 של \u0003חוצפית המתורגמן חזא\u0004 \u0005[ראה]\u0006 לאחר שנהרג על ידי המלכות והושלך לחוץ \u0003דהוה גריר ליה דבר אחר\u0004 \u0005[שהיה גורר אותה חזיר].\u0006 \u0003אמר: פה שהפיק מרגליות ילחך עפר?! נפק\u0004 \u0005[יצא]\u0006 ו\u0003חטא\u0004 בגלל זה.","\u0003רמי\u0004 \u0005[השליך\u0006 הראה סתירה\u0005]\u0006 \u0003רב טובי בר רב קיסנא לרבא: תנן\u0004 \u0005[שנינו\u0006 במשנתנו\u0005]\u0006 \u0003כל העושה מצוה אחת מטיבין לו,\u0004 משמע: אם \u0003עשה\u0004 מצוה בפועל — \u0003אין\u0004 \u0005[כן],\u0006 \u0003לא עשה\u0004 — \u0003לא. ורמינהי\u0004 \u0005[ומשליכים\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003ישב ולא עבר עבירה\u0004 — \u0003נותנים לו שכר כעושה מצוה\u0004 אף שלא עשה מצוה בפועל ממש! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003התם\u0004 \u0005[שם]\u0006 שאמרנו: ישב ולא עבר עבירה — אין הכוונה שישב סתם, אלא \u0003כגון שבא דבר עבירה לידו וניצול הימנה\u0004 (ממנה).","\u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003ר' חנינא בר פפי תבעתיה ההיא מטרוניתא\u0004 \u0005[תבעה אותו גבירה אחת\u0006 לזנות\u0005].\u0006 \u0003אמר מלתא ומלי נפשיה שיחנא וכיבא\u0004 \u0005[אמר דבר\u0006 של לחש \u0005ומילא\u0006 את \u0005עצמו שחין ופצעים],\u0006 \u0003עבדה היא מילתא ואיתסי\u0004 \u0005[עשתה היא דבר\u0006 אחר של כשפים \u0005והתרפא].\u0006 \u0003ערק, טשא בההוא בי בני\u0004 \u0005[הלך\u0006 ו\u0005התחבא בבית מרחץ אחד]\u0006 שהיה מסוכן כל כך מפני המזיקים \u0003דכי הוו עיילין בתרין אפילו ביממא הוו מיתזקי\u0004 \u0005[שכאשר היו באים\u0006 בו \u0005שנים\u0006 יחד \u0005אפילו ביום היו ניזוקים].\u0006 \u0003למחר אמרו ליה רבנן\u0004 \u0005[אמרו לו חכמים]:\u0006 \u0003מאן נטרך\u0004 \u0005[מי שמר אותך]\u0006 במקום המסוכן הזה? \u0003אמר להו\u0004 \u0005[להם]:\u0006 היו שם מלאכים שנדמו כמו \u0003שני\u0004"],["\u0003נושאי קיסר\u0004 (אנשי צבא) \u0003שמרוני כל הלילה. אמרו ליה\u0004 \u0005[לו]:\u0006 \u0003שמא דבר ערוה בא לידך וניצלת הימנו,\u0004 ולכן קרה לך נס זה. \u0003דתנינא\u0004 \u0005[ששנינו]:\u0006 \u0003כל הבא דבר ערוה לידו וניצל הימנו\u0004 — \u0003עושין לו נס.\u0004 נאמר \u0003\"גברי כח עושי דברו לשמע בקול דברו\"\u0004 (תהלים קג, כ) — \u0003כגון ר' צדוק וחביריו.\u0004 ומה מעשיהם?","\u0003ר' צדוק תבעתיה ההיא מטרוניתא\u0004 \u0005[תבעה אותו גבירה אחת\u0006 לזנות\u0005],\u0006 \u0003אמר לה: חלש לי ליבאי ולא מצינא\u0004 \u0005[חלוש לבי ואיני יכול,\u0006 איני מסוגל לכך עכשו\u0005],\u0006 האם \u0003איכא מידי למיכל\u0004 \u0005[יש משהו לאכול\u0006 שאתחזק בו\u0005]?\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003איכא\u0004 \u0005[יש כאן]\u0006 \u0003דבר טמא. אמר לה: מאי נפקא מינה\u0004 \u0005מה יצא מזה]?\u0006 מה הבדל יש בדבר? \u0003דעביד הא\u0004 \u0005[\u0006מי \u0005שעושה\u0006 מעשה \u0005כזה]\u0006 — \u0003אכול הא\u0004 \u0005[אוכל\u0006 גם מאכל \u0005כזה].\u0006 \u0003שגרת תנורא, קא מנחא ליה\u0004 \u0005[הסיקה תנור\u0006 ו\u0005הניחה בו\u0006 להיצלות את האוכל האסור\u0005].\u0006 \u0003סליק ויתיב בגויה\u0004 \u0005[עלה וישב בתוך\u0006 התנור\u0005].\u0006 \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003מאי האי\u0004 \u0005[מה\u0006 פשר מעשה \u0005זה]?\u0006 \u0003אמר לה: דעביד הא\u0004 \u0005[\u0006מי \u0005שעושה\u0006 מעשה \u0005כזה]\u0006 — \u0003נפיל בהא\u0004 \u0005[נופל בזה],\u0006 כלומר, בגיהנום. \u0003אמרה ליה\u0004 \u0005[לו]:\u0006 \u0003אי ידעי כולי האי\u0004 \u0005[אילו הייתי יודעת\u0006 ש\u0005כל כך\u0006 חמור הדבר בעיניך\u0005]\u0006 — \u0003לא צערתיך\u0004 \u0005[הייתי מצערת אותך].\u0006","ועוד מסופר: \u0003רב כהנא הוה קמזבין דיקולי\u0004 \u0005[היה מוכר סלי\u0006 נשים קלועים מנצרים של דקל\u0005],\u0006 \u0003תבעתיה ההיא מטרוניתא\u0004 \u0005[תבעה אותו גבירה אחת\u0006 לזנות\u0005].\u0006 \u0003אמר לה: איזיל איקשיט נפשאי\u0004 \u0005[אלך אקשט\u0006 את \u0005עצמי]\u0006 לפני כן, \u0003סליק וקנפיל מאיגרא לארעא\u0004 \u0005[עלה\u0006 לגג \u0005ונפל מהגג לארץ].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003אליהו\u0004 הנביא \u0003קבליה\u0004 \u0005[\u0006ו\u0005קיבל אותו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 אליהו לרב כהנא: \u0003אטרחתן ארבע מאה פרסי\u0004 \u0005[הטרחת אותי ארבע מאות פרסה]\u0006 כדי לבוא אליך להצילך! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מי גרם לי\u0004 להגיע לידי מעשה זה \u0003לאו עניותא\u0004 \u0005[\u0006האם \u0005לא העניות]?\u0006 שהייתי נזקק להתעסק בעיסוק כזה עם נשים? \u0003יהב ליה שיפא דדינרי\u0004 \u0005[נתן לו\u0006 אליהו \u0005סל\u0006 מלא \u0005דינרים]\u0006 שלא יצטרך עוד לעסוק בכך.","\u0003רמי ליה\u0004 \u0005[השליך,\u0006 הראה סתירה\u0005]\u0006 \u0003רבא לרב נחמן: תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003אלו דברים שאדם עושה אותן ואוכל פירותיהן בעולם הזה והקרן קיימת לו לעולם הבא, אלו הן: כיבוד אב ואם, וגמילות חסדים, והבאת שלום שבין אדם לחבירו, ותלמוד תורה כנגד כולם.\u0004","ומה הוא המקור לכך — \u0003בכיבוד אב ואם כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"למען יאריכן ימיך ולמען ייטב לך\"\u0004 (דברים ה, טז), משמע שיש לו שכר בעולם הזה. \u0003בגמילות חסדים כתיב\u0004 \u0005[נאמר]:\u0006 \u0003\"רדף צדקה וחסד ימצא חיים צדקה וכבוד\"\u0004 (משלי כא, כא)","ומשמעות הכתוב שימצא כן בעולם הזה, \u0003ובהבאת שלום כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"בקש שלום ורדפהו\"\u0004 (תהלים לד, טו), \u0003ואמר ר' אבהו: אתיא\u0004 \u0005[באה,\u0006 נלמדת הבאת שלום\u0005]\u0006 בגזירה שווה \u0003\"רדיפה\" \"רדיפה\"; כתיב הכא\u0004 \u0005[נאמר כאן]\u0006 \u0003\"בקש שלום ורדפהו\" וכתיב התם\u0004 \u0005[ונאמר שם]\u0006 בגמילות חסדים \u0003\"רדף צדקה וחסד\"\u0004 ללמד שאף רודף השלום יזכה לחיים, צדקה וכבוד. \u0003בתלמוד תורה כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"כי הוא חייך וארך ימיך\"\u0004 (דברים ל, כ).","ושאל רבא: \u0003בשילוח הקן נמי כתיב\u0004 \u0005[גם כן נאמר]\u0006 \u0003\"למען ייטב לך והארכת ימים\"\u0004 (שם כב, ז), \u0003ליתני נמי הא\u0004 \u0005[שישנה גם כן\u0006 מצוה \u0005זו]!\u0006 ענה לו רב נחמן: \u0003תנא\u0004 \u0005[שנה]\u0006 \u0003ושייר\u0004 ולא מנה הכל. אמר לו: \u0003תני\u0004 \u0005[שנה]\u0006 ה\u0003תנא \"אלו דברים\",\u0004 כלומר, שרצה לדייק ולומר רק אלו בכלל, \u0003ואת אמרת תנא\u0004 \u0005[ואתה אומר שנה]\u0006 \u0003ושייר?!\u0004","\u0003אמר רבא: רב אידי אסברא\u0004 \u0005[הסביר]\u0006 \u0003לי\u0004 את הדבר. נאמר \u0003\"אמרו צדיק כי טוב כי פרי מעלליהם יאכלו\"\u0004 (ישעיה ג, י). ונשאלת השאלה: \u0003וכי יש צדיק טוב ויש צדיק שאינו טוב? אלא\u0004 כך יש להבין: מי שהוא \u0003טוב לשמים ו\u0004טוב \u0003לבריות\u0004 — \u0003זהו צדיק טוב,\u0004 מי ש\u0003טוב לשמים ורע לבריות\u0004 — \u0003זהו צדיק שאינו טוב.\u0004","\u0003כיוצא בדבר אתה אומר \"אוי לרשע רע כי גמול ידיו יעשה לו\"\u0004 (שם יא). \u0003וכי יש רשע רע ויש שאינו רע? אלא: רע לשמים ורע לבריות\u0004 — \u0003הוא רשע רע, רע לשמים ואינו רע לבריות\u0004 — \u0003זהו רשע שאינו רע.\u0004 ורק מי שהוא \"צדיק טוב\" שעושה מצוה שיש בה גם טובה לבריות הוא הזוכה לאכול מפירותיה בעולם הזה, ואלו הם הדברים ששנינו, מה שאין כן בשילוח הקן שאין בה טובה לבריות.","אגב כך מביאים: \u0003הזכות\u0004 (מצוה) \u0003יש לה קרן ויש לה פירות,\u0004 שמקבל שכר יתר על שכר עצם המצוה שעשה (\"קרן\") כעין פירות ורווחים, \u0003שנאמר \"אמרו צדיק כי טוב\u0004 כי פרי מעלליהם יאכלו\u0003\"\u0004 (ישעיה ג, י). \u0003עבירה יש לה קרן ואין לה פירות, שנאמר: \"אוי לרשע רע\u0004 כי גמול ידיו יעשה לו\u0003\"\u0004 (שם, שם יא) ולא יותר מזה.","\u0003ואלא מה\u0004 (איך) \u0003אני מקיים\u0004 את הפסוק הנאמר בעוברי עבירה \u0003\"ויאכלו מפרי דרכם וממעצתיהם ישבעו\"\u0004 (משלי א, לא), שמשמע שיש גם פירות לעבירה והרשע נענש גם על פירות העבירה? אלא יש לומר כך: \u0003עבירה שעושה פירות,\u0004 שיש תוצאות מעשיות לרע מן העבירה הזו, כגון שלמדים אחרים מאותו אדם לעשות כמוהו — \u0003יש לה פירות\u0004 גם לענין העונש. \u0003ו\u0004עבירה \u0003שאין עושה פירות\u0004 — \u0003אין לה פירות.\u0004","ועוד שנו: \u0003מחשבה טובה מצרפה\u0004 הקדוש ברוך הוא \u0003למעשה, שנאמר: \"אז נדברו יראי ה' איש אל רעהו ויקשב ה' וישמע ויכתב ספר זכרון לפניו ליראי ה' ולחשבי שמו\"\u0004 (מלאכי ג, טז). ומסבירים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"ולחשבי שמו\"? אמר רב אסי: אפילו חשב אדם לעשות מצוה ונאנס ולא עשאה\u0004 — \u0003מעלה\u0004 (מחשיב) \u0003עליו הכתוב כאילו עשאה\u0004 בפועל, ונזכר הדבר לפני הקדוש ברוך הוא כמצוה שנעשתה.","ואילו \u0003מחשבה רעה אין\u0004 הקדוש ברוך הוא \u0003מצרפה למעשה, שנאמר \"און אם ראיתי בלבי לא ישמע ה'\"\u0004 (תהלים סו, יח). \u0003ואלא מה\u0004 (איך) \u0003אני מקים\u0004 את האמור \u0003\"הנני מביא אל העם הזה רעה פרי מחשבותם\"\u0004 (ראה ירמיה ו, יט)? לומר: \u0003מחשבה\u0004 רעה \u0003שעושה פרי\u0004 (\"פרי מחשבותם\") ומביאה לידי מעשה \u0003הקדוש ברוך הוא מצרפה למעשה\u0004 ונענש על המחשבה, \u0003מחשבה שאין בה פרי\u0004 — \u0003אין הקדוש ברוך הוא מצרפה למעשה.\u0004","ומקשים: \u0003ואלא הא דכתיב\u0004 \u0005[זה שנאמר]\u0006 \u0003\"למען תפש את [בית] ישראל בלבם\"\u0004 (יחזקאל יד, ה), מלמד שנענשים גם על מחשבה שבלב! \u0003אמר רב אחא בר יעקב:\u0004 הכתוב \u0003ההוא בעבודה זרה הוא דכתיב\u0004 \u0005[שנאמר],\u0006 \u0003דאמר מר\u0004 \u0005[שאמר החכם]:\u0006 \u0003חמורה עבודה זרה, שכל הכופר בה כמודה בכל התורה כולה.\u0004 ולהיפך, המודה בה ככופר בכל התורה. ומפני חומרתה אף המהרהר בעבודה זרה נענש.","\u0003עולא אמר:\u0004 יש לפרש זאת \u0003כ\u0004דברי \u0003רב הונא\u0004 ש\u0003אמר רב הונא: כיון שעבר אדם עבירה ושנה בה\u0004 — \u0003הותרה לו.\u0004 מיד תוהים על לשון זו: \u0003הותרה לו סלקא דעתך\u0004 \u0005[עולה על דעתך]?!\u0006 \u0003אלא\u0004 כוונתו: \u0003נעשית לו כהיתר,\u0004 שהוא מתרגל בה ושוב אינו מרגיש שעבירה בידו.","\u0003אמר ר' אבהו משום\u0004 (בשם) \u0003ר' חנינא: נוח לו\u0004 (מוטב לו) \u0003לאדם שיעבור עבירה בסתר, ואל יחלל שם שמים\u0004 לעבור על מצות ה' \u0003בפרהסיא, שנאמר: \"ואתם בית ישראל כה אמר ה'\u0004 אלקים \u0003איש גלוליו לכו עבדו [ואחר] אם אינכם שמעים אלי, ואת שם קדשי לא תחללו\"\u0004 (יחזקאל כ, לט).","\u0003אמר ר' אלעאי הזקן: אם רואה אדם שיצרו מתגבר עליו\u0004 — \u0003ילך למקום שאין מכירין אותו, וילבש שחורים, ויתכסה שחורים,\u0004 כלומר, בגדים פשוטים ופחותים \u0003ויעשה כמו שלבו חפץ, ואל יחלל שם שמים בפרהסיא.\u0004","ותוהים: \u0003איני\u0004 \u0005[כך הוא]\u0006 הדבר? \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003כל שלא חס על כבוד קונו\u0004 — \u0003ראוי לו שלא בא לעולם.\u0004 ושאלו: \u0003מה היא,\u0004 מיהו זה שלא חס על כבוד קונו? \u0003רבה אומר: זה המסתכל בקשת,\u0004 שנאמר בה שהיא כ\"מראה כבוד ה'\" (יחזקאל א, כח). \u0003רב יוסף אומר: זה העובר עבירה בסתר,\u0004 שמגלה בכך שחושש מן הבריות אבל אינו חושש לכבוד קונו המלא את הכל. משמע שהעובר עבירה בסתר חמור יותר!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה];\u0006 \u0003הא\u0004 \u0005[זה]\u0006 שעליו נאמר שלא חס על כבוד קונו — הוא זה \u0003דמצי כייף ליצריה\u0004 \u0005[\u0006\u0005שיכול לכפות את יצרו]\u0006 ועובר עבירה בסתר, \u0003והא\u0004 \u0005[וזה]\u0006 שמוטב שיעבור עבירה בסתר — הרי זה באופן \u0003דלא מצי כייף ליצריה\u0004 \u0005[שאינו יכול לכפות את יצרו].\u0006","\u0003תנן התם\u0004 \u0005[שנינו שם]:\u0006 \u0003אין מקיפין בחילול השם, אחד שוגג ואחד מזיד.\u0004 ושואלים: \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"אין מקיפין\"? אמר מר זוטרא: שאין עושים כחנווני,\u0004 כלומר, שהוא נותן דברים בהקפה, בהלוואה על החשבון, אלא אדם נענש מיד, ללא דיחוי. \u0003מר בריה\u0004 \u0005[בנו]\u0006 של \u0003רבנא אמר: לומר שאם היתה\u0004 עבירה של חילול ה' \u0003שקולה\u0004 שעל ידה נעשו זכויותיו וחובותיו שקולים — הרי היא \u0003מכרעת\u0004 לחובה. ומפרש \"מקיפים\" במובן משווים, מדמים. שלעבירה זו אין השוואה, והיא מכרעת לחובה.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003לעולם\u0004"],["\u0003יראה אדם עצמו כאילו\u0004 הוא שקול: \u0003חציו חייב וחציו זכאי\u0004 בדיוק, וכאילו הוא במאזנים ששתי הכפות מאוזנות, ולכן אם \u0003עשה מצוה אחת\u0004 — \u0003אשריו, שהכריע\u0004 את \u0003עצמו\u0004 בכך \u0003לכף זכות, עבר עבירה אחת\u0004 — \u0003אוי לו, שהכריע את עצמו\u0004 בכך \u0003לכף חובה, שנאמר: \"וחוטא אחד יאבד טובה הרבה\"\u0004 (קהלת ט, יח), לומר: \u0003בשביל חטא יחידי שחטא אובד ממנו טובות הרבה.\u0004","\u0003ר' אלעזר בר' שמעון אומר: לפי שהעולם נידון אחר רובו\u0004 אם יש לו רוב מצוות או רוב עבירות, \u0003והיחיד נידון אחר רובו,\u0004 לכן צריך לחשוב כל אדם בלבו: אם \u0003עשה מצוה אחת\u0004 — \u0003אשריו, שהכריע את עצמו ואת כל העולם לכף זכות,\u0004 ואם \u0003עבר עבירה אחת\u0004 — \u0003אוי לו, שהכריע את עצמו ואת כל העולם לכף חובה, שנאמר: \"וחוטא אחד\u0004 יאבד טובה הרבה \u0003\"\u0004— \u0003בשביל חטא יחידי שעשה זה אבד ממנו ומכל העולם טובה הרבה.\u0004","\u0003ר' שמעון בן יוחי אומר: אפילו\u0004 היה \u0003צדיק גמור כל ימיו ומרד\u0004 (פשע ועבר) \u0003באחרונה\u0004 (בסוף ימיו) — \u0003איבד את\u0004 הזכויות \u0003הראשונות, שנאמר: \"צדקת הצדיק לא תצילנו ביום פשעו\"\u0004 (יחזקאל לג, יב). \u0003ו\u0004להיפך: \u0003אפילו\u0004 היה \u0003רשע גמור כל ימיו ועשה תשובה באחרונה\u0004 — \u0003אין מזכירים לו שוב רשעו, שנאמר: \"ורשעת הרשע לא יכשל בה ביום שובו מרשעו\"\u0004 (שם).","ושואלים: \u0003וניהוי\u0004 \u0005[ושיהיה]\u0006 זה שעשה כל ימיו מצוות ואחר כך עבר עבירה — לפחות \u0003כמחצה עונות ומחצה זכיות,\u0004 וייחשבו אלה כנגד אלה! ולמה הוא נידון לכף חובה? \u0003אמר ריש לקיש:\u0004 כאן אין מדובר במי שרק עבר עבירה אלא \u0003בתוהא\u0004 (מתחרט) \u0003על\u0004 כל המצוות \u0003הראשונות\u0004 שעשה שאז אין נחשבות לו המצוות שעשה כלל.","\u0003כל שישנו\u0004 (שיש בו) \u0003במקרא ובמשנה ובדרך ארץ,\u0004 שעושה מלאכתו ושאר מעשיו כיאות — \u0003לא במהרה הוא חוטא, שנאמר: \"והחוט המשלש לא במהרה ינתק\"\u0004 (קהלת ד, יב), שאם יש בו שלושה אלה, אינו מגיע לידי עבירה. \u0003וכל שאינו לא במקרא ולא במשנה ולא בדרך ארץ\u0004 — \u0003אינו מן היישוב,\u0004 כלומר אינו נחשב אדם כלל.","\u0003אמר ר' אלעזר בר' צדוק: למה צדיקים נמשלים בעולם הזה\u0004 — \u0003לאילן שכולו עומד במקום טהרה, ונופו\u0004 (ענפיו) \u0003נוטה למקום טומאה,\u0004 ונמצא שחלק מהאילן נמצא במקום טמא. אם \u0003נקצץ נופו\u0004 — \u0003כולו עומד במקום טהרה. כך הקדוש ברוך הוא מביא יסורים על צדיקים בעולם הזה\u0004 אם נטו קצת למקום טומאה ועבירה, ומייסר אותם (\"קוצץ נופו\") — \u0003כדי שיירשו העולם הבא\u0004 בשלימות, \u0003שנאמר: \"והיה ראשיתך מצער ואחריתך ישגה מאד\"\u0004 (איוב ח, ז).","\u0003ולמה רשעים דומים בעולם הזה\u0004 — \u0003לאילן שכולו עומד במקום טומאה ונופו נוטה למקום טהרה.\u0004 אם \u0003נקצץ נופו\u0004 — \u0003כולו עומד במקום טומאה. כך הקדוש ברוך הוא משפיע להן טובה לרשעים בעולם הזה\u0004 על מעט מצוות שעשו (\"נופו\") \u0003כדי לטורדן\u0004 (לגרשם) \u0003ולהורישן למדריגה התחתונה\u0004 לעתיד לבוא, \u0003שנאמר: \"יש דרך ישר לפני איש ואחריתה דרכי מות\"\u0004 (משלי יד, יב).","כיון שהוזכרו במשנה זו וקודמתה מעלות התורה, מביאים מעשה זה: \u0003וכבר היה ר' טרפון וזקנים מסובין בעלית בית נתזה בלוד. נשאלה שאילה\u0004 (שאלה) \u0003זו בפניהם: תלמוד גדול או מעשה גדול? נענה ר' טרפון ואמר: מעשה גדול. נענה ר' עקיבא ואמר: תלמוד גדול. נענו כולם ואמרו: תלמוד גדול\u0004 אבל לא מצד עצמו, אלא מפני \u0003שהתלמוד מביא לידי מעשה.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי אומר: גדול תלמוד\u0004 תורה \u0003שקדם ל\u0004מצות \u0003חלה ארבעים שנה,\u0004 שתורה ניתנה לישראל מיד בצאתם ממצרים ובמצות חלה נתחייבו רק בבואם לארץ. וקדם \u0003ל\u0004מצות \u0003תרומות ולמעשרות חמשים וארבע\u0004 שנים שלא נתחייבו בהן אלא לאחר ארבע עשרה שנים של כיבוש וחלוקת הארץ אחר כניסתם לארץ. \u0003לשמיטים\u0004 (מצות שמיטה) \u0003ששים ואחת\u0004 שנה, שרק לאחר חלוקת הארץ החלו למנות את השנים עד לשנה השביעית. \u0003ליובלות מאה ושלש\u0004 שאף מנין היובל הראשון החל רק מסוף חלוקת הארץ.","ותוהים: מדוע אמר \u0003מאה ושלש\u0004 שנים? הלא \u0003מאה וארבע הויין\u0004 \u0005[הן]\u0006 שיש להוסיף חמישים שנה על חמישים וארבע השנים שמהן החלו לקיים מצוות התלויות בארץ! ומשיבים: \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 כי \u0003יובל מתחילתו\u0004 (מתחילת השנה) \u0003הוא משמט\u0004 לענין שילוח עבדים והחזרת קרקעות, ולכן עברו מאה ושלש שנים עד שחלה מצות היובל.","\u0003וכשם שהלימוד קודם למעשה,\u0004 כלומר, שמצות הלימוד קודם למצוות אחרות, \u0003כך דינו\u0004 של אדם בדין של מעלה, שנידון על לימוד תורה \u0003קודם\u0004 לדין שנידון על \u0003מעשה\u0004 המצוות, \u0003כ\u0004דברי \u0003רב המנונא.\u0004 ש\u0003אמר רב המנונא: אין תחילת דינו של אדם אלא על דברי תורה, שנאמר: \"פוטר מים ראשית מדון\"\u0004 (משלי יז, יד) שהוא מפרש שעל עוון ביטול תורה, (\"פוטר מים\"), שפטר עצמו מתורה, ואין מים אלא תורה, היא ראשית דינו (\"מדון\").","\u0003וכשם שדינו\u0004 של תלמוד תורה \u0003קודם ל\u0004דין של כל \u0003מעשה\u0004 אחר — \u0003כך שכרו קודם ל\u0004שכר \u0003מעשה, שנאמר: \"ויתן להם ארצות גוים ועמל לאמים יירשו. בעבור ישמרו חקיו ותורתיו ינצרו\"\u0004 (תהלים קה, מד–מה), שתשלום השכר הראשון הוא על שמירת החוקים והתורות — לימוד התורה.","שנינו במשנה \u0003כל שאינו לא במקרא ולא במשנה\u0004 ולא בדרך ארץ אינו מן הישוב. \u0003אמר ר' יוחנן: ופסול לעדות,\u0004 שאינו בגדר בני אדם שאפשר לסמוך עליהם. \u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 \u0003האוכל בשוק הרי זה דומה לכלב,\u0004 שהוא מזלזל בעצמו ואינו מתבייש לאכול בכל מקום. \u0003ויש אומרים\u0004 שהוא אף \u0003פסול לעדות. אמר ר' אידי בר אבין: הלכה כיש אומרים.\u0004","וכעין הדברים הללו \u0003דרש בר קפרא: רגזן\u0004"],["\u0003לא עלתה בידו\u0004 (הצליח להשיג) \u0003אלא רגזנותא\u0004 \u0005[רגזנות],\u0006 שאין כל תועלת באה לו מן הרוגז, ואין נשאר בידו אלא עצם הרוגז שרגז. \u0003ולאדם טוב מטעימים אותו מפרי מעשיו. וכל\u0004 אדם \u0003שאינו לא במקרא ולא במשנה ולא בדרך ארץ — דור\u0004 (נדור) \u0003הנאה,\u0004 קבל עליך שלא תיהנה \u0003ממנו\u0004 ואל תתעסק עימו כלל, \u0003שנאמר: \"ובמושב לצים לא ישב\"\u0004 (תהלים א, א), כי \u0003מושבו\u0004 של אדם כזה הוא בהכרח \u0003מושב לצים,\u0004 שהרי אין לו במה לעסוק אלא בדברים בטלים.","","\u0003האיש מקדש\u0004 את האשה \u0003בו,\u0004 כלומר, הוא בעצמו, \u0003ו\u0004כן \u0003בשלוחו\u0004 על ידי שליח. וכן \u0003האשה מתקדשת בה\u0004 בעצמה, \u0003ובשלוחה. האיש מקדש את בתו כשהיא נערה, בו ובשלוחו.\u0004","תחילה תוהים על לשון המשנה: \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אמרה המשנה ש\u0003בשלוחו מקדש, בו מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 שיכול לקדש אותה בעצמו?! \u0003אמר רב יוסף:\u0004 יש בדברי המשנה הדגשה במה שנאמר \"בו\" וגם \"בשלוחו\" לקבוע סדר שהוא קודם לשלוחו, לומר \u0003מצוה בו יותר מבשלוחו.\u0004 כי אף שהקידושין חלים בכל מקרה, מכל מקום ראוי שתיעשה המצוה על ידו ולא על ידי שליח. \u0003כי הא\u0004 \u0005[כמו\u0006 מעשה \u0005זה]\u0006 ש\u0003רב ספרא מחריך רישא\u0004 \u0005[היה חורך\u0006 את \u0005ראש]\u0006 הבהמה בעצמו בערב שבת להכינו לכבוד שבת, \u0003רבא מלח שיבוטא\u0004 \u0005[היה מולח דג שיבוטה]\u0006 כדי לקיים בעצמו את המצוה להכין צרכי שבת, אף שהמלאכה יכולה היתה להיעשות על ידי אחרים.","\u0003איכא דאמרי\u0004 \u0005[יש שאומרים]:\u0006 \u0003בהא איסורא נמי אית\u0004 \u0005[ב\u0006מצוה \u0005זאת,\u0006 קידושין, \u0005איסור גם כן יש]\u0006 \u0003בה\u0004 אם מקדש אשה על ידי שליח, \u0003כ\u0004דברי \u0003רב יהודה אמר רב.\u0004 ש\u0003אמר רב יהודה אמר רב: אסור לאדם שיקדש את האשה עד שיראנה, שמא יראה בה\u0004 לאחר הקדושין \u0003דבר מגונה, ותתגנה עליו\u0004 וישנאנה, \u0003ורחמנא אמר\u0004 \u0005[והתורה אמרה]\u0006 \u0003\"ואהבת לרעך כמוך\"\u0004 (ויקרא יט, יח) וכדי שלא יגיע למכשול בדבר זה אמרו שיקדש הוא אותה בעצמו וכך יראנה ויחליט אם נאה היא בעיניו. \u0003ו\u0004לפי שיטה זו \u0003כי איתמר\u0004 \u0005[כאשר נאמרה]\u0006 שמועה זו של \u0003רב יוסף\u0004 שמצוה בו יותר מבשלוחו שמשמע שרק מצוה לכתחילה שיעשה בעצמו — \u0003אסיפא איתמר\u0004 \u0005[על סופו,\u0006 על הקטע האחרון של המשנה \u0005נאמר],\u0006 שאמרנו ש\u0003האשה מתקדשת בה ובשלוחה.\u0004 ויש לשאול: \u0003השתא\u0004 \u0005[עכשיו]\u0006 הרי \u0003בשלוחה מיקדשא\u0004 \u0005[\u0006היא \u0005מתקדשת]\u0006 \u0003בה\u0004 עצמה \u0003מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]?!\u0006 ועל כך \u0003אמר רב יוסף: מצוה בה יותר מבשלוחה. כי הא\u0004 \u0005[כמו זו]\u0006 שאמרנו ש\u0003רב ספרא מחריך רישא\u0004 \u0005[היה חורך ראש\u0006 בהמה\u0005]\u0006 ו\u0003רבא מלח שיבוטא\u0004 \u0005[היה מולח דג שיבוטה]\u0006 לכבוד שבת.","","\u0003אבל בהא איסורא לית\u0004 \u0005[בזה,\u0006 כשממנה האשה שליח לקידושיה, \u0005איסור אין]\u0006 \u0003בה.\u0004 וטעמו של דבר — \u0003כ\u0004דברי \u0003ריש לקיש,\u0004 ש\u0003אמר ריש לקיש:\u0004 פתגם הוא שאומרות הנשים: \u0003טב למיתב טן דו מלמיתב ארמלו\u0004 \u0005[טוב לשבת בשנים מלשבת אלמנה,\u0006 בודדה\u0005],\u0006 לומר שהאשה אינה מקפידה כל כך ומסתפקת אף בגבר שיש בו איזה פגם ולכן אף אם תתקדש על ידי שליח ולא תראה לפני כן את בעלה, אין לחשוש שיתגנה בעיניה ותשנאנו.","שנינו במשנה ש\u0003האיש מקדש את בתו כשהיא נערה.\u0004 ונדייק מכאן: \u0003כשהיא נערה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003כשהיא קטנה\u0004 — \u0003לא. מסייע ליה\u0004 \u0005[לו]\u0006 הדבר \u0003לרב,\u0004 ש\u0003אמר רב יהודה אמר רב ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' אלעזר: אסור לאדם שיקדש את בתו כשהיא קטנה, עד שתגדל ותאמר \"בפלוני אני רוצה\".\u0004 כי אם מקדש אותה כשהיא קטנה ואין בה דעת — שמא לכשתגדל לא תרצה בו, ונמצאת נשואה לאדם שאינו כלבבה.","במשנה זו נאמרו דינים ביחס לשליחות, שיפה כוח השליח גם לגבי קידושין. ושואלים: גופו של דין ה\u0003שליחות מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003דתניא\u0004 \u0005[שכן\u0006 \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נאמר בתורה בדין גירושי אשה \"ושלחה מביתו\" (דברים כד, א) ומתוך שלא נקט בלשון גירושין אלא בלשון \u0003\"ושלח\"\u0004 — הרי זה \u0003מלמד שהוא,\u0004 הבעל, \u0003עושה שליח,\u0004 שאינו צריך לתת לה גט בעצמו.","וממה שנאמר \u0003\"ושלחה\"\u0004 — \u0003מלמד\u0004 על ידי הכתיב (שאפשר לקרוא \"ושלחה\" ללא מפיק ה\"א) \u0003ש\u0004גם \u0003היא\u0004 האשה \u0003עושה שליח\u0004 לקבל את גיטה, ומפני שנאמר באותו ענין פעמיים \u0003\"ושלח\" \"ושלחה\"\u0004 (שם ג) — \u0003מלמד ש\u0004אף \u0003השליח עושה שליח.\u0004","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו\u0006 איפוא שיש דין שליחות\u0005]\u0006 \u0003בגירושין, בקידושין מנלן\u0004 \u0005[מניין לנו]?\u0006 \u0003וכי תימא דיליף\u0004 \u0005[ואם תאמר ש\u0006הוא \u0005לומד]\u0006 דבר זה \u0003מגירושין\u0004 שכשם שיוצאת מבעלה, כך גם נכנסת אליו לרשותו על ידי שליח, אולם אין הדברים דומים בדיניהם: שהרי \u0003מה לגירושין\u0004 — \u0003שכן ישנן בעל כרחה,\u0004 וכיון שיכול אדם לגרש את אשתו בעל כרחה שמא יפה כוחו לעשות זאת גם על ידי שליח, מה שאין כן בקידושין שהם מרצונה בלבד. ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"ויצאה\u0004 מביתו והלכה \u0003והיתה\u0004 לאיש אחר\u0003\"\u0004 (שם ב), \u0003מקיש\u0004 \u0005[משווה]\u0006 הפסוק הזה \u0003הויה,\u0004 קניינה של אשה לאיש, כלומר, קידושין, \u0003ליציאה,\u0004 לגירושין; \u0003מה\u0004 לצורך \u0003יציאה משוי\u0004 \u0005[עושה,\u0006 ממנה\u0005]\u0006 המגרש \u0003שליח\u0004 — \u0003אף\u0004 לענין \u0003הויה נמי\u0004 \u0005[גם כן]\u0006 \u0003משוי\u0004 \u0005[ממנה]\u0006 \u0003שליח.\u0004","ושואלים: \u0003ואלא הא דתנן\u0004 \u0005[זו ששנינו\u0006 במשנה\u0005]:\u0006 \u0003האומר לשלוחו \"צא תרום\"\u0004 עבורי תרומה מתבואת שדי — \u0003תורם\u0004 השליח \u0003כדעת בעל הבית\u0004 לפי השיעור שרוצה בעל הבית לתת. שיש הנותנים בעין יפה — אחד מארבעים, ויש בעין רעה אחד משישים. \u0003ואם אינו יודע\u0004 מהי \u0003דעת בעל הבית\u0004 — \u0003תורם ב\u0004מידה \u0003בינונית,\u0004 שהיא \u0003אחד מחמשים\u0004 מן היבול."],["\u0003פיחת עשרה או הוסיף עשרה,\u0004 שנתן יותר מהכמות או פחות מהכמות — \u0003תרומתו תרומה. מנלן\u0004 \u0005[מניין לנו]\u0006 שאפשר למנות שליח לתרומה? \u0003וכי תימא דיליף\u0004 \u0005[ואם תאמר ש\u0006הוא \u0005לומד]\u0006 דבר זה \u0003מגירושין\u0004 — אולם אפשר להקשות על השוואה זו: \u0003מה לגירושין שכן ישנן\u0004 (נחשבות) \u0003חול\u0004 לגבי תרומה, ואין ללמוד מכאן שתועיל שליחות בתרומה שיש בה קדושה! ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 בענין תרומה \"כן תרימו גם אתם\" (במדבר יח, כח), שהרי יכול לכתוב רק \u0003\"אתם\",\u0004 והריבוי \u0003\"גם אתם\"\u0004 בא \u0003לרבות את השליח.\u0004","ושואלים: \u0003ונכתוב רחמנא\u0004 \u0005[ותכתוב התורה]\u0006 שליחות \u0003בתרומה, וניתו הנך ונגמרו מיניה\u0004 \u0005[ויבואו אלה,\u0006 קידושין וגירושין, \u0005ויילמדו ממנה]\u0006 שגם בהם יש שליחות! ומשיבים: \u0003משום דאיכא למפרך\u0004 \u0005[שיש מקום לפרוך,\u0006 לשבור\u0005]\u0006 את ההשוואה, ולומר: שונה תרומה \u0003שכן ישנה\u0004 בה צד להקל, שאפשר להפרישה גם \u0003במחשבה,\u0004 שאין צורך דווקא במעשה הפרשה ודי אם הוא חושב ומחליט בליבו על כך, ומשום כך מובן מדוע נעשית גם על ידי שליח, מה שאין כן בקידושין וגירושין.","ועוד שואלים: \u0003והא דתנן\u0004 \u0005[וזה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003חבורה\u0004 של בני אדם שנמנו להשתתף בקרבן פסח \u0003שאבד פסחה\u0004 (הבהמה שהקדישו לקרבן פסח), \u0003ואמרו לאחד\u0004 מהם: \u0003צא ובקש\u0004 (חפש) \u0003ושחוט עלינו\u0004 (עבורנו) את הבהמה הזו, \u0003והלך ו\u0004אכן \u0003מצא\u0004 את הבהמה \u0003ושחט. והן\u0004 שראו בינתיים שהוא אינו מגיע \u0003לקחו\u0004 (קנו) בהמה אחרת לקרבן פסח \u0003ושחטו\u0004 אותה, \u0003אם שלו נשחט ראשון\u0004 — \u0003הוא אוכל משלו,\u0004 מזה שמצא, \u0003והם\u0004 שאר בני החבורה \u0003אוכלים ושותים עמו.\u0004 ומכאן למדים שהוא נעשה שליח עבורם לשחיטת הפסח.","\u0003מנלן\u0004 \u0005[מניין לנו]\u0006 דין זה של שליחות בקדשים? \u0003וכי תימא דיליף מהנך\u0004 \u0005[ואם תאמר ש\u0006הוא \u0005לומד מאלו,\u0006 כלומר, מגירושין ומתרומה\u0005]\u0006 — יש להקשות על השוואה זו: \u0003מה להנך\u0004 \u0005[לאלו]\u0006 \u0003שכן ישנן\u0004 (נחשבים הם) ל\u0003חול אצל\u0004 (לגבי) \u0003קדשים!\u0004 וכיצד ילמד מהם לגבי קדשים?!","ומשיבים: \u0003נפקא ליה\u0004 \u0005[יוצא לו]\u0006 הדבר \u0003מ\u0004דברי \u0003ר' יהושע בן קרחה.\u0004 ש\u0003אמר ר' יהושע בן קרחה: מנין ששלוחו של אדם כמותו\u0004 — \u0003שנאמר\u0004 בקרבן הפסח: \u0003\"ושחטו אתו כל קהל עדת ישראל בין הערבים\"\u0004 (שמות יב, ו). ויש לשאול: \u0003וכי כל הקהל כולן שוחטין? והלא אינו שוחט אלא אחד\u0004 מתוך כל חבורה! \u0003אלא מכאן ששלוחו של אדם כמותו. ו\u0004אולם מעתה יש מקום לשאול:","\u0003נכתוב רחמנא\u0004 \u0005[שתכתוב התורה]\u0006 דין שליחות רק \u0003בקדשים וניתי הנך וניגמרו מיניה\u0004 \u0005[ויבואו אלה,\u0006 קידושין גירושין ותרומה, \u0005ויילמדו ממנה]!\u0006 ומשיבים: \u0003משום דאיכא למפרך\u0004 \u0005[שיש\u0006 מקום \u0005לפרוך,\u0006 לשבור\u0005]\u0006 השוואה זו ולומר: \u0003מה לקדשים\u0004 — \u0003שכן רוב מעשיהן על ידי שליח,\u0004 שרוב עבודות הקדשים נעשים על ידי הכהן שהוא שליח, ולכן אין ללמוד מהם דין שליחות לעניינים אחרים.","ושואלים עוד: אמנם \u0003חדא מחדא לא אתיא\u0004 \u0005[אחת מאחת אינה באה],\u0006 כלומר, אי אפשר ללמוד כל אחת מן ההלכות הללו מן ההלכה האחרת, שכפי שהוכחנו יש הבדל בין הדינים ויש צד של יחוד בכל אחד מהם, ואולם \u0003תיתי חדא מתרתי\u0004 \u0005[תבוא,\u0006 תילמד, הלכה \u0005אחת משתים\u0006 האחרות\u0005]?\u0006 ודוחים: \u0003הי תיתי\u0004 \u0005[איזו תבוא\u0006 ותילמד משתים האחרות\u0005]?\u0006","אם נאמר ש\u0003לא נכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 דין שליחות \u0003בקדשים ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה],\u0006 גירושין ותרומה, אולם אז יש לדחות ולומר \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן ישנן חול אצל קדשים,\u0004 ואף תרומה נחשבת כחול לגבי קדשים. ואם תאמר ש\u0003לא נכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 דין שליחות \u0003בגירושין, ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה],\u0006 מתרומה וקדשים, הרי אפשר לדחות: \u0003מה להנך\u0004 \u0005[לאלה]\u0006 \u0003שכן ישנן במחשבה\u0004 שאף בקדשים אם הקדיש במחשבתו, חל ההקדש.","\u0003אלא\u0004 כך יש לשאול: ש\u0003לא לכתוב רחמנא\u0004 \u0005[תכתוב התורה]\u0006 דין שליחות \u0003בתרומה, ותיתי מהנך\u0004 \u0005[ותבוא,\u0006 תילמד \u0005מאלה],\u0006 מקדשים וגירושין, שאם מבחינת היותה קודש — הרי קדשים קדושים ממנה ובכל זאת יש בהם שליחות, ואם מצד שניטלת במחשבה — אף בקדשים מחשבה מועילה! ומשיבים: \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 הוא הדבר, ואכן זהו המקור לדין שליחות בתרומה.","ושואלים: \u0003ואלא\u0004 אם כן ריבוי זה שלמדנו מ\u0003\"אתם\" \"גם אתם\" למה לי?\u0004 ומשיבים: \u0003מיבעי ליה\u0004 \u0005[צריך אותו]\u0006 \u0003ל\u0004כמו שאמר \u0003ר' ינאי.\u0004 ש\u0003אמר ר' ינאי\u0004 שלמדים מ\u0003\"גם אתם\"\u0004 לא את עצם דין השליחות, אלא את פרטי דיניה: \u0003מה אתם\u0004 המשלחים \u0003בני ברית\u0004 (יהודים) — \u0003אף שלוחכם\u0004 צריכים להיות \u0003בני ברית,\u0004 שגוי אינו יכול להפריש תרומה בשליחות ישראל.","ושואלים: \u0003הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 \u0003למה לי קרא\u0004 \u0005[פסוק]\u0006 עבורו? \u0003מ\u0004דברי \u0003ר' חייא בר אבא אמר ר' יוחנן נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005]\u0006 הדבר, ש\u0003אמר ר' חייא בר אבא אמר ר' יוחנן: אין העבד נעשה שליח לקבל גט\u0004 לאשה \u0003מיד בעלה של אשה, לפי שאינו בתורת גיטין וקידושין.\u0004 משמע שיש הלכה כללית שמי שאינו בכלל הדינים השייכים בנושא מסויים אף אינו יכול לשמש שליח לאותו דבר, וכיון שאין גויים מצווים להפריש תרומה — ממילא אינם יכולים להיות שליחים להפרשתה!","ומשיבים: מכל מקום \u0003איצטריך\u0004 \u0005[נצרך]\u0006 לימוד זה בתרומה, ואין דין זה נלמד מדברי ר' ינאי, כי \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003עבד דלאו בר היתירא\u0004 \u0005[שלא בר היתר]\u0006 \u0003הוא כלל,\u0004 שאין בו דין גירושין כלל, הוא שאינו יכול להיות שליח בהם, \u0003אבל גוי, הואיל ואיתיה בתרומה דנפשיה\u0004 \u0005[וישנו בתרומה של עצמו]\u0006 שיש מעין דין תרומה גם בגוי, \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003הגוי והכותי שתרמו\u0004 מרצונם מתבואתם שלהם — \u0003תרומתן תרומה\u0004 למרות שאינם מצווים על כך, אם כן \u0003אימא\u0004 \u0005[אמור]\u0006 ש\u0003שליח נמי עביד\u0004 \u0005[גם כן\u0006 הוא \u0005עושה],\u0006 על כן \u0003קמשמע לן\u0004 \u0005[השמיע לנו]\u0006 הפסוק \"גם אתם\" שצריך השליח בתרומה להיות בן ברית ולא גוי.","ושואלים: \u0003ול\u0004דעת \u0003ר' שמעון\u0004 ש\u0003פטר\u0004 בתרומת גוי. \u0003דתנן\u0004 \u0005[ששנינו\u0006 במשנה\u0005]:\u0006 \u0003תרומת גוי מדמעת,\u0004 שאם נתערבה בחולין — הרי היא אוסרת אותם כדין תרומה מעורבת ואם אכל זר את התרומה הזו בשוגג \u0003חייבין עליה\u0004 תוספת \u0003חומש ור' שמעון פוטר\u0004 לגמרי, מפני שהוא סבור שאין כל קדושה בתרומת הגוי, ואם נתנה לכהן הרי היא נחשבת כמתנה בלבד. ולשיטתו הריבוי \u0003\"אתם\" \"גם אתם\" למה לי,\u0004 והרי למדנו כבר דין שליחות מקדשים וגירושין?","ומשיבים: \u0003איצטריך\u0004 \u0005[צריך]\u0006 הדבר להיאמר; \u0003סלקא דעתך אמינא\u0004 \u0005[יעלה על דעתך לומר]:\u0006 \u0003הואיל ואמר מר\u0004 \u0005[החכם]\u0006 שיש לראות במלה \"אתם\" הדגשה והגבלה לומר: דווקא \u0003אתם\u0004 תורמים \u0003ולא אריסין\u0004 בחלקו של בעל הבית, וכן דווקא \u0003\"אתם\" ולא שותפין,\u0004 בנכסים המשותפים שלא מדעת השותף, \u0003\"אתם\" ולא אפוטרופוס\u0004 בנכסי היתומים, \u0003\"אתם\" ולא התורם את שאינו שלו\u0004 — \u0003אימא\u0004 \u0005[אמור]\u0006 כעין זה: \u0003\"אתם\" ולא שלוחכם נמי\u0004 \u0005[גם כן],\u0006 על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 \"גם אתם\" לרבות השליח.","לעצם הלימוד של שליחות מקדשים שואלים: \u0003הניחא\u0004 \u0005[זה נוח]\u0006 כל זה \u0003ל\u0004דעת \u0003ר' יהושע בן קרחה\u0004 שמפרש את הכתוב \"ושחטו אותו כל קהל עדת ישראל...\" (שמות יב, ו) בענין קרבן פסח ללמוד ממנו דין שליחות בקדשים, \u0003אלא לר' יונתן דמפיק ליה להאי קרא לדרשא אחרינא,\u0004 \u0003מנא לן\u0004 \u0005[שמוציא אותו, את הפסוק הזה לדרשה אחרת מניין לנו]\u0006 דין שליחות בקדשים? ומה אמר ר' יונתן — \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005],\u0006 \u0003ר' יונתן אומר: מנין שכל ישראל כולן יוצאים\u0004 ידי חובה"],["\u0003ב\u0004קרבן \u0003פסח אחד\u0004 שאף כשיש רק קרבן פסח אחד ולא ייתכן שכל אחד יאכל ממנו כזית — בכל אופן כלל ישראל יוצאים בו ידי חובה בעצם הקרבתו — \u0003שנאמר\u0004 בנוגע לקרבן הפסח: \u0003\"ושחטו אתו כל קהל עדת ישראל בין הערבים\"\u0004 (שמות יב, ו), \u0003וכי כל הקהל כולם שוחטים? והלא אינו שוחט אלא אחד! אלא מכאן שכל ישראל יוצאים\u0004 ידי חובה \u0003ב\u0004קרבן \u0003פסח אחד\u0004 ואין אכילתו מעכבת. וכיון שמכתוב זה הוא לומד שפעמים מקריבים רק קרבן אחד — \u0003שליח בקדשים מנא ליה\u0004 \u0005[מניין לו]?\u0006","ומשיבים: \u0003מיניה\u0004 \u0005[ממנו,\u0006 מאותו פסוק עצמו\u0005],\u0006 שהרי אחד שוחט עבור כולם. ודוחים: \u0003ודילמא שאני התם\u0004 \u0005[ושמא שונה שם]\u0006 \u0003דאית ליה\u0004 \u0005[שיש לו,\u0006 לשליח\u0005]\u0006 \u0003שותפות בגוייהו\u0004 \u0005[בתוכם]\u0006 בקרבן, וכיון שכולם שותפים מובן כיצד אחד יכול לשחוט עבור כולם, מה שאין כן בסתם שליח שאינו שותף בדבר.","\u0003אלא מהכא\u0004 \u0005[מכאן]\u0006 הוא למד, שנאמר בקרבן פסח: \u0003\"ויקחו להם איש שה לבית אבת שה לבית\"\u0004 (שם ג), הרי שאחד לוקח ושוחט עבור כל בית האב, המשפחה. ומקשים: \u0003ודילמא התם נמי דאית ליה\u0004 \u0005[ושמא שם גם כן\u0006 מפני \u0003שיש]\u0004 \u0003שותפות בגוייהו\u0004 \u0005[בתוכם]?\u0006 ודוחים: \u0003אם כן תרי קראי\u0004 \u0005[שני כתובים]\u0006 \u0003למה לי\u0004 לומר אותו דבר? אלא \u0003אם\u0004 הדין האמור בפסוק \u0003אינו ענין להיכא\u0004 \u0005[להיכן]\u0006 שהוא \u0003שייך,\u0004 כלומר, דווקא בשליח שיש לו שותפות בדבר, \u0003תניהו ענין\u0004 (שיך אותו) \u0003להיכא\u0004 \u0005[להיכן]\u0006 שהוא \u0003לא שייך,\u0004 וגם כשאין לו שותפות בדבר יוכל להיות שליח.","ודוחים: \u0003האי מיבעי ליה\u0004 \u0005[\u0006פסוק \u0005זה נצרך לו\u0006 לענין אחר\u0005],\u0006 \u0003ל\u0004למוד כמו שאמר \u0003ר' יצחק.\u0004 ש\u0003אמר ר' יצחק:\u0004 מפסוק זה למדים ש\u0003איש,\u0004 כלומר, מבוגר דווקא \u0003זוכה\u0004 עבור אחרים \u0003ולא הקטן זוכה.\u0004 ומשיבים: \u0003ההוא\u0004 \u0005[אותו]\u0006 דין שדווקא איש זוכה \u0003מ\"איש לפי אכלו\u0004 תכוסו על השה\u0003\"\u0004 (שם ד) \u0003נפקא\u0004 \u0005[יוצא,\u0006 נלמד\u0005].\u0006","ומוסיפים להקשות: \u0003ואכתי מיבעי ליה\u0004 \u0005[ועדיין צריך אותו]\u0006 כתוב \"איש לפי אכלו\" לענין אחר: ש\u0003שוחטין את הפסח על היחיד,\u0004 ואין חובה דווקא שיהיה \"שה לבית אבות\" כאמור בפסוק הקודם, אלא אפילו איש אחד שוחט לעצמו (\"תכוסו על השה\")? ומשיבים: \u0003סבר לה כמאן דאמר\u0004 \u0005[סבור הוא\u0006 ר' יונתן \u0005כמי שאומר]:\u0006 \u0003אין שוחטין את הפסח על היחיד.\u0004","ושואלים מצד אחר: \u0003ואלא הא\u0004 \u0005[זה]\u0006 ש\u0003אמר רב גידל אמר רב: מנין ששלוחו של אדם כמותו\u0004 — \u0003שנאמר: \"ונשיא אחד נשיא אחד ממטה\u0004 תקחו לנחול את הארץ\u0003\"\u0004 (במדבר לד, יח) \u0003תיפוק ליה שליחות מהכא\u0004 \u0005[תצא,\u0006 תלמד, \u0005לו\u0006 שליחות \u0005מכאן],\u0006 מחלוקת הארץ על ידי הנשיאים שהיו שלוחי המטות (השבטים) בחלוקת הנחלות, ואין צורך במקורות האחרים! ודוחים: \u0003ותיסברא דהא\u0004 \u0005[וסבור אתה שזה]\u0006 שעשו הנשיאים מחמת \u0003שליחות הוא\u0004 שעשו כן? \u0003והא\u0004 \u0005[והרי]\u0006 \u0003קטנים לאו\u0004 \u0005[\u0006ש\u0005לא]\u0006 \u0003בני שליחות נינהו\u0004 \u0005[הם],\u0006 שאינם יכולים למנות שליח, ואילו הנשיאים זיכו את הנחלות לכל בני שבטם, גם לגדולים וגם לקטנים!","\u0003אלא\u0004 חלוקת הנחלות על ידי הנשיאים נעשתה מטעם אחר, \u0003כי הא\u0004 \u0005[כמו זה]\u0006 שאמר \u0003רבא בר רב הונא.\u0004 ש\u0003אמר רבא בר רב הונא אמר רב גידל אמר רב: מנין שזכין לאדם שלא בפניו\u0004 — \u0003שנאמר: \"ונשיא אחד נשיא אחד\"\u0004 וכו', ואין זה מדין שליחות. ומקשים: \u0003ותיסברא\u0004 \u0005[וסבור אתה]\u0006 ש\u0003זכות היא? הא\u0004 \u0005[הרי]\u0006 \u0003חובה נמי איכא\u0004 \u0005[גם כן יש]\u0006 בכך, \u0003דאיכא דניחא ליה\u0004 \u0005[שיש שנוח לו]\u0006 שתהיה חלקתו \u0003בהר,\u0004 \u0003ולא ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003בבקעה, ואיכא דניחא ליה\u0004 \u0005[ויש שנוח לו]\u0006 \u0003בבקעה ולא ניחא ליה\u0004 \u0005[נוח לו]\u0006 \u0003בהר!\u0004 ואילו לאחר חלוקת הארץ על ידי הנשיאים לא יכלו הנוחלים לערער.","\u0003ואלא\u0004 את הפסוק צריך לענין אחר \u0003כ\u0004דברי \u0003רבא בר רב הונא.\u0004 ש\u0003אמר רבא בר רב הונא אמר רב גידל אמר רב: מנין ליתומים שבאו לחלוק בנכסי אביהן שבית דין מעמידין להם אפוטרופוס לחוב ולזכות.\u0004 ולפני עצם הדיון בנושא מבררים את הלשון: \u0003לחוב אמאי\u0004 \u0005[מדוע]?\u0006 לשם מה בית דין מעמידים אפוטרופוס כדי לחייב את היתומים! \u0003אלא\u0004 הכוונה היא: \u0003לחוב על מנת לזכות,\u0004 שמאחר שנתמנה לדאוג לנכסי היתומים יכול הוא לעשות דבר שהוא לחובתם על מנת שתצא להם זכות ממנו לאחר זמן. ומהיכן למדים את הדבר — \u0003תלמוד לומר\u0004 ממה שנאמר: \u0003\"ונשיא אחד נשיא אחד ממטה תקחו\".\u0004","באותו ענין של אפוטרופוס ליתומים \u0003אמר רב נחמן אמר שמואל: יתומים שבאו לחלוק בנכסי אביהם\u0004 — \u0003בית דין מעמידים להם אפוטרופוס, ובוררים להם,\u0004 לכל בן, \u0003חלק יפה, ואם הגדילו\u0004 — \u0003יכולים\u0004 היתומים \u0003למחות\u0004 בחלוקה, ולומר שאינם רוצים חלוקה זו. \u0003ורב נחמן דידיה\u0004 \u0005[משלו]\u0006 \u0003אמר: אם הגדילו אינם יכולים למחות,\u0004 ש\u0003אם כן\u0004 שיכולים למחות \u0003מה כח בית דין\u0004 שמינה את האופוטרופסים, \u0003יפה?\u0004","ושואלים: \u0003ומי אית ליה\u0004 \u0005[והאם יש לו]\u0006 \u0003לרב נחמן\u0004 סברה זו של \u0003\"אם כן מה כח בית דין יפה\"? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003שום\u0004 (הערכה) של \u0003הדיינים,\u0004 שהעריכו את נכסיו של לווה שלא בפניו או שלא מדעתו כדי לגבות מהם חוב שלא שולם, \u0003שפיחתו\u0004 בהערכתם \u0003שתות\u0004 (ששית) \u0003או הותירו\u0004 (הוסיפו) \u0003שתות\u0004 על הערך האמיתי — \u0003מכרן בטל\u0004 משום שטעות ביותר מששית מבטלת את האומדן. \u0003רבן שמעון בן גמליאל אומר: מכרן קיים. ואמר רבן שמעון בן גמליאל:\u0004 ש\u0003אם כן\u0004 אתה אומר שמכרם בטל — \u0003מה כח בית דין יפה\u0004 יותר מסתם אדם! \u0003ואמר רב הונא בר חיננא אמר רב נחמן: הלכה כדברי חכמים.\u0004 ומשמע שאינו מקבל את הנימוק של \"מה כוח בית דין יפה\"!","ומשיבים: \u0003לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006"],["\u0003הא\u0004 \u0005[זה]\u0006 שפסק רב נחמן כחכמים האומרים שאין דינם דין, כלומר, אין אומרים \"מה כוח בית דין יפה\" הרי זה מדובר באופן ש\u0003טעו\u0004 בית הדין בשתות, \u0003הא\u0004 \u0005[זה]\u0006 שפסק רב נחמן שאין היתומים יכולים למחות משהגדילו מכיון שאומרים \"מה כוח בית דין יפה\" מדובר באופן ש\u0003לא טעו\u0004 בשתות. ושואלים: \u0003אי\u0004 \u0005[אם]\u0006 מדובר באופן ש\u0003לא טעו, מאי\u0004 \u0005[מה]\u0006 אם כן טעמו של שמואל האומר ש\u0003יכולים למחות\u0004 לאחר מכן, ועל מה ימחו? ומשיבים: \u0003יכולים למחות ב\u0004חלוקת ה\u0003רוחות\u0004 (צדדים), שיש להם ענין להחליף את מיקומם של חלקי השדה שקיבלו בירושה.","\u0003אמר רב נחמן: האחין שחלקו\u0004 בנכסי ירושתם \u0003הרי הן כלקוחות,\u0004 שנידונים כאילו היו קונים זה מזה, ודינם לענין אונאה שווה לשאר קונים. ולכן, אם היתה בחלוקה טעות \u0003פחות משתות\u0004 — \u0003נקנה\u0004 ה\u0003מקח.\u0004 ואם היתה הטעות \u0003יתר על שתות\u0004 — \u0003בטל\u0004 ה\u0003מקח\u0004 כולו. ואם היתה הטעות בדיוק \u0003שתות\u0004 — \u0003קנה,\u0004 כלומר, החלוקה קיימת, \u0003ומחזיר\u0004 מי שקיבל יותר מן המגיע לו את ההפרש, כדין \u0003אונאה.\u0004","\u0003אמר רבא: הא דאמרן\u0004 \u0005[זה שאמרנו]\u0006 כי בטעות \u0003פחות משתות נקנה\u0004 ה\u0003מקח\u0004 — \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 דווקא באופן ש\u0003לא שויה\u0004 \u0005[עשה,\u0006 מינה \u0005אותו]\u0006 אחד מן הלקוחות או האחים \u0003שליח\u0004 לחלוק במקומו, \u0003אבל\u0004 אם \u0003שויה\u0004 \u0005[עשה,\u0006 מינה \u0005אותו]\u0006 \u0003שליח\u0004 — אינו כן, כי \u0003אמר\u0004 \u0005[אומר]\u0006 המשלח: \u0003לתקוני שדרתיך\u0004 \u0005[לתקן שלחתיך]\u0006 \u0003ולא לעוותי\u0004 \u0005[לקלקל]\u0006 ואם עשה דבר שאינו מתוקן אפילו הוא פחות משתות — שוב אינו נידון לענין זה כשליח.","\u0003והא דאמרן\u0004 \u0005[וזה שאמרנו]\u0006 כי בטעה ב\u0003יתר משתות בטל\u0004 ה\u0003מקח\u0004 — \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 באופן ש\u0003לא אמר \"ניפליגן בשומא דבי דינא\"\u0004 \u0005[\"נחלוק בשומה\u0006 כמו \u0005של בית דין\"],\u0006 \u0003אבל\u0004 אם \u0003אמר \"נפלוג בשומא דבי דינא\"\u0004 \u0005[\"נחלוק בשומה של בית דין\"]\u0006 — \u0003מכרן קיים. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003שום הדיינים שפיחתו שתות או הותירו שתות\u0004 — \u0003מכרן בטל. רבן שמעון בן גמליאל אומר: מכרן קיים.\u0004 והלכה כמותו, שיפה כוח בית דין אף אם טעו.","\u0003והא דאמרן\u0004 \u0005[וזה שאמרנו]\u0006 כי כאשר טעה ב\u0003שתות קנה ומחזיר אונאה\u0004 — \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 כן \u0003אלא\u0004 דווקא כשהיתה האונאה \u0003במטלטלי\u0004 \u0005[במטלטלין]\u0006 \u0003אבל\u0004 אם היתה זו אונאה \u0003במקרקעי\u0004 \u0005[בקרקעות],\u0006 כלל הוא כי \u0003אין אונאה לקרקעות. ו\u0004גם \u0003במקרקעי\u0004 \u0005[בקרקעות]\u0006 \u0003לא אמרן\u0004 \u0005[אמרנו]\u0006 שאין דין אונאה, \u0003אלא\u0004 דווקא \u0003דפלוג בעילויא\u0004 \u0005[שחילקו לפי ערך\u0006 הקרקע\u0005],\u0006 \u0003אבל\u0004 אם \u0003פלוג במשחתא\u0004 \u0005[חילקו במידה]\u0006 וטעו בכך — \u0003לא\u0004 אומרים שאין אונאה. ו\u0003כ\u0004דברי \u0003רבה.\u0004 ש\u0003אמר רבה: כל דבר ש\u0004הוא טעות \u0003במדה,\u0004 או \u0003במשקל,\u0004 או \u0003במנין, אפילו\u0004 היתה הטעות \u0003פחות מכדי אונאה,\u0004 כלומר, פחות משישית — \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003חוזר.\u0004","וממשיכים בדיון כללי בדיני שליחות. שואלים: \u0003והא דתנן\u0004 \u0005[וזה ששנינו\u0006 במשנה\u0005]:\u0006 \u0003השולח את הבעירה\u0004 (דבר שגרם לשריפה) \u0003ביד חרש שוטה וקטן\u0004 — \u0003פטור\u0004 השולח \u0003מדיני אדם, וחייב בדיני שמים.\u0004 ואם \u0003שילח ביד פיקח\u0004 — ה\u0003פיקח חייב\u0004 ולא שולחו.","\u0003ואמאי\u0004 \u0005[ומדוע]\u0006 חייב השליח? \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003שלוחו של אדם כמותו!\u0004 ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 ש\u0003אין שליח לדבר עבירה. דאמרינן\u0004 \u0005[שאנו אומרים]:\u0006 \u0003דברי הרב ודברי תלמיד\u0004 — \u0003דברי מי שומעים?\u0004 שצריך היה השליח לשמוע בקולו של הקדוש ברוך הוא, שאסר את הדבר, ולא בקולו של המשלח, ולכן נחשב השליח כאילו עשה מדעת עצמו, ואין אחריות מוטלת על המשלח.","ומקשים: \u0003והדתניא\u0004 \u0005[וזו ששנינו\u0006 ברייתא\u0005]\u0006 בדיני מעילה: \u0003שליח שלא עשה שליחותו,\u0004 ששינה מכפי שציווה אותו המשלח, ובמה שעשה היה משום שימוש בחפץ של הקדש (מעילה) — \u0003שליח מעל\u0004 והוא החייב בקרבן (\"אשם מעילות\"). אבל אם \u0003עשה\u0004 השליח \u0003שליחותו\u0004 — \u0003בעל הבית מעל.\u0004 ומכל מקום \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003עשה\u0004 השליח \u0003שליחותו\u0004 של \u0003בעל הבית\u0004 — \u0003בעל הבית מיהא\u0004 \u0005[על כל פנים]\u0006 \u0003מעל.\u0004 ויש לשאול: \u0003אמאי\u0004 \u0005[מדוע]?\u0006 \u0003נימא\u0004 \u0005[נאמר]:\u0006 \u0003אין שליח לדבר עבירה!\u0004","ומשיבים: במעילה יש דין מיוחד; \u0003שאני מעילה, דילפא\u0004 \u0005[שונה\u0006 היא \u0005מעילה, שלמדה]\u0006 דין זה בגזירה שווה \u0003\"חטא\" \"חטא\" מתרומה; מה תרומה משוי\u0004 \u0005[עושה,\u0006 ממנה\u0005]\u0006 \u0003שליח\u0004 — \u0003אף מעילה משוי\u0004 \u0005[עושה,\u0006 ממנה\u0005]\u0006 \u0003שליח\u0004 ואף שהוא דבר עבירה.","ושואלים: \u0003ונילף מינה\u0004 \u0005[ונלמד ממנה]\u0006 ממעילה הלכה כללית, שיש שליח אף לדבר עבירה! ומשיבים: \u0003משום דהוי\u0004 \u0005[שהריהם]\u0006 \u0003מעילה ושליחות יד,\u0004 כלומר, גניבת דבר שנמסר לאדם בפקדון, ועובר על כך גם אם נעשה על ידי שלוחו, \u0003שני כתובים הבאים כאחד,\u0004 שבשניהם יש דין שליח לדבר עבירה, \u0003וכל שני כתובים הבאים כאחד אין מלמדין\u0004 לגבי מקרים אחרים. ומסבירים: \u0003מעילה\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו].\u0006 \u0003שליחות יד מאי\u0004 \u0005[מה]\u0006 \u0003היא?\u0004","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 על מה שנאמר בתורה לגבי הנחשד בשליחת יד בפקדון לשון ריבוי \u0003\"על כל דבר פשע\"\u0004 (שמות כב, ח), \u0003בית שמאי אומרים:\u0004 הרי ריבוי זה בא \u0003לחייב על\u0004 הדיבור ו\u0003המחשבה\u0004 (\"כל דבר\") \u0003כמעשה. ובית הלל אומרים: אינו חייב עד שישלח בו יד\u0004 ממש, \u0003שנאמר: \"אם לא שלח ידו\u0004 במלאכת רעהו","\u0003\"\u0004(שם י). \u0003אמרו בית שמאי לבית הלל: והלא נאמר \"על כל דבר פשע\",\u0004 משמע שבדיבור בלבד מתחייב! \u0003אמרו להם בית הלל לבית שמאי: והלא נאמר \"אם לא שלח ידו במלאכת רעהו\"! אמרו בית שמאי לבית הלל: אם כן \"על כל דבר פשע\" למה לי?\u0004 ומשיבים בית הלל: \u0003שיכול אין לי אלא\u0004 אם \u0003הוא\u0004 עצמו שלח יד, אבל אם \u0003אמר לעבדו\u0004 או \u0003לשלוחו\u0004 שישלח בו יד \u0003מנין\u0004 שהוא גם כן חייב — \u0003תלמוד לומר: \"על כל דבר פשע\",\u0004 שמתחייב השולח על ההוראה שנתן לשליחו.","ושואלים עוד: מה שתירצנו שמעילה ושליחות יד הם שני כתובים הבאים כאחד \u0003הניחא\u0004 \u0005[זה נוח]\u0006 \u0003ל\u0004דעת \u0003בית הלל. אלא לבית שמאי דמוקמי ליה להאי קרא\u0004 \u0005[שמעמידים את הכתוב הזה]\u0006 שכוונתו לחייב בעבירה זו \u0003במחשבה כמעשה,\u0004 ואינם למדים מכאן שבשליחות יד עושה אדם שליח, אם כן"],["\u0003נילף מיניה\u0004 \u0005[נלמד ממנו]\u0006 ממעילה שיש שליחות לדבר עבירה! ומשיבים: \u0003משום דהוה\u0004 \u0005[שהריהן]\u0006 \u0003מעילה\u0004 וכן דין \u0003טביחה ומכירה\u0004 של בהמות שגנב \u0003שני כתובים הבאים כאחד, וכל שני כתובים הבאים כאחד אין מלמדין.\u0004 ומסבירים: שליחות ב\u0003מעילה\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 מקודם, \u0003טביחה ומכירה מאי\u0004 \u0005[מה]\u0006 \u0003היא,\u0004 מהו עניינו? \u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 \u0003\"וטבחו או מכרו\"\u0004 (שמות כא, לז) ויש בכך השוואת מכירה לטביחה: \u0003מה מכירה\u0004 נעשית בהכרח \u0003על ידי אחר,\u0004 שהרי בכל מכירה צריך להיות צד שני, הקונה — \u0003אף טביחה\u0004 הנעשית גם \u0003על ידי אחר\u0004 שהוא שליחו, נחשבת למשלח כמעשהו, ומתחייב עליה.","\u0003דבי\u0004 \u0005[\u0006החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' ישמעאל תנא\u0004 \u0005[שנה]\u0006 ולמד זאת ממה שנאמר: \"וטבחו או מכרו\", \u0003\"או\"\u0004 זה לשון ריבוי הוא ובא \u0003לרבות את השליח. דבי\u0004 \u0005[\u0006החכם \u0005בבית\u0006 מדרשו\u0005]\u0006 של \u0003חזקיה תנא\u0004 \u0005[שנה]:\u0006 מה שנאמר בטביחה ומכירה \"חמישה בקר ישלם תחת השור וארבע צאן תחת השה\" (שם) אחת מן המלים \u0003\"תחת\"\u0004 מיותרת ובאה \u0003לרבות את השליח,\u0004 שלא רק הגנב עצמו, אלא אף השליח שממנה תחתיו (בשליחותו), מחייב אותו.","על כך שואלים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006תירוץ \u0005זה נוח ל\u0006דעת \u0005מי שאומר]\u0006 \u0003שני כתובים הבאים כאחד אין מלמדין, אלא למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 שאף הם \u0003מלמדין, מאי איכא למימר\u0004 \u0005[מה יש לומר]?\u0006 ומדוע לא נלמד דין שליח לדבר עבירה ממעילה ומטביחה ומכירה לכל העבירות כולן! ומשיבים: \u0003גלי רחמנא\u0004 \u0005[גילתה התורה]\u0006 שאין לומר שליח לדבר עבירה \u0003בשחוטי חוץ,\u0004 באדם השוחט קרבן מחוץ לבית המקדש, שנאמר בו \u0003\"דם יחשב לאיש ההוא דם שפך\"\u0004 (ויקרא יז, ד) ויש בכתוב הדגשה \"לאיש ההוא\", שכוונתה: \u0003הוא\u0004 בלבד חייב על מעשהו שעשה \u0003ולא\u0004 על מה שעשה \u0003שלוחו.\u0004","ושואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 דין זה שאין שליח לדבר עבירה \u0003גבי\u0004 איסור של \u0003שחוטי חוץ,\u0004 אך \u0003בכל התורה מנלן\u0004 \u0005[מניין לנו]?\u0006 ומשיבים: \u0003דיליף\u0004 \u0005[שלומד]\u0006 \u0003משחוטי חוץ\u0004 הלכה כללית, בבנין אב.","ומקשים: \u0003אדיליף\u0004 \u0005[עד ש\u0006הוא \u0005לומד]\u0006 \u0003משחוטי חוץ\u0004 שאין שליח לדבר עבירה, \u0003ניליף מהנך\u0004 \u0005[שילמד מאלה]\u0006 (מעילה וטביחה ומכירה) שמפורש בהן שיש שליח לדבר עבירה! ומשיבים: \u0003הדר כתב רחמנא\u0004 \u0005[חזרה\u0006 ו\u0005כתבה התורה]\u0006 באיסור שחוטי חוץ הדגשה זו שנית \u0003\"ונכרת האיש ההוא\"\u0004 (שם), \u0003אם אינו ענין לגופו,\u0004 לשוחט בחוץ, שכבר נאמר קודם שאינו מתחייב אלא הוא ולא שליחו — \u0003תנהו ענין לכל התורה כולה,\u0004 שמתחייב רק העושה במעשהו שלו, ולא במעשה שליחו.","ושואלים: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003שני כתובים הבאים כאחד אין מלמדים, הני\u0004 \u0005[אותם]\u0006 הכתובים \u0003\"ההוא\" \"ההוא\"\u0004 שבאים למעט, \u0003מאי דריש בהו\u0004 \u0005[מה\u0006 הוא \u0005דורש בהם],\u0006 שהרי לשיטתו אין בהם צורך לענין שליח לדבר עבירה שהרי לומדים זאת מסברה? ומשיבים: \u0003חד למעוטי\u0004 \u0005[\u0006כתוב \u0005אחד\u0006 בא \u0005למעט]\u0006 \u0003שנים שאוחזים בסכין ושוחטים\u0004 שחוטי חוץ יחד שאין שניהם מתחייבים, משום שנאמר \"האיש ההוא\" — ולא שנים. \u0003וחד\u0004 \u0005[ו\u0006כתוב \u0005אחד]\u0006 בא להדגיש: \u0003\"הוא\"\u0004 — \u0003ולא אנוס\u0004 לשחוט, \u0003\"הוא\"\u0004 — \u0003ולא שוגג,\u0004 שלא ידע שאיסור הוא לשחוט בחוץ, \u0003\"הוא\"\u0004 — \u0003ולא מוטעה,\u0004 כגון שלא ידע שקרבן הוא. כלומר, האיש ההוא בשלימות דעתו ורצונו, רק כך מתחייב.","ושואלים: \u0003ואידך\u0004 \u0005[והאחר]\u0006 שלומד מ\"ההוא\" לשלול שליחות לדבר עבירה, מניין יודע הוא הלכות אלו? ומשיבים: לומד הוא זאת ממה שהיה יכול לכתוב במקרא רק \u0003\"הוא\"\u0004 וכתב \u0003\"ההוא\",\u0004 שהיא תוספת הדגשה ללימוד אחר. \u0003ואידך\u0004 \u0005[והאחר]\u0006 שלמד הלכות אלו מעצם הייתור של המלה \"ההוא\", את הייתור \u0003\"הוא\" \"ההוא\" לא דריש\u0004 \u0005[אינו דורש]\u0006 אינו סבור שיש לו משמעות כדי לדרוש ממנו.","ושואלים: \u0003והא דתני\u0004 \u0005[וזו ששנויה]:\u0006 \u0003האומר לשלוחו \"צא הרוג את הנפש\", הוא,\u0004 ההורג — \u0003חייב, ושולחיו\u0004 — \u0003פטור. שמאי הזקן אומר משום חגי הנביא: שולחיו חייב, שנאמר\u0004 לדוד על שגרם להריגת אוריה: \u0003\"\u0004ו\u0003אתו הרגת בחרב בני\u0004 \u0003עמון\"\u0004 (שמואל ב יב, ט).","ושואלים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003שמאי הזקן?\u0004 כיצד יכול הוא לומר שיש שליח לדבר עבירה? ומשיבים: \u0003קסבר\u0004 \u0005[סבור]\u0006 הוא: \u0003שני כתובים הבאים כאחד מלמדין,\u0004 ולכן למד ממעילה וטביחה ומכירה שיש שליח לדבר עבירה, \u0003ו\u0004את המיעוט של \u0003\"הוא\" \"ההוא\" לא דריש\u0004 \u0005[אינו דורש].\u0006 \u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003לעולם\u0004 תאמר ש\u0003דריש\u0004 \u0005[דורש]\u0006 דרשה זו, ואף הוא סבור שאין שליח לדבר עבירה, \u0003ו\u0004אולם \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003חייב\u0004 שאמר שמאי — \u0003חייב בדיני שמים.\u0004 שאף שאין המשלח לדבר עבירה חייב בדיני אדם, מכל מקום חייב הוא כלפי הקדוש ברוך הוא.","ותוהים: האם \u0003מכלל\u0004 הדברים תאמר שה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003סבר\u0004 ש\u0003אפילו מדיני שמים נמי\u0004 \u0005[גם כן]\u0006 \u0003פטור?!\u0004 והרי המשלח מעורב בעבירה זו, ויש לו חלק בה! \u0003אלא:\u0004 גם לתנא הראשון חייב המשלח בדיני שמים, ולגבי \u0003דינא רבה ודינא זוטא איכא בינייהו\u0004 \u0005[דין גדול ודין קטן יש ביניהם\u0006 הבדל\u0005],\u0006 שלדעת שמאי יש עליו חיוב גדול, שהוא נחשב בדיני שמים כאחראי גמור לדבר, ולדעת אחרים אין חיובו חמור כל כך.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 לכל הדעות, אין שליח לדבר עבירה, ופטור המשלח, אלא שלדעת שמאי \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 (מעשה אוריה החתי) \u0003דגלי רחמנא\u0004 \u0005[שגילתה התורה]\u0006 \u0003\"\u0004ו\u0003אתו הרגת בחרב בני עמון\"\u0004 הרי שדוד נתחייב במפורש בעבירה זו.","\u0003ואידך\u0004 \u0005[והאחר]\u0006 שאינו סבור שהמשלח חייב מפרש את הפסוק: \u0003הרי לך\u0004 הריגת אוריה החתי \u0003כחרב בני עמון\u0004 עצמה, \u0003מה חרב בני עמון אין אתה נענש עליו,\u0004 על אלה שנהרגו כדרכם במלחמה זו — \u0003אף אוריה החתי אי\u0004 (אין) \u0003אתה נענש עליו\u0004 כלל אפילו בידי שמים. \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — \u0003מורד במלכות הוה\u0004 \u0005[היה]\u0006 אוריה ומן הדין היה חייב מיתה, \u0003דקאמר ליה\u0004 \u0005[שאמר לו]\u0006 לדוד המלך \u0003\"ואדני יואב ועבדי אדני על פני השדה חנים\"\u0004 (שם יא, יא) וכיון שקרא ליואב \"אדוני\" בפני המלך, הרי זה כמודיע שיואב הוא עבורו מקור הסמכות ויש בכך מרד במלך.","\u0003אמר רבא: אם תמצי לומר\u0004 ותגיע למסקנה כי \u0003סבר שמאי שני כתובים הבאים כאחד מלמדין, ו\"הוא\" ההוא\" לא דריש\u0004 \u0005[אינו דורש]\u0006 ואם כן בכל הדינים יש שליח לדבר עבירה, \u0003מודה\u0004 גם הוא \u0003באומר לשלוחו \"צא בעול את הערוה\"\u0004 או שאמר לו \u0003\"\u0004צא \u0003אכול את החלב\" שהוא,\u0004 השליח, \u0003חייב, ושולחיו פטור.\u0004 והטעם — \u0003שלא מצינו בכל התורה כולה\u0004 דין ש\u0003זה\u0004 (השליח) \u0003נהנה וזה\u0004 (השולח) \u0003מתחייב\u0004 על הנאת השליח.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה, \u0003רב אמר: שליח נעשה עד.\u0004 כלומר, מי שנתמנה שליח לאיזה דבר — יכול להיות גם עד על מה שעושה. \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא אמרי\u0004 \u0005[אמרו]:\u0006 \u0003אין שליח נעשה עד.\u0004 ושואלים: \u0003מאי טעמא דבי\u0004 \u0005[מה הטעם של בני בית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003משום\u0004 ש\u0003לא אמר ליה\u0004 \u0005[לו]\u0006 המשלח לשליח \u0003\"הוי\u0004 (היה) \u0003לי עד\"\u0004 — \u0003אלא מעתה\u0004 מי ש\u0003קידש אשה בפני שנים, ולא אמר להם \"אתם עדיי\"\u0004 — \u0003הכי נמי דלא הוו קידושי\u0004 \u0005[כך גם כן\u0006 סבורים הם \u0005שאינם קידושין]?\u0006 הלא ודאי אין צורך שייחד עדים כדי להעיד!","\u0003אלא\u0004 כך צריך לומר, \u0003רב אמר: שליח נעשה עד\u0004 — \u0003אלומי קא מאלימנא למילתיה\u0004 \u0005[מחזקים אנו את דבריו]\u0006 שהוא מעיד על דבר שבטוח בו, שהרי הוא עצמו עשאו. \u0003דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא אמרי\u0004 \u0005[אמרו]:\u0006 \u0003אין שליח נעשה עד,\u0004 וטעמם — \u0003כיון\u0004 ש\u0003אמר מר\u0004 \u0005[החכם]\u0006 \u0003\"שלוחו של אדם כמותו\"\u0004 — \u0003הוה ליה כגופיה\u0004 \u0005[הרי הוא\u0006 השליח \u0005כגופו]\u0006 של המשלח, וכמו שהוא עצמו אינו נאמן להעיד בדבר הנוגע לגופו — כך שלוחו אינו מעיד.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 לרב: \u0003אמר לשלשה \"צאו וקדשו לי\u0004 את \u0003האשה\"\u0004 — \u0003אחד\u0004 מהם הוא ה\u0003שליח\u0004 לקידושין \u0003ושנים\u0004 מהם נעשים \u0003עדים,\u0004 אלו \u0003דברי בית שמאי. ובית הלל אומרים: כולם שלוחין הן, ואין שליח נעשה עד,\u0004 וצריכים שני עדים אחרים. ונדייק: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 בית שמאי ובית הלל \u0003אלא בשלשה,\u0004 שמפני שהיו יותר משנים מסתבר לומר שמינה אחד מהם לשליח והאחרים לעדים. \u0003אבל בשנים\u0004 — \u0003דברי הכל לא\u0004 נעשים השליחים עדים!","ומשיבים: \u0003הוא\u0004 (רב), \u0003דאמר כי האי תנא\u0004 \u0005[שאמר כ\u0006דעת \u0005תנא זה],\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003ר' נתן אומר, בית שמאי אומרים:\u0004 בשנים — \u0003שליח ועד אחד\u0004 יכולים להצטרף ולהיות עדים בדבר. \u0003ובית הלל אומרים: שליח ושני עדים.\u0004 ותוהים: אם כן \u0003ו\u0004כי תאמר ש\u0003רב כבית שמאי?!\u0004 ומתרצים: \u0003איפוך\u0004 \u0005[הפוך]\u0006 את השיטות, שבית הלל הם האומרים שליח ועד אחד. \u0003ורב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רבא מתני איפכא\u0004 \u0005[היה שונה\u0006 את מחלוקת האמוראים \u0005להיפך]:\u0006 \u0003רב אמר: אין שליח נעשה עד, דבי\u0004 \u0005[בבית\u0006 מדרשו\u0005]\u0006 של \u0003ר' שילא אמרי\u0004 \u0005[אמרו]:\u0006 \u0003שליח נעשה עד.\u0004 ומסכמים \u0003והילכתא\u0004 \u0005[והלכה\u0006 היא\u0005]:\u0006 \u0003שליח נעשה עד.\u0004","\u0003אמר רבא אמר רב נחמן:\u0004 על פי הדברים הללו, \u0003אמר לשנים \"צאו וקדשו לי את האשה\"\u0004 — \u0003הן הן שלוחיו\u0004 לקידושין, \u0003הן הן עדיו,\u0004 ואינו זקוק לעדים אחרים. \u0003וכן בגירושין,\u0004 שאם שלח גט לאשתו על ידי שנים — הם השליחים והם העדים שנתגרשה."],["\u0003וכן בדיני ממונות,\u0004 שאם שלח שליחים לעשות עבורו פעולה בענייני ממונות כגון ששלחם למלווה לפרוע לו את חובו — מעידים הם על הפרעון.","ומעירים: \u0003וצריכא\u0004 \u0005[וצריך]\u0006 היה לפרט את ההלכה בכל המקרים הללו; \u0003דאי אשמעינן\u0004 \u0005[שאם היה משמיע לנו]\u0006 רק \u0003בקידושין,\u0004 היינו אומרים כי יכולים הם להיות עדים בדבר \u0003משום דלמיסרה קאתי\u0004 \u0005[שלאסור אותה\u0006 לכולם הם \u0005באים]\u0006 בעדותם, ואין סיבה לומר שישקרו, שאין הם נוגעים בדבר שהרי אסורים הם בה לפי עדותם. \u0003אבל\u0004 ב\u0003גירושין\u0004 — \u0003ניחוש\u0004 \u0005[נחשוש]\u0006 \u0003שמא עיניו נתן בה\u0004 השליח, ומעיד שקר כדי שיוכל לשאתה.","\u0003ואי אשמעינן\u0004 \u0005[ואם היה משמיע לנו]\u0006 רק ב\u0003גירושין\u0004 שהשליחים נאמנים — משום שאין לחשוד בהם שהם מעידים שקר \u0003משום דאיתתא לבי תרי לא חזיא\u0004 \u0005[שאשה לשנים אינה ראויה],\u0006 וכיון ששנים הם המעידים, אין לחשוד בהם שמא עיניהם נתנו בה. \u0003אבל ממונא\u0004 \u0005[ממון]\u0006 — \u0003אימא: הני מיפלג פלגי\u0004 \u0005[אמור\u0006 ש\u0005אלה מחלקים]\u0006 ביניהם את הכסף, ובאמת לא פרעו את החוב ולקחו את הכסף לעצמם. על כן \u0003צריכי\u0004 \u0005[צריכים]\u0006 כל הדברים להיאמר, שבכל מקרה הם נאמנים להעיד.","ושואלים: \u0003מאי קסבר\u0004 \u0005[מה סבור]\u0006 רב נחמן? \u0003אי קסבר\u0004 \u0005[אם סבור\u0006 הוא\u0005]\u0006 ש\u0003המלוה\u0004 את \u0003חבירו בעדים צריך\u0004 הלווה \u0003לפורעו בעדים\u0004 — \u0003הני\u0004 \u0005[אלה]\u0006 השליחים \u0003נוגעים בעדות נינהו\u0004 \u0005[הם],\u0006 \u0003דאי אמרי \"לא פרעניה\"\u0004 \u0005[שאם יאמרו \"לא פרענו לו\"]\u0006 \u0003אמר להו\u0004 \u0005[אומר להם]\u0006 המשלח: \u0003פרעוני\u0004 פרעו אתם לי והחזירו לי את הכסף שנתתי לכם כפרעון החוב ולא יהיו נאמנים לומר שהחזירו ללווה, ולכן הם מעידים בשקר שפרעו!","\u0003אלא לעולם קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003המלוה את חבירו בעדים אין צריך לפורעו בעדים, ומגו דיכלי למימר\u0004 \u0005[ומתוך ש\u0006הם \u0005יכולים לומר]\u0006 \u0003\"אהדרינהו\u0004 \u0005[החזרנו אותו],\u0006 את הכסף, \u0003ללוה\"\u0004 ואין צריכים להביא עדים על כך, כדין המלווה את חבירו, \u0003יכולין\u0004 אף \u0003למימר\u0004 \u0005[לומר]\u0006 \u0003\"פרעניה למלוה\"\u0004 \u0005[פרענו\u0006 את החוב \u0005למלו\u0006 \u0005וה]\u0006 ולכן אין הם נוגעים בעדות.","ומעירים: \u0003והשתא דתקון רבנן\u0004 \u0005[ועכשיו\u0006 בדורות אחרונים \u0005שתיקנו חכמים]\u0006 \u0003שבועת היסת,\u0004 שהכופר בתביעת חבירו חייב להשבע על כך — נעשו עדים אלו שוב נוגעים בעדותם. שהרי אם היה טוען המלוה שלא קיבל את חובו צריכים היו להשבע ללוה שהחזירו לו את כספו. ומשום כך אין עדותם עדות, אלא \u0003משתבעי הני\u0004 \u0005[נשבעים אלו]\u0006 ה\u0003עדים \"דיהיבנא ליה\"\u0004 \u0005[\"שנתנו לו\"]\u0006 למלווה, \u0003ומשתבע\u0004 \u0005[ונשבע]\u0006 כנגדם ה\u0003מלוה\u0004 ש\u0003לא שקיל ליה\u0004 \u0005[נטל,\u0006 קיבל, \u0005אותו,\u0006 את החוב\u0005]\u0006 \u0003ופרע ליה\u0004 \u0005[ופורע לו]\u0006 \u0003לוה למלוה\u0004 את החוב שנית, כמו שפסקו חכמים במקרים דומים.","שנינו במשנה: \u0003\"האיש מקדש את בתו\u0004 כשהיא נערה\". \u0003תנן התם\u0004 \u0005[שנינו שם\u0006 במשנה\u0005]:\u0006 \u0003נערה המאורסה\u0004 — \u0003היא ואביה\u0004 (או אביה) \u0003מקבלין את גיטה. אמר ר' יהודה: אין שתי ידים זוכות כאחד,\u0004 כלומר, לא ייתכן לומר שיש זכות שווה לשני אנשים בדבר אחד שאם הנערה נחשבת כאישיות משפטית עצמאית שיכולה לזכות — אין עוד מקום לאביה בכך. ולהיפך, אם אין לה זכות בעצמה — רק אביה יכול לזכות. \u0003אלא, אביה\u0004 בלבד \u0003מקבל את גיטה. וכל שאין יכולה לשמור את גיטה\u0004 מפני קטנותה או חוסר דעתה — \u0003אין יכולה להתגרש,\u0004 שאין גט תופס אלא בזו שמבינה מעט שיש בגירושין משום ניתוק הקשר, וזו שאינה בת דעת כלל אי אפשר לגרשה.","\u0003אמר ריש לקיש: כמחלוקת לגירושין\u0004 בנערה אם היא ואביה מקבלים את גיטה או אביה בלבד, \u0003כך מחלוקת לקידושין. ור' יוחנן אמר: מחלוקת לגירושין, אבל לקידושין דברי הכל\u0004 — \u0003אביה ולא היא.\u0004","\u0003ואמר ר' יוסי בר' חנינא: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוחנן אליבא דרבנן\u0004 \u0005[לפי\u0006 דעת \u0005חכמים]?\u0006 — שכן הוא מסביר: \u0003גירושין,\u0004 ש\u0003מכנסת עצמה\u0004 על ידי הגירושין שוב \u0003לרשות אביה,\u0004 נחשב הדבר כאילו האב זכה בגט על ידי בתו ו\u0003בין היא ובין אביה\u0004 יכולים לקבל את הגט. ואילו \u0003קידושין,\u0004 ש\u0003מפקעת עצמה מרשות אביה,\u0004 הרי היא אינה יכולה להפקיע את עצמה מדעתה בלבד, ורק \u0003אביה\u0004 יכול להוציאה מרשותו \u0003ולא היא.\u0004","ומקשים: \u0003והרי מאמר\u0004 (קידושי כסף שעושה יבם ביבמה) ש\u0003מפקעת עצמה\u0004 היבמה \u0003מרשות אביה\u0004 מדברי סופרים, \u0003ותנן\u0004 \u0005[ושנינו\u0006 במשנה\u0005]:\u0006"],["\u0003קטנה\u0004 שנתאלמנה \u0003מן האירוסין\u0004 ויש לה יבם — \u0003אין עושים בה מאמר אלא מדעת אביה. והנערה\u0004 — \u0003בין מדעת עצמה בין מדעת אביה, (מה שאין כן בקידושין).\u0004 הרי שהנערה יכולה לקבל מאמר מדעת עצמה למרות שהיא מפקעת את עצמה בכך מרשות אביה!","\u0003אלא אי איתמר, הכי איתמר\u0004 \u0005[אם נאמר\u0006 הדבר, \u0005כך נאמר]:\u0006 \u0003אמר ר' יוסי בר' חנינא: מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003ר' יוחנן אליבא דרבנן\u0004 \u0005[לפי\u0006 שיטת \u0005חכמים]?\u0006 — \u0003קידושין\u0004 שאינם חלים אלא \u0003מדעתה,\u0004 ברצונה של המתקדשת — \u0003אביה\u0004 יכול לקבלם \u0003ולא היא,\u0004 שהרי הקידושין תלויים בדעתו. אבל \u0003גירושין,\u0004 ש\u0003בעל כרחה\u0004 של האשה באים ואינם צריכים את דעתה כלל — \u0003בין היא בין אביה\u0004 יכולים לקבלם.","ומקשים: \u0003הרי מאמר\u0004 שגם הוא חל רק \u0003מדעתה\u0004 כשאר קידושין, \u0003וקתני\u0004 \u0005[ושנינו\u0006 בו\u0005]:\u0006 \u0003בין היא ובין אביה!\u0004 ומשיבים: \u0003התם\u0004 \u0005[שם]\u0006 מדובר \u0003במאמר\u0004 שנעשה \u0003בעל כרחה, ו\u0004שיטת \u0003רבי היא. דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 יבם \u0003העושה מאמר ביבמתו שלא מדעתה, רבי אומר: קנה\u0004 אותה היבם בכך, \u0003וחכמים אומרים לא קנה.\u0004","ומסבירים: \u0003מאי טעמיה\u0004 \u0005[מה טעמו]\u0006 של \u0003רבי?\u0004 — \u0003גמר\u0004 \u0005[לומד]\u0006 הוא את הדבר \u0003מביאה\u0004 שעושה היבם ב\u0003יבמה; מה ביאה\u0004 של \u0003יבמה\u0004 אפילו \u0003בעל כרחה\u0004 קונה אותה בכך — \u0003אף הכא נמי\u0004 \u0005[כאן גם כן\u0006 במאמר\u0005]\u0006 קונה את יבמתו \u0003בעל כרחה. ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003ילפינן\u0004 \u0005[לומדים אנו]\u0006 דין מאמר \u0003מקידושין; מה קידושין\u0004 בכלל הרי נעשים רק \u0003מדעתה\u0004 — \u0003אף הכא נמי\u0004 \u0005[כאן,\u0006 במאמר, \u0005גם כן]\u0006 נעשים דווקא \u0003מדעתה.\u0004","ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]\u0006 מה היסוד העקרוני של מחלוקת זו ומדוע כל אחד מהם מדמה לדבר אחר? ומסבירים: \u0003רבי סבר\u0004 \u0005[סבור]\u0006 \u0003מילי\u0004 \u0005[דברים]\u0006 של \u0003יבמה מיבמה הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 והרי עיקר הקשר של היבמה ביבם אינו תלוי מרצונה אלא גם בעל כרחה. \u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 \u0003קידושין מקידושין הוה ליה למילף\u0004 \u0005[היה לו ללמוד],\u0006 שהרי מאמר ביבמה דין קידושין יש לו ככל קידושי אשה.","ומעירים: \u0003הכי נמי מסתברא כדקא\u0004 \u0005[כך גם כן מסתבר\u0006 לומר \u0005כפי]\u0006 ש\u0003מתרץ\u0004 \u0003ר' יוחנן, מדקתני סיפא\u0004 \u0005[ממה ששנה בסוף\u0006 הברייתא העוסקת במאמר ביבמה\u0005]:\u0006 \u0003\"מה שאין כן בקידושין\",\u0004 שמתקדשת דווקא מדעת אביה. ושואלים: \u0003אלא נימא\u0004 \u0005[נאמר]\u0006 \u0003תיהוי תיובתא\u0004 \u0005[תהיה\u0006 זו \u0005קושיה חמורה]\u0006 ל\u0003ריש לקיש?\u0004 הסבור שלדעת חכמים גם נערה מקבלת קידושיה. ומשיבים: \u0003אמר\u0004 \u0005[יכול היה לומר]\u0006 \u0003לך ריש לקיש: הא מני\u0004 \u0005[\u0006ברייתא \u0005זו\u0006 כשיטת \u0005מי היא]\u0006 — שיטת \u0003ר' יהודה היא,\u0004 ש\u0003אמר: אין שתי ידים זוכות כאחת.\u0004","ומקשים: \u0003אי\u0004 \u0005[אם]\u0006 כשיטת \u0003ר' יהודה\u0004 היא מדוע אומר הוא \u0003מה שאין כן בקידושין?! מה שאין כן בגירושין מיבעי ליה\u0004 \u0005[צריך היה לו]\u0006 לומר! שהרי הוא גילה דעתו החולקת בענין גירושין דווקא! ומשיבים: \u0003אין הכי נמי\u0004 \u0005[כן, כך\u0006 הוא \u0005גם כן]\u0006 וכך היה ראוי לומר, אולם כאן \u0003איידי דתנא\u0004 \u0005[מתוך ששנה]\u0006 \u0003מאמר דדמי\u0004 \u0005[ש\u0006הוא \u0005דומה]\u0006 \u0003לקידושין, תנא נמי\u0004 \u0005[שנה גם כן]:\u0006 \u0003מה שאין כן בקידושין.\u0004","ושואלים: \u0003ו\u0004אם הוא כדעת \u0003ר' יהודה, מאי שנא\u0004 \u0005[במה שונה]\u0006 \u0003מאמר\u0004 שאף הנערה יכולה לקבל, מגירושין שרק האב מקבל, הרי שניהם נעשים בעל כרחה? ומשיבים: שונה דין המאמר \u0003הואיל וזקוקה ועומדת\u0004 ויש כבר קשר וזיקה ליבם, די בקבלה כלשהי כדי שיחול בה המאמר. ומעירים: \u0003השתא דאתית להכי\u0004 \u0005[עכשיו שהגעת לכך]\u0006 להסבר זה, ל\u0003ר' יוחנן נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תיקשי\u0004 \u0005[תקשה]\u0006 קושיה זו \u0003לך מעיקרא\u0004 \u0005[מתחילה]\u0006 אף לפי החילוק הראשון לדעת חכמים בין גירושין לקידושין, שהרי אפשר להסביר: \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003מאמר\u0004 מקידושין \u0003הואיל וזקוקה ועומדת.\u0004","\u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003האיש מקדש את בתו כשהיא נערה, בו ובשלוחו.\u0004 ונדייק מכאן: \u0003בו ובשלוחו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003בה ובשלוחה\u0004 — \u0003לא,\u0004 והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 \u0003לריש לקיש,\u0004 שלדעתו, לדעת חכמים אף נערה עצמה מקבלת את קידושיה! ומשיבים: \u0003אמר\u0004 \u0005[\u0006יכול היה \u0005לומר]\u0006 \u0003לך ריש לקיש: הא נמי\u0004 \u0005[זו\u0006 המשנה \u0005גם כן]\u0006 לשיטת \u0003ר' יהודה היא.\u0004","ושואלים: \u0003ומי מצית מוקמת לה\u0004 \u0005[והאם יכול אתה להעמיד\u0006 להסביר את המשנה \u0005הזו]\u0006 \u0003כ\u0004דעת \u0003ר' יהודה? והקתני סיפא\u0004 \u0005[והרי שנה בסופה]\u0006 בהמשך, במשנה הבאה: \u0003האומר לאשה \"התקדשי לי בתמרה זו\", \"התקדשי לי ב\u0004תמרה \u0003זו\"\u0004 אינה מקודשת עד שיהא באחת מהן שווה פרוטה. \u0003ואמרינן\u0004 \u0005[ואמרנו]:\u0006 \u0003מאן\u0004 \u0005[מיהו]\u0006 ה\u0003תנא\u0004 האומר \u0003\"התקדשי\" \"התקדשי\"?\u0004 כלומר, שאם אינו אומר על כל תמרה שנותן \"התקדשי\" נחשב ככולל את כולן יחד ומצטרפות התמרות לשווה פרוטה.","\u0003ואמר רבה:\u0004 שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 שאין אדם חייב קרבנות שבועה מרובים אם נשבע לשקר לכמה אנשים יחד (כגון \"שבועה שאין חפץ שלך בידי לא לך, לא לך\"), \u0003עד שיאמר\u0004 לשון \u0003שבועה לכל אחד ואחד\u0004 (\"שבועה לא לך, שבועה לא לך\"). ואין זו משנת ר' יהודה!","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 שכל המשנה \u0003כולה\u0004 שיטת \u0003ר' יהודה\u0004 היא, \u0003ו\u0004אולם \u0003בפרטי\u0004 \u0005[ב\u0006ענין \u0005פרטים],\u0006 מה היא לשון הנחשבת לפירוט מספיק כדי להתחייב על כל ביטוי קרבן אשם מיוחד, \u0003סבר לה\u0004 \u0005[סבור הוא]\u0006 \u0003כ\u0004שיטת \u0003ר' שמעון.\u0004 \u0003ו\u0004אולם \u0003מי סבר לה\u0004 \u0005[האם סבור הוא]\u0006 כמותו?","\u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 \u0003זה הכלל\u0004 לענין חיובים בקרבן שבועה: \u0003כלל\u0004 את השבועות כאחת — \u0003אינו חייב אלא\u0004 על שבועה \u0003אחת, פרט\u0004 — \u0003חייב על כל אחת ואחת,\u0004 אלו \u0003דברי ר' מאיר. ר' יהודה אומר:\u0004 אמר \u0003\"שבועה\u0004 שאין פקדון בידי \u0003לא לך, לא לך, לא לך\"\u0004 ונמצא משקר — \u0003חייב על כל אחת ואחת. ר' אליעזר אומר: \"לא לך, לא לך, לא לך ולא לך שבועה\"\u0004 — \u0003חייב על כל אחת ואחת,\u0004 שדווקא כשאמר לשון שבועה בסוף הרי זה פרט. \u0003ר' שמעון אומר: לעולם אינו חייב\u0004 בקרבנות נפרדים אלא \u0003עד שיאמר\u0004 לשון \u0003שבועה לכל אחד ואחד.\u0004 הרי שלענין הגדרה איזו אמירה נחשבת לפירוט חולק ר' יהודה על ר' שמעון!","\u0003אלא\u0004 יש לפרש להיפך: משנתנו שלנו בקידושין \u0003כולה\u0004 כשיטת \u0003ר' שמעון היא, וב\u0004דין \u0003שליחות סבר לה כ\u0004שיטת \u0003ר' יהודה,\u0004 שדווקא אבי הנערה ממנה שליח לקבל קידושיה.","מסופר: פעם אחת \u0003ר' אסי לא על לבי מדרשא\u0004 \u0005[נכנס לבית המדרש].\u0006 \u0003אשכחיה\u0004 \u0005[מצא את]\u0006 \u0003ר' זירא, אמר\u0004 \u0003ליה\u0004 \u0005[לו]:\u0006 \u0003מאי אמור האידנא בי מדרשא\u0004 \u0005[מה אמרו עכשיו בבית המדרש]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אף אנא\u0004 \u0005[אני]\u0006 \u0003לא עייל\u0004 \u0005[נכנסתי].\u0006 והוסיף ר' זירא: אבל \u0003ר' אבין הוא דעייל\u0004 \u0005[שנכנס]\u0006 \u0003ואמר: חברותא\u0004 \u0005[החבורה]\u0006 \u0003כולה\u0004 סבורה \u0003כ\u0004שיטת \u0003ר' יוחנן\u0004 שמחלק בנערה בין קידושין וגירושין. \u0003וצווח ריש לקיש\u0004 בקול רם \u0003כי כרוכיא\u0004 \u0005[ככרוכיה]\u0006 כנגדם: הלא נאמר \u0003\"ויצאה... והיתה\"\u0004 (דברים כד, ב), שהכתוב משווה קידושין לגירושין לכל דבר, \u0003וליכא דאשגח ביה\u0004 \u0005[ולא\u0006 היה מי \u0005שישגיח בו,\u0006 בדבריו\u0005].\u0006 \u0003אמר ליה\u0004 \u0005[לו\u0006 ר' אסי\u0005]:\u0006 וכי \u0003ר' אבין בר סמכא הוא,\u0004 האם אפשר לסמוך עליו שהוא מוסר דברים כפי שנאמרו? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אין\u0004 \u0005[כן],\u0006 בענין זה אפשר לסמוך עליו, כיון שהיה זה \u0003כמין ימא לטיגני הוא\u0004 \u0005[כמו\u0006 המרחק משליית הדג \u0005מהים לטיגונו],\u0006 שעבר זמן קצר ביותר, ואין לחשוש ששכח או טעה בכך.","\u0003אמר רב נחמן בר יצחק: אנא\u0004 \u0005[אני],\u0006 כאשר אני חוזר על שמועה זו, איני שונה בה \u0003לא ר' אבין בר' חייא, ולא ר' אבין בר כהנא, אלא ר' אבין סתם.\u0004 ושואלים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 אם שונה את השמועה בשם זה או בשם זה? ומשיבים: \u0003למירמא דידיה אדידיה\u0004 \u0005[ל\u0006ענין \u0005השלכה,\u0006 סתירה מדבריו \u0005שלו על\u0006 דבריו \u0005שלו].\u0006 שאם נמצא דעה סותרת בשם ר' חייא בר אבין, למשל, אין זו סתירה אמיתית, כי מאמר זה נאמר על ידי ר' אבין אחר.","\u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רבא מרב נחמן:\u0004"],["לדעת חכמים שאף הנערה עצמה יכולה לקבל את גיטה, יש לשאול: \u0003נערה מהו שתעשה\u0004 (תמנה) אדם אחר כ\u0003שליח לקבל\u0004 את \u0003גיטה מיד בעלה?\u0004 וצדדי השאלה: מאחר שהבת בעודה נערה נחשבת כקניינו של אביה, האם מבחינה משפטית \u0003כיד אביה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 ועומדת במקומו, \u0003או כחצר אביה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת]?\u0006 ומסבירים: \u0003כיד אביה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת];\u0006 \u0003מה אביה משוי\u0004 \u0005[עושה,\u0006 ממנה\u0005]\u0006 \u0003שליח\u0004 — \u0003אף היא נמי משוי\u0004 \u0005[גם כן עושה]\u0006 \u0003שליח,\u0004 שהרי היא נחשבת כגופו. \u0003או דילמא\u0004 \u0005[שמא]\u0006 \u0003כחצר אביה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת],\u0006 \u0003ו\u0004לכן \u0003עד דמטיא גיטא\u0004 \u0005[שמגיע הגט]\u0006 \u0003לידה\u0004 ממש \u0003לא מיגרשה\u0004 \u0005[אינה מתגרשת].\u0006","ושואלים: \u0003ומי מספקא ליה\u0004 \u0005[והאם מסופק לו]\u0006 \u0003לרבא הא\u0004 \u0005[\u0006דבר \u0005זה]?\u0006 \u0003והאמר\u0004 \u0005[והרי אמר]\u0006 \u0003רבא: כתב גט ונתנו ביד עבדה\u0004 של אשתו שהיה \u0003ישן, ו\u0004היא \u0003משמרתו\u0004 את העבד — \u0003הרי זה גט.\u0004 ואם היה העבד \u0003ניעור\u0004 — \u0003אינו גט.\u0004 ונברר: כאשר העבד \u0003ניעור אמאי\u0004 \u0005[מדוע]\u0006 \u0003אינו גט\u0004 — \u0003דהויא\u0004 \u0005[שהרי הוא],\u0006 העבד, \u0003לה\u0004 כ\u0003חצר משתמרת שלא לדעתה,\u0004 אלא לדעתו של העבד עצמו. \u0003ואי סלקא דעתך\u0004 \u0005[ואם עולה על דעתך]\u0006 לומר שהנערה \u0003כחצר אביה דמיא\u0004 \u0005[נחשבת]\u0006 \u0003כי מטא גיטה\u0004 \u0005[כאשר מגיע גט]\u0006 \u0003לידה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא תיגרש\u0004 \u0005[תתגרש],\u0006 משום \u0003דהויא לה\u0004 \u0005[שהרי היא]\u0006 כ\u0003חצר המשתמרת שלא לדעת אביה!\u0004","\u0003אלא לעולם פשיטא ליה\u0004 \u0005[פשוט לו]\u0006 לרבא \u0003דכי\u0004 \u0005[ש\u0006נערה \u0005כמו]\u0006 \u0003יד אביה דמיא\u0004 \u0005[\u0006היא \u0005נחשבת]\u0006 ולא כחצירו, \u0003והכי קמיבעיא ליה\u0004 \u0005[וכך נשאלה,\u0006 נסתפקה \u0005לו]:\u0006 \u0003מי אלימא\u0004 \u0005[האם בעלת תוקף]\u0006 היא \u0003כיד אביה\u0004 ממש \u0003לשויה איהי\u0004 \u0005[שתעשה,\u0006 תמנה, \u0005היא]\u0006 עצמה \u0003שליח, או לא? אמר ליה\u0004 \u0005[לו]\u0006 רב נחמן: \u0003אין עושה שליח.\u0004","\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רבא ממה ששנינו: \u0003קטנה שאמרה\u0004 לשליח \u0003\"התקבל לי גיטי\"\u0004 — \u0003אינו גט עד שיגיע גט לידה,\u0004 שהקטנה שאינה נחשבת כבת־דעת אינה יכולה למנות שליח. ונדייק: \u0003הא\u0004 \u0005[הרי]\u0006 אם היתה זו \u0003נערה\u0004 — \u0003הרי זה גט,\u0004 ומשמע שנערה יכולה למנות שליח רגיל! ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 — \u0003בשאין לה אב,\u0004 ולכן נערה זו יכולה למנות שליח שהרי היא כבר גדולה וברשות עצמה, אבל נערה שיש לה אב עדיין היא ברשות אביה ואינה יכולה למנות שליח.","ומקשים: \u0003הא מדקתני סיפא\u0004 \u0005[הרי מ\u0006מה \u0005ששנה, בסופה]\u0006 של אותה משנה: \u0003אם אמר אביה\u0004 לשליח \u0003\"צא וקבל גט לבתי\", אם רצה בעל לחזור בו\u0004 — \u0003לא יחזור\u0004 אחרי שניתן גט לשליח, שהרי השליח הוא כמותה, וכאילו הגיע הגט לידיה ממש. \u0003מכלל\u0004 הדברים אתה למד \u0003דרישא\u0004 \u0005[ש\u0006גם \u0005בראשה\u0006 של המשנה\u0005]\u0006 מדובר \u0003ב\u0004אופן ש\u0003יש לה אב עסקינן\u0004 \u0005[אנו עוסקים]!\u0006 ומשיבים: \u0003חסורי מיחסרא והכי קתני\u0004 \u0005[חסרה\u0006 המשנה \u0005וכך היא שנויה]:\u0006 \u0003קטנה שאמרה \"התקבל לי גיטי\"\u0004 — \u0003אינו גט, עד שיגיע גט לידה. הא\u0004 \u0005[הרי]\u0006 ב\u0003נערה הרי זה גט\u0004 אם הגיע גט כזה ליד השליח. \u0003במה דברים אמורים\u0004 — \u0003כשאין לה אב, אבל יש לה אב ואמר אביה \"צא וקבל לבתי גיטה\", ורוצה בעל לחזור\u0004 — \u0003לא יחזור.\u0004","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה הבאה: \u0003קטנה שנתקדשה\u0004 בעצמה \u0003שלא לדעת אביה, אמר שמואל: צריכה גט\u0004 מן הבעל, \u0003וצריכה\u0004 גם \u0003מיאון\u0004 שתבטל את הנישואין על ידי מיאון בבעלה. \u0003אמר\u0004 החכם \u0003קרנא: דברים\u0004 תמוהים יש \u0003בגו\u0004 \u0005[בתוך]\u0006 הלכה זו, שכן יש בה סתירה פנימית, שהרי \u0003אם\u0004 צריכה \u0003גט,\u0004 משמע שאנו דנים שהיו אלה קידושין ממש, ואז — \u0003למה\u0004 צריכה \u0003מיאון?\u0004 ולהיפך, \u0003אם\u0004 צריכה \u0003מיאון\u0004 ומיאון זה מועיל, משמע שלא חלו קידושין אלה מדין תורה, ואם כן \u0003למה\u0004 לה גם \u0003גט?\u0004","\u0003אמרו ליה\u0004 \u0005[לו]\u0006 לקרנא: \u0003הא\u0004 \u0005[הרי]\u0006 \u0003מר עוקבא ובי דיניה\u0004 \u0005[ובית דינו]\u0006 יושבים \u0003ב\u0004עיר \u0003כפרי,\u0004 נשלח את השאלה הזו לפניו. ועוד עשו כדי לפתור שאלה זו, \u0003אפכוה, שדרוה לקמיה\u0004 \u0005[הפכו\u0006 את שמות בעלי הסברות ו\u0005שלחו\u0006 את השאלה \u0005לפני]\u0006 \u0003רב. אמר להו\u0004 \u0005[להם]\u0006 לשליחים בלשון שבועה: \u0003האלהים! צריכה גט, וצריכה מיאון. וחס ליה לזרעיה\u0004 \u0005[וחס\u0006 ושלום \u0005לו, לזרעו]\u0006 של \u0003אבא בר אבא\u0004 כלומר, שמואל (לפי מה שנאמר לרב), \u0003דנימא הכי\u0004 \u0005[\u0006\u0005שיאמר כך]\u0006 שדי לה בגט בלבד.","ושואלים: \u0003ו\u0004באמת \u0003טעמא מאי\u0004 \u0005[מה הטעם]\u0006 להצריך גם גט וגם מיאון? \u0003אמר רב אחא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב איקא: צריכה גט\u0004 — \u0003שמא נתרצה האב בקידושין\u0004 וחלו למפרע, ומצד שני \u0003צריכה מיאון\u0004 — \u0003שמא לא נתרצה האב בקידושין\u0004 ולא חלו הקידושין, ואם תתגרש בגט בלבד האנשים עלולים לחשוב שנתרצה האב \u0003ו\u0004אם יקדש אותו אדם את אחותה \u0003יאמרו\u0004 ש\u0003אין קידושין תופסין באחותה\u0004 כלל, שיחשבו שהם בטלים מעיקרם ולא יצריכוה גט כלל שכן אין קידושין תופסים באחות אשתו, אפילו כשגירש את אשתו, ולכן צריכה גם מיאון ובגלל תוספת זו של המיאון יבינו הכל שלא היו אלה קידושי ודאי ואם אחר כך יקדש את אחותה יצריכוה גט מספק.","\u0003אמר רב נחמן:\u0004 דברים אלה שחוששים לריצוי האב בקטנה שנתקדשה שלא לדעת אביה, אינם בכל מקרה אלא \u0003הוא\u0004 דווקא בזמן \u0003ששדכו\u0004 אותה לאיש זה קודם שקידשה עצמה, שאז יש לחשוש שמא נתרצה אביה בקידושיה.","\u0003עולא אמר:\u0004 במקרה של קטנה שקיבלה קידושין שלא לדעת אביה אין הקידושין חלים ו\u0003אפילו מיאון אינה צריכה.\u0004 ושואלים: האם אמר עולא דברים אלה \u0003אף על גב\u0004 (אף על פי) ש\u0003שידכו?\u0004 ומשיבים: \u0003מאן דמתני הא, לא מתני הא\u0004 \u0005[מי ששונה\u0006 את \u0005זו, אינו שונה\u0006 את \u0005זו].\u0006 כלומר, מי ששנה את דברי עולא לא העמיד את דברי שמואל כרב נחמן דווקא במקרה של שידוך מוקדם, אלא בסתם. \u0003איכא דאמרי\u0004 \u0005[יש שאומרים]\u0006 \u0003אמר עולא: קטנה שנתקדשה שלא לדעת אביה\u0004 — \u0003אפילו מיאון אינה צריכה\u0004 ואפילו שידכו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב כהנא:\u0004 שנינו במסכת יבמות שאם נפלה לפני הי בם אחת מחמש עשרה נשים האסורות עליו משום ערוה — לא רק היא עצמה אסורה להתייבם אלא אף צרתה אסורה ליבם. והוסיפו: \u0003וכולן,\u0004 כל אותן הנשים האסורות, \u0003אם מתו, או מיאנו, או נתגרשו, או שנמצאו איילונית\u0004 לפני שמת הבעל — \u0003צרותיהן מותרות\u0004 ליבם.","ונברר לגבי זו שמיאנה: ש\u0003קדשה מאן\u0004 \u0005[מי]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003קדשה אביה\u0004 לאח שמת, וכי \u0003במיאון\u0004 בלבד \u0003סגי לה\u0004 \u0005[די לה]?!\u0006 הלא \u0003גט מעליא בעיא\u0004 \u0005[מעולה,\u0006 גמור, היא \u0005צריכה]!\u0006 \u0003אלא לאו\u0004 \u0005[אין\u0006 זאת\u0005]\u0006 — ש\u0003קדשה איהי נפשה\u0004 \u0005[היא את עצמה]\u0006 בעודה קטנה, \u0003ו\u0004מכל מקום \u0003קתני דבעיא\u0004 \u0005[ושנה שצריכה]\u0006 \u0003מיאון,\u0004 וקשה לעולא שאמר שאינה צריכה אפילו מיאון!","ומעירים: \u0003הוא,\u0004 רב כהנא, \u0003מותיב לה\u0004 \u0005[מקשה\u0006 את הקושיה \u0005הזו]\u0006 \u0003והוא מפרק\u0004 \u0005[מתרץ]\u0006 \u0003לה; כגון שנעשה לה מעשה יתומה בחיי האב.\u0004 שבמשנה זו מדובר כגון שהשיאה אביה קודם לאדם אחר ונתאלמנה או נתגרשה בקטנותה, שאז דינה כיתומה לענין זה שאין לאב זכות לקדש אותה עוד, אף שהוא בחיים. ואם קידשה את עצמה, אין אלה קידושין התופסים מדין תורה, שהרי היא קטנה, אלא מדברי חכמים, ויוצאת מבעלה במיאון.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב המנונא:\u0004 שנינו בדין אמה העבריה: \u0003אין\u0004 האב \u0003מוכרה\u0004 את בתו הקטנה כשפחה \u0003לקרובים\u0004 משום שאי אפשר לקיים את דברי הכתוב בענין זה בשלימותם לפי שאינם יכולים לשאתה לאשה לאחר מכן. \u0003משום\u0004 (בשם) \u0003ר' אלעזר אמרו: מוכרה\u0004 אף \u0003לקרובים,\u0004 שפעמים אינו מוכרה אלא לשם שפחות בלבד ולא לנישואין."],["\u0003ושוין\u0004 (מסכימים) \u0003שמוכרה\u0004 אף שהיא \u0003אלמנה לכהן גדול,\u0004 וכן אם היא \u0003גרושה,\u0004 או \u0003חלוצה לכהן הדיוט,\u0004 שאף שהן אסורות להנשא להם, מכל מקום קידושין תופסים בהן. ונברר: \u0003האי\u0004 \u0005[זו]\u0006 ה\u0003אלמנה\u0004 שאביה יכול למוכרה \u0003היכי דמי\u0004 \u0005[כיצד בדיוק מדובר כאן]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003קדשה אביה\u0004 ואחר כך מת בעלה בעודה קטנה, אולם \u0003מי מצי מזבין לה\u0004 \u0005[האם יכול למכור אותה]\u0006 אחר שקידשה? \u0003הא\u0004 \u0005[הרי]\u0006 \u0003אין אדם מוכר את בתו לשפחות אחר אישות\u0004 (שקידשה)! \u0003אלא לאו\u0004 \u0005[האם לא]\u0006 מדובר כאן במקרה \u0003דקדיש איהי נפשה\u0004 \u0005[שקידשה היא\u0006 את \u0005עצמה]\u0006 בהיותה קטנה \u0003ו\u0004בכל זאת \u0003קא קרי\u0004 \u0005[קורא]\u0006 \u0003לה אלמנה,\u0004 הרי שחלו קידושיה! וקשה לעולא.","\u0003אמר רב עמרם אמר ר' יצחק: הכא\u0004 \u0005[כאן]\u0006 מדובר באלמנה \u0003בקידושי יעוד\u0004 שמכרה אביה לאמה, וייעדה הקונה להיות לו לאשה, ומת לפני שנשאה. \u0003ואליבא\u0004 \u0005[ועל פי\u0006 שיטת\u0005]\u0006 \u0003ר' יוסי בר' יהודה\u0004 היא, ש\u0003אמר: מעות הראשונות\u0004 שמקבל האב עבור מכירת בתו \u0003לאו\u0004 \u0005[לא]\u0006 \u0003לקידושין\u0004 שייעשו בה לאחר מכן \u0003ניתנו,\u0004 אלא קידושיה חלים כאשר מוותר לה האדון על מקצת עבודתה, ובכך מקדשה. והואיל ואין אלה קידושין מכוח האב מותר הוא למוכרה שוב לשפחה לאחר מכן.","\u0003איתמר\u0004 \u0005[נאמר]:\u0006 אם \u0003מת\u0004 זה שקידש את הקטנה שלא מדעת אביה \u0003ונפלה לפני אחיו ליבום; אמר רב הונא אמר רב: ממאנת למאמרו,\u0004 כלומר, שאם עשה בה היבם מאמר (קידש אותה לאשה), כשבא לגרשה צריכה גם מיאון בקידושין אלו, בנוסף לגט, \u0003ואינה ממאנת לזיקתו,\u0004 שאם לא עשה בה מאמר, אינה צריכה למיאון יחד עם החליצה. ומסבירים: \u0003כיצד? עשה בה מאמר\u0004 — \u0003צריכה גט, וצריכה חליצה, וצריכה מיאון.\u0004","והסבר הדברים: \u0003צריכה גט\u0004 — \u0003שמא נתרצה האב בקידושי שני,\u0004 שהרי המאמר הוא מעשה קידושין, ואם לא נתרצה בקידושי ראשון אינה נחשבת ליבמה ותפסו בה קידושין אלו וכדי להפקיעם צריכה גט. \u0003צריכה חליצה\u0004 — \u0003שמא נתרצה האב בקידושי ראשון,\u0004 ואם כן הריהי כיבמה גמורה, שיוצאת דווקא בחליצה. \u0003צריכה מיאון\u0004 — \u0003שמא לא נתרצה האב לא בקידושי ראשון ולא בקידושי שני,\u0004 ומשום כך צריכה גם מיאון בנוסף לגט וחליצה. שאם לא כן שמא \u0003יאמרו\u0004 שנישואיה הראשונים היו נישואין ודאיים, ולכן \u0003אין קידושין תופסין באחותה,\u0004 בעוד שבאמת אינה אלא ספק מקודשת שמא נתרצה לשני, רק מפני הספק, תופסים קידושין באחותה.","אם \u0003לא עשה בה מאמר\u0004 — \u0003אינה צריכה אלא חליצה בלבד.\u0004 ומסבירים: \u0003מאי אמרת\u0004 \u0005[מה\u0006 יכול אתה \u0005לומר]:\u0006 \u0003תיבעי נמי\u0004 \u0005[תצטרך גם כן]\u0006 במקרה זה \u0003מיאון, שמא יאמרו אין קידושין תופסין באחותה\u0004 — כאן אין צורך בכך כי \u0003הכל יודעים: אחות\u0004 של \u0003חלוצה\u0004 אינה אסורה אלא \u0003דרבנן\u0004 \u0005[מ\u0006דברי \u0005סופרים]\u0006 וקידושין תופסים בה ולא יבואו להתירה בלא גט. ש\u0003אמר ריש לקיש\u0004 על משנה ביבמות: \u0003כאן שנה רבי,\u0004 כלומר, במשנה זו לימד אותנו רבי בדרך אגב כי \u0003אחות\u0004 של \u0003גרושה\u0004 אסורה \u0003מדאורייתא\u0004 \u0005[מן התורה],\u0006 ואילו \u0003אחות חלוצה\u0004 אסורה רק \u0003מדברי סופרים.\u0004","מסופר: \u0003הנהו בי תרי דהוו קא שתו חמרא תותי ציפי\u0004 \u0005[שנים שהיו\u0006 יושבים ו\u0005שותים יין תחת עצי צפצפה]\u0006 \u0003בבבל. שקל חד מינייהו כסא דחמרא, יהב ליה לחבריה\u0004 \u0005[לקח אחד מהם כוס יין, נתנה לחבירו].\u0006 \u0003אמר: מיקדשא\u0004 \u0005[תתקדש]\u0006 \u0003לי\u0004 בכך \u0003ברתיך לברי\u0004 \u0005[בתך לבני].\u0006 \u0003אמר רבינא: אפילו למאן דאמר\u0004 \u0005[ל\u0006שיטת \u0005מי שאומר]\u0006 בקטנה שנתקדשה שלא לדעת אביה \u0003חיישינן\u0004 \u0005[\u0006ש\u0005חוששים אנו]\u0006 \u0003שמא נתרצה האב\u0004 —"],["\u0003שמא נתרצה הבן לא אמרינן\u0004 \u0005[אין אנו אומרים]\u0006 וכיון שקידש אביו את האשה שלא מדעת בנו — אין אלו קידושין. \u0003אמרי ליה רבנן\u0004 \u0005[אמרו לו חכמים]\u0006 \u0003לרבינא: ודילמא\u0004 \u0005[ושמא]\u0006 \u0003שליח שויה\u0004 \u0005[עשאו],\u0006 מינה הבן את אביו, לקדשה ויחולו הקידושין? ענה להם: \u0003לא חציף איניש לשויי לאבוה\u0004 \u0005[אין אדם חצוף לעשות את אביו]\u0006 \u0003שליח.\u0004 ושאלו עוד: \u0003ודילמא ארצויי ארצייה קמיה\u0004 \u0005[ושמא\u0006 הבן \u0005ריצה ופייס אותו]\u0006 את האב, ואמר לו שרצונו באשה זו, והאב מדעתו עשה רצון בנו וקידשה לו, וייחשב כזוכה לו בקידושי אשה זו? \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבה בר שימי\u0004 לרבינא: אין כאן בכלל שאלה שכן \u0003בפירוש אמר מר\u0004 \u0005[החכם,\u0006 רבינא\u0005]\u0006 \u0003דלא סבר להא\u0004 \u0005[שאינו סבור\u0006 אינו מקבל \u0005ל\u0006שיטה \u0005זו]\u0006 של \u0003רב ושמואל\u0004 ואין אומרים שמא נתרצה האב, ולדעתו אין לחשוש שמא נתרצה אדם כאשר עשו דבר שלא מדעתו.","עוד מסופר: \u0003ההוא גברא דקדיש בכישא דירקא בשוקא\u0004 \u0005[אדם אחד שקידש\u0006 קטנה שלא לדעת אביה \u0005באגודת ירק בשוק].\u0006 \u0003אמר רבינא: אפילו למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 בקטנה שנתקדשה שלא לדעת אביה ש\u0003חוששין שמא נתרצה האב\u0004 ומקודשת — \u0003הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים דווקא כשקידש אותה \u0003דרך כבוד, אבל\u0004 אם קידשה ב\u0003דרך בזיון\u0004 — \u0003לא,\u0004 שבכך ודאי לא היה האב מתרצה ואף כאן היו הקידושין בדרך בזיון.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב אחא מדיפתי לרבינא: בזיון דמאי\u0004 \u0005[של מה],\u0006 מה בדיוק היה דרך הבזיון שבקידושין אלה? \u0003אי\u0004 \u0005[האם]\u0006 ה\u0003בזיון\u0004 הוא \u0003דירקא\u0004 \u0005[ש\u0006עשה זאת על ידי \u0005ירק],\u0006 \u0003אי\u0004 \u0005[או]\u0006 ה\u0003בזיון\u0004 היה \u0003דשוקא\u0004 \u0005[\u0006בגלל שנעשה הדבר \u0005בשוק]?\u0006 \u0003נפקא מינה\u0004 \u0005[יוצא מזה\u0006 הבדל להלכה\u0005]\u0006 מהדיוק בהגדרה של בזיון זה במקרה \u0003דקדיש בכספא בשוקא\u0004 \u0005[שקידש בכסף בשוק],\u0006 \u0003או בכישא דירקא בביתא\u0004 \u0005[באגודת ירק ב\u0006תוך ה\u0005בית],\u0006 אם כן \u0003מאי\u0004 \u0005[מה]\u0006 יהיה הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 \u0003דרך בזיון הוא\u0004 כל אחד בפני עצמו, ולכן בשני המקרים הללו לא תהיה הקטנה מקודשת.","עוד מסופר: בני זוג שהיתה להם בת קטנה ורצו להשיאה \u0003ההוא\u0004 \u0005[הוא],\u0006 האב ש\u0003אמר\u0004 שהוא רוצה להשיא אותה \u0003לקריבאי\u0004 \u0005[לקרובו],\u0006 \u0003והיא,\u0004 האם, \u0003אמרה\u0004 שהיא רוצה להשיא אותה \u0003לקריבה\u0004 \u0005[לקרובה].\u0006 \u0003כפתיה\u0004 \u0005[כפתה אותו\u0006 ואילצה אותו\u0005]\u0006 \u0003עד\u0004 ש\u0003אמר לה\u0004 לאשתו: \u0003\"תיהוי לקריבה\"\u0004 \u0005[תינשא\u0006 הבת \u0005לקרוב שלה].\u0006 \u0003אדאכלי ושתי\u0004 \u0005[עד\u0006 שהיו \u0005אוכלים ושותים]\u0006 במשתה שלפני האירוסין \u0003אתא קריביה באיגרא\u0004 \u0005[בא קרובה לגג]\u0006 \u0003וקדשה\u0004 לעצמו ובא מעשה לפני חכמים.","\u0003אמר אביי: כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"שארית ישראל לא יעשו עולה ולא ידברו כזב\"\u0004 (צפניה ג, יג). וכיון שאמר לאשתו שהוא מוכן שתינשא הבת לקרוב שלה — ודאי לא שיקר ולא חזר בו. וכיון שהיתה הבת קטנה ותלויים קידושיה בדעתו, אין לומר שנתרצה האב בקידושין שקידש אותה קרובו. \u0003רבא אמר\u0004 טעם אחר יש כאן: \u0003חזקה אין אדם טורח בסעודה ומפסידה.\u0004 וכאן הרי עשו סעודה לכבוד הקידושין של הבת לקרוב של אשתו, ובודאי לא היה האב עושה את הדבר לחנם.","ושואלים: \u0003מאי בינייהו\u0004 \u0005[מה\u0006 ההבדל \u0005ביניהם]\u0006 הלכה למעשה אם זה או זה הטעם? ומשיבים: \u0003איכא בינייהו\u0004 \u0005[יש ביניהם]\u0006 הבדל \u0003למעשה במקרה ש\u0004\u0003לא טרח\u0004 בסעודה, שלדעת רבא חוששים אנו לקידושיה, שהרי לא טרח, ולדעת אביי בודאי אינה מקודשת שבכל מקרה אין אדם משקר.","קטנה ש\u0003נתקדשה לדעת אביה, והלך אביה למדינת הים ועמדה ונישאת\u0004 לדעת עצמה, ואביה לא מסרה לחופה; \u0003אמר רב:\u0004 אם היא בת ישראל ונישאה לכהן — \u0003אוכלת בתרומה עד שיבא אביה וימחה,\u0004 שיאמר בפירוש שאינו רוצה בנישואין הללו. \u0003רב אסי אמר: אינה אוכלת\u0004 בתרומה, \u0003שמא יבוא אביה וימחה, ונמצאת זרה\u0004 (שאינה כהנת) \u0003אוכלת בתרומה למפרע.\u0004 מסופר: \u0003הוה עובדא וחש לה\u0004 \u0005[היה מעשה\u0006 כגון זה \u0005וחשש]\u0006 \u0003רב להא\u0004 \u0005[ל\u0006סברה \u0005זו]\u0006 של \u0003רב\u0004 \u0003אסי\u0004 שלא תיחשב הבת כנשואה, ואסר עליה לאכול בתרומה (למרות שלדעתו היא מותרת בכך), שמא יבוא האב וימחה.","\u0003אמר רב שמואל בר רב יצחק: ומודה רב שאם מתה\u0004 אותה קטנה — הבעל \u0003אינו יורשה.\u0004 ומדוע — \u0003אוקי ממונא\u0004 \u0005[העמד\u0006 את \u0005הממון]\u0006 \u0003בחזקת מריה\u0004 \u0005[בעליו],\u0006 שחזקתו ברשות יורשיה ולא ברשותו, והואיל ויש ספק בנישואין אם נתרצה האב בהן — נשאר הממון בינתיים ברשותם.","ועוד מחלוקת חכמים: \u0003נתקדשה\u0004 בת ישראל קטנה לכהן \u0003לדעת\u0004 אביה \u0003וניסת\u0004 (נישאת) \u0003שלא לדעת\u0004 אביה, \u0003ואביה כאן; רב הונא אמר: אינה אוכלת\u0004 בתרומה, שהרי אביה מן הסתם אינו מסכים שתינשא שלא מדעתו. \u0003רב ירמיה בר אבא אמר\u0004 \u0003: אוכלת\u0004 בתרומה.","ומסבירים את השיטות: \u0003רב הונא אמר: אינה אוכלת. ואפילו לרב\u0004 ש\u0003אמר\u0004 כשהיה האב במדינת הים \u0003אוכלת\u0004 בתרומה — \u0003התם הוא דלא איתיה לאב\u0004 \u0005[שם,\u0006 שאמר שאוכלת, \u0005הוא כשהאב איננו]\u0006 \u0003אבל הכא דאיתיה לאב\u0004 \u0005[כאן שישנו האב]\u0006 ודאי לא נתרצה בכך, \u0003האי דאישתיק\u0004 \u0005[זה ש\u0006הוא \u0005שותק]\u0006 ולא מוחה במפורש, זה משום שודאי \u0003מירתח רתח\u0004 \u0005[\u0006הוא \u0005כועס]\u0006 כל כך שאינו רוצה אפילו לדבר איתה, אבל ברור שלא הסכים לנישואיה. \u0003רב ירמיה בר אבא אמר: אוכלת. ואפילו לרב אסי\u0004 ש\u0003אמר אינה אוכלת, התם\u0004 \u0005[שם]\u0006 \u0003הוא\u0004 שיש לחשוש לכך \u0003שמא יבוא אביה וימחה, אבל הכא מדשתיק\u0004 \u0005[כאן\u0006 מכיון \u0005ש\u0006הוא \u0005שותק]\u0006 — מן הסתם \u0003איתנוחי איתנחא ליה\u0004 \u0005[\u0006\u0005נוחה לו\u0006 דעתו בזה\u0005].\u0006","ובעיה נוספת: \u0003נתקדשה\u0004 הקטנה \u0003שלא לדעת אביה, וניסת שלא לדעת, ואביה כאן; רב הונא אמר: אוכלת\u0004 בתרומה, \u0003רב ירמיה בר אבא אמר: אינה אוכלת. אמר עולא: הא\u0004 \u0005[\u0006שיטתו \u0005זו]\u0006 של \u0003רב הונא\u0004 שבמקרה כזה אוכלת בתרומה היא \u0003\"כחמץ לשנים וכעשן לעינים\"\u0004 (משלי י, כו), כלומר, אינה מסתברת כלל שהרי היא אף בניגוד לדברי עצמו. \u0003השתא ומה התם דקידושי דאורייתא אמרת לא אכלה\u0004 \u0005[עכשיו,\u0006 הרי, \u0005ומה שם\u0006 כשנתקדשה לדעת אביה \u0005ש\u0006יש על כל פנים \u0005קידושין מן התורה\u0006 ולמרות זאת \u0005אתה אומר שאינה אוכלת]\u0006 בתרומה, מחשש שמא לא נתרצה לחופה, \u0003הכא\u0004 \u0005[כאן]\u0006 שאף הקידושין היו שלא לדעת האב \u0003לא כל שכן\u0004 שלא תאכל?!"],["אלא \u0003נראין דברי\u0004 ה\u0003תלמיד,\u0004 שדברי ר' ירמיה בר אבא, אף שהוא כתלמיד לגבי רב הונא נראים יותר. \u0003אמר רבא: מאי טעמא\u0004 \u0005[מה הטעם]\u0006 של \u0003רב הונא\u0004 — \u0003הואיל ונעשה בה מעשה יתומה בחיי האב.\u0004 כלומר, מכיון שהאב מתעלם גם מהקידושין וגם מהנישואין ואינו פועל כלל בענין זה, נראה מדבריו שהוא מוותר על זכותו בה, והרי היא כעין יתומה בחיי האב שקידושיה חלים.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו בבעיה זו: \u0003קטנה שנתקדשה שלא לדעת אביה, אמר רב: בין היא ובין אביה יכולין לעכב,\u0004 כלומר, יכולים לומר אחר כך שאינם רוצים בקידושין אלה. \u0003ורב אסי אמר: אביה\u0004 יכול לעכב \u0003ולא היא,\u0004 שהרי היא נתרצתה מתחילה. \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רב הונא לרב אסי, ואמרי לה\u0004 \u0005[ויש אומרים]\u0006 שהקשה זאת \u0003חייא בר רב לרב אסי:\u0004 נאמר בדיני המפותה \u0003\"אם מאן ימאן אביה\u0004 לתתה לו (למפתה), כסף ישקול כמוהר הבתולות\u0003\"\u0004 (שמות כב, טז), ודרשו: ממה שנאמר בכתוב \u0003אין לי אלא\u0004 ש\u0003אביה\u0004 יכול למאן, ואולם \u0003היא עצמה מנין\u0004 שיכולה למאן — \u0003תלמוד לומר: \"אם מאן ימאן\",\u0004 שלשון כפולה זו מלמדת שיש רשות מיאון \u0003מכל מקום.\u0004 משמע שגם היא, למרות שנתפתתה תחילה, יכולה להתחרט ולומר שאינה רוצה בו!","\u0003אמר להו\u0004 \u0005[להם]\u0006 \u0003רב\u0004 לאלה שרצו לסייע לו: \u0003לא תיזלו בתר איפכא\u0004 \u0005[אל תלכו אחר ההיפך],\u0006 כלומר, אל תנסו להוכיח ממקור שאפשר להבין אותו גם בדרך הפוכה. \u0003יכול\u0004 רב אסי \u0003לשנויי לכו\u0004 \u0005[לתרץ לכם]\u0006 שכאן מדובר \u0003כגון שפיתה\u0004 אותה מתחילה \u0003שלא לשום\u0004 (לשם) \u0003אישות,\u0004 שלא אמר לה אף מתחילה שרצונו לשאת אותה, אלא למשכב בלבד, ומלכתחילה לא התרצתה להנשא לו ובמקרה כזה יכולה גם היא למאן. ותוהים: וכי \u0003פיתה שלא לשום אישות קרא בעי\u0004 \u0005[צריך כתוב]\u0006 ללמדנו שיכולה למאן להנשא לו? \u0003אמר רב נחמן בר יצחק: לומר\u0004 שאף כשהיא ממאנת מלהנשא לו, ולמרות שאביה מסכים לנישואין, \u0003שמשלם קנס כמפותה,\u0004 ואין אומרים שקנס משלמים רק כשאביה ממאן להשיאה לו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב יוסף: אי הכי\u0004 \u0005[אם כך]\u0006 יש לסייע להסבר זה, שכן \u0003היינו דתנינא\u0004 \u0005[זהו ששנינו\u0006 בברייתא\u0005]\u0006 בענין מפותה, שמה שנאמר \u0003\"מהר ימהרנה לו לאשה\"\u0004 (שם טו) הרי זה בא לומר \u0003שצריכה הימנו\u0004 (ממנו) \u0003קידושין. ואם\u0004 עוסק הכתוב ב\u0003פיתה\u0004 ובא עליה \u0003לשום אישות, קידושין\u0004 אם כן \u0003למה לי?\u0004 הרי ביאתה היא היא מעשה הקידושין! משמע שמדובר כשפיתה אותה שלא לשם אישות. \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 אפשר לדחות ולומר שהכוונה היא שעל אף שפיתה אותה לשם אישות \u0003צריכה קידושין לדעת אביה\u0004 שהרי היא קטנה וקידשה שלא לדעתו.","\u0003האומר לאשה \"התקדשי לי בתמרה זו\",\u0004 ומוסיף ואומר \u0003\"התקדשי לי בזו\"; אם יש באחת מהן\u0004 מן התמרים הללו \u0003שוה פרוטה\u0004 — הריהי \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת,\u0004 שהרי פרט ואמר לשון \"קידושין\" לגבי כל תמרה לעצמה. אבל אם אמר לה \u0003\"\u0004התקדשי לי \u0003בזו ובזו ובזו\"; אם יש שוה פרוטה בכולן\u0004 — הריהי \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת.\u0004 נתן לה תמרים ורצה לקדש אותה בהם, ו\u0003היתה אוכלת ראשונה ראשונה,\u0004 שכל תמרה שנתן לה אכלתה מיד — \u0003אינה מקודשת, עד שיהא באחת מהן שוה פרוטה.\u0004","\u0003מאן\u0004 \u0005[מי הוא]\u0006 ה\u0003תנא\u0004 הסבור שכדי שייחשבו הדברים כחלוקים זה מזה צריך לומר \u0003\"התקדשי\" \"התקדשי\"\u0004 בכל פעם ופעם? \u0003אמר רבה:\u0004 שיטת \u0003ר' שמעון היא,\u0004 ש\u0003אמר\u0004 בדיני שבועת הפקדון כיוצא בזה, שאינו חייב בקרבן לגבי כל אדם שהוא מכחיש את טענתו \u0003עד שיאמר\u0004 לשון \u0003\"שבועה\" לכל אחד ואחד.\u0004","שנינו במשנה: אם אמר \u0003\"בזו\" \"ובזו\" \"ובזו\"\u0004 — \u0003אם יש בכולן שוה פרוטה\u0004 — הריהי מקודשת. ושנינו בסופה שאם היתה אוכלת ראשונה ראשונה אינה מקודשת עד שיהא באחת מהן שווה פרוטה ושואלים: מקרה זה בשהיתה אוכלת ראשונה ראשונה, \u0003אהייא\u0004 \u0005[לאיזה]\u0006 דין הוא מתייחס? \u0003אילימא ארישא\u0004 \u0005[אם תאמר\u0006 לגבי \u0005ראש\u0006 המשנה\u0005]\u0006 כאשר קידש אותה בכל תמרה לחוד, \u0003מאי איריא\u0004 \u0005[מה שייך,\u0006 מדוע דווקא\u0005]\u0006 ב\u0003אוכלת? אפילו\u0004 אם היתה \u0003מנחת\u0004 אותן בלי לאוכלן \u0003נמי\u0004 \u0005[גם כן]\u0006 יהא זה אותו דין, \u0003דהא\u0004 \u0005[שהרי]\u0006 \u0003\"התקדשי לי בזו\" קאמר\u0004 \u0005[אמר],\u0006 וצריך שיהיה בכל תמרה כדי קידושין! \u0003אלא\u0004 צריך אתה לומר שמדובר \u0003אסיפא\u0004 \u0005[על סופה,\u0006 במקרה האחרון\u0005]\u0006 שאמר לה שהוא מקדש אותה בכל התמרים, אזי אם אכלה אחת אחת אינה מקודשת עד שיהיה באחת מהן שווה פרוטה.","ויש לשאול: \u0003ואפילו\u0004 אם \u0003בקמייתא\u0004 \u0005[ב\u0006תמרה \u0005הראשונה]\u0006 יש שווה פרוטה הריהי מקודשת בכך? \u0003והא\u0004 \u0005[והרי]\u0006 הואיל ואינה מקודשת עד שתזכה בכל התמרים שהרי קידשה בכולן, תמרה זו הראשונה \u0003מלוה היא,\u0004 שלאחר שאכלה שוב אין התמרה הראשונה (של קידושין), אלא חוב שהיא צריכה להחזיר לו, וכלל הוא: המקדש במלוה אינה מקודשת! \u0003אמר ר' יוחנן\u0004 כאשר עיין בקושי זה שבמשנה: \u0003הרי שלחן, והרי בשר, והרי סכין\u0004 — \u0003ואין לנו לאכול.\u0004 כלומר, לכאורה הכל מפורש, ואולם איננו יכולים להסביר את הדברים.","ואילו \u0003רב ושמואל אמרי תרוייהו\u0004 \u0005[אמרו שניהם]:\u0006 \u0003לעולם\u0004 תפרש שקטע זה מוסב \u0003ארישא\u0004 \u0005[על ראשה\u0006 של המשנה\u0005]\u0006 שמקדש בכל תמרה לחוד, \u0003ו\u0004בלשון \u0003לא מיבעיא קאמר\u0004 \u0005[נצרכה אמר],\u0006 וכך יש להבין: \u0003לא מיבעיא\u0004 \u0005[נצרכה\u0006 לומר\u0005]\u0006 כשהיתה \u0003מנחת\u0004 את התמרות ברשותה, \u0003דאי איכא\u0004 \u0005[שאם יש]\u0006 \u0003שוה פרוטה\u0004 באחת — \u0003אין\u0004 \u0005[כן],\u0006 הרי היא מקודשת, \u0003אי\u0004 \u0005[אם]\u0006 \u0003לא\u0004 — \u0003לא. אבל\u0004 שמא אם היתה \u0003אוכלת, הואיל ומיקרבא הנייתה\u0004 \u0005[וקרובה הנאתה],\u0006 שהרי היא נהנית מיד ממה שנתן לה, \u0003אימא גמרה ומקניא נפשה\u0004 \u0005[אמור\u0006 ש\u0005גומרת\u0006 בדעתה \u0005ומקנה\u0006 את \u0005עצמה]\u0006 בתמרה זו, אף שאינה שווה פרוטה על כן \u0003קא משמע לן\u0004 \u0005[השמיע לנו]\u0006 שבכל זאת אינה מקודשת.","\u0003ר' אמי אמר\u0004 הסבר אחר: \u0003לעולם\u0004 תפרש שהדברים מוסבים \u0003אסיפא\u0004 \u0005[על הסוף]\u0006 שקידש אותה בכל התמרים, \u0003ומאי\u0004 \u0005[ומה]\u0006 הכוונה \u0003\"עד שיהא באחת מהן שוה פרוטה\"\u0004 — הכוונה: \u0003עד שיהא באחרונה שוה פרוטה,\u0004 אבל אם היה רק באחת מן התמרים האחרות שווה פרוטה — אינה מקודשת, כי דינן משנאכלו, כדין מלוה.","\u0003אמר רבא: שמע מינה\u0004 \u0005[למד מכאן]\u0006 \u0003מ\u0004דברי \u0003ר' אמי תלת\u0004 \u0005[שלשה\u0006 דברים\u0005]\u0006 בהלכה, שמתוך דבריו אפשר להסיק אותם; \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003המקדש\u0004 אשה \u0003במלוה,\u0004 שהוא מוחל לה חוב שהיא חייבת לו — \u0003אינה מקודשת,\u0004 וכמו כן אינה מקודשת בתמרה שאכלה כבר, \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 גם ש\u0003המקדש במלוה ופרוטה,\u0004 אם הוא מקדש אשה על ידי זה שמוחל מלוה גדול וגם נותן לה פרוטה, אף שסכום המלוה גדול בהרבה, בכל אופן \u0003דעתה\u0004 על ה\u0003פרוטה\u0004 ואין אומרים שהיתה דעתה על המלוה, ואת הפרוטה לא החשיבה. שהרי כאן אכלה תמרים הרבה ויש כאן מלוה גדול יותר מאשר בתמרה האחרונה השווה רק פרוטה, ובכל זאת היא מתקדשת בתמרה זו."],["\u0003ושמע מינה\u0004 \u0005[ולמד מכאן]:\u0006 \u0003מעות בעלמא\u0004 \u0005[סתם]\u0006 של קידושין שלא חלו — \u0003חוזרים,\u0004 שאם נתן לאשה מעות לשם קידושין, ולא חלו הקידושין — אין אנו אומרים שנתן לה את המעות הללו כמתנה, אלא הרי הם כמלוה וחייבת להחזירם. שהרי במשנתנו התמרים שאכלה אינן נחשבות לה כנתינה לשם קידושין אלא כמלוה, ואינה מתקדשת אלא בתמרה אחרונה באם שווה פרוטה.","\u0003איתמר\u0004 \u0005[נאמר]\u0006 שנחלקו אמוראים בבעיה זו: \u0003המקדש אחותו\u0004 ונתן לה כסף קידושין, וללא ספק אין כאן קידושין שהרי היא ערוה עליו; \u0003רב אמר: מעות\u0004 הקידושין \u0003חוזרים,\u0004 שחייבת האחות להחזיר את המעות הללו שנתן לה כביכול לשם קידושין. \u0003ושמואל אמר: מעות\u0004 אלה \u0003מתנה\u0004 הן והריהן שלה. ומסבירים את טעמיהם: \u0003רב אמר: מעות חוזרים;\u0004 וטעמו — \u0003אדם יודע שאין קידושין תופסין באחותו, וגמר\u0004 בדעתו \u0003ונתן\u0004 לה את המעות \u0003לשום\u0004 (לשם) \u0003פקדון.\u0004 ומקשים: \u0003ולימא\u0004 \u0005[ושיאמר]\u0006 \u0003לה\u0004 במפורש שנותן לה \u0003לשום פקדון?\u0004 ומשיבים: \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 ש\u0003לא מקבלה\u0004 \u0005[תקבל]\u0006 ממנו, ולכן אמר בלשון זו.","\u0003ושמואל סבר: מעות מתנה\u0004 הן, ומאותו טעם: \u0003אדם יודע שאין קידושין תופסין באחותו, וגמר ונתן לשום מתנה.\u0004 ושואלים: \u0003ונימא\u0004 \u0005[שיאמר]\u0006 \u0003לה\u0004 במפורש שהוא נותן לה \u0003לשום מתנה?\u0004 ומשיבים: \u0003סבר\u0004 \u0005[סבור\u0006 הוא\u0005]:\u0006 \u0003כסיפא\u0004 \u0005[בושה]\u0006 יש \u0003לה מילתא\u0004 \u0005[\u0006ב\u0005דבר]\u0006 ולכן לא תרצה לקבל את הכסף ולפיכך נתן לה בדרך זו.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 על כך \u0003רבינא\u0004 ממה ששנינו במשנה: \u0003המפריש חלתו\u0004 כשהיא \u0003קמח,\u0004 ועדיין לא נעשתה עיסה — מה שהפריש \u0003אינו חלה,\u0004 כיון שאמרה תורה \"ראשית עריסותיכם\", שאין מפרישים אלא מן העיסה, \u0003ו\u0004מה שנתן הוא \u0003גזל ביד\u0004 ה\u0003כהן,\u0004 אם אין הכהן מחזירו. ויש לשאול: \u0003ואמאי\u0004 \u0005[ומדוע]\u0006 הוא \u0003גזל ביד\u0004 ה\u0003כהן? נימא\u0004 \u0005[נאמר]\u0006 גם כאן כסברת שמואל: \u0003אדם יודע שאין מפרישים חלה\u0004 בעודה \u0003קמח, ו\u0004אם כן מה שנתן — \u0003נתן לשם מתנה,\u0004 ולא לשם חלה!","ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 שאנו מחייבים אותו להחזיר, שאם לא כן \u0003נפיק חורבה מינה\u0004 \u0005[\u0006פעמים \u0005יוצאת תקלה מזה].\u0006 כיצד? \u0003זימנין דאית ליה\u0004 \u0005[פעמים שיש לו]\u0006 \u0003לכהן פחות מחמש רבעים\u0004 של קב \u0003קמח\u0004 ובפחות משיעור זה אין חובת חלה על העיסה, \u0003והאי\u0004 \u0005[ו\u0006את הקמח ה\u0005זה]\u0006 שקיבל לשם חלה, \u0003אליש ליה בהדי הדדי\u0004 \u0005[ילוש אותו יחד]\u0006 עם הקמח שלו, \u0003וקסבר\u0004 \u0005[ו\u0006הוא \u0005סבור]\u0006 \u0003נתקנה עיסתו\u0004 לענין חלה, שאין צורך להפריש ממנה, שהקמח שלו עצמו לא היה חייב בחלה, ומה שהוסיף הוא חלה \u0003ואתי למיכלה בטיבלה\u0004 \u0005[ויבוא לאכול אותה\u0006 בעודה \u0005טבל\u0006 (בלתי מתוקנת)\u0005],\u0006 שכן קמח זה שקיבלו באמת אינו חלה, והוא מצטרף עם הקמח שלו לחייב הפרשת חלה מן העיסה.","ומקשים: \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 ש\u0003אדם יודע שאין מפרישים חלה\u0004 בעודה \u0003קמח,\u0004 וכיצד יכול גם הכהן לטעות בכך? ומשיבים: אמנם \u0003אדם\u0004 \u0003יודע ו\u0004אולם \u0003אינו יודע\u0004 מספיק; \u0003יודע\u0004 הוא \u0003שאין מפרישים חלה\u0004 בעודה \u0003קמח, ואינו יודע\u0004 לגמרי, \u0003דסבר\u0004 \u0005[ש\u0006הוא \u0005סבור]:\u0006 \u0003טעמייהו מאי\u0004 \u0005[טעמם\u0006 של החכמים \u0005מהו],\u0006 מדוע אמרו שאין מפרישים חלה מן הקמח — \u0003משום טירחא\u0004 \u0005[וטירחה]\u0006 של ה\u0003כהן\u0004 שרוצים למנוע ממנו את הטירחה ללוש בעצמו, ולכן אמרו שיקבל עיסה גמורה \u0003וטירחא\u0004 \u0005[ו\u0006את \u0005הטירחה]\u0006 של ה\u0003כהן אחילתיה\u0004 \u0005[מחלתי]\u0006 בעצמי.","ומקשים מצד אחר: ומדוע נטריח את הכהן להחזיר את הקמח לבעליו \u0003ותיהוי\u0004 \u0005[ותהיה]\u0006 הפרשה זו של קמח נחשבת מדברי חכמים \u0003תרומה, ולא תאכל\u0004 על ידי הכהן \u0003עד שיוציא עליה חלה ממקום אחר\u0004 לתקן אותה. \u0003מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 כיוצא בזה: אם נתן תרומה \u0003מן\u0004 הצמחים שצמחו בכלי \u0003הנקוב\u0004 שדינם כגידולי קרקע ממש וחייבים בהפרשת תרומות ומעשרות מן התורה, \u0003על\u0004 מה שצמח בכלי \u0003שאינו נקוב,\u0004 שמדין תורה אינו חייב כלל בהפרשת תרומות ומעשרות — למרות שמעיקר הדין לא עשה כלום והם עדיין טבל, הרי זו \u0003תרומה\u0004 ונשארת ברשות הכהן, \u0003ולא תאכל עד שיוציא עליה תרומה ומעשר מ\u0004פירות שצמחו ב\u0003מקום אחר\u0004 החייב מן התורה בהפרשת תרומות ומעשרות, ומדוע לא אמרו גם בחלה כעין זה?","ומשיבים: לגבי דבר שנמצא \u0003בתרי מני\u0004 \u0005[בתרי כלים]\u0006 לחוד — \u0003צאית\u0004 \u0005[מציית]\u0006 הכהן, שמאחר שהוא יודע שהיו כאן שני כלים, וכגון בהפרשת תרומות ומעשרות שיש הבדל ברור בין הכלי נקוב לכלי שאינו נקוב, מבין הכהן את הדבר ומקבל את דברי חכמים, אבל אם היה הדבר \u0003בחד מנא\u0004 \u0005[בכלי אחד]\u0006 — \u0003לא צאית\u0004 \u0005[איננו מציית],\u0006 וכגון בהפרשת חלה שאינו מבין את ההבדל אם קיבל קמח או עיסה, ולכן לא יציית לדברי חכמים ומשום כך הצריכוהו להחזיר את הקמח לבעלים.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 שהתנא חושש מטעם אחר: \u0003לעולם\u0004 תפרש כי ה\u0003כהן מיצת ציית\u0004 \u0005[\u0006ודאי \u0005יציית]\u0006 גם בכלי אחד ואין לחשוש לתקלה שתגרם על ידי הכהן, \u0003ו\u0004אולם החשש הוא אחר, כי \u0003קסבר\u0004 \u0005[סבור\u0006 הוא\u0005]\u0006 \u0003בעל הבית\u0004 שהפריש את חלתו קמח ש\u0003נתקנה\u0004 בכך \u0003עיסתו, ואתי למיכל בטיבלא\u0004 \u0005[ויבוא לאכול\u0006 אותה \u0005בעודה טבל].\u0006","ומקשים: \u0003והאמרת\u0004 \u0005[והרי אמרת]\u0006 \u0003אדם יודע שאין מפרישין חלה\u0004 בעודה \u0003קמח!\u0004 ומשיבים: \u0003יודע ואינו יודע; יודע שאין מפרישין חלה קמח, ואינו יודע\u0004 מספיק. \u0003דסבר טעמא מאי\u0004 \u0005[שסבור\u0006 הוא \u0005שהועם מהו]\u0006 — \u0003משום טירחא\u0004 \u0005[הטירחה]\u0006 של ה\u0003כהן,\u0004 ואת ה\u0003טירחא\u0004 של ה\u0003כהן\u0004 הרי \u0003קבלה עליה\u0004 \u0005[קיבל עליו]\u0006 הכהן, שהרי לא החזיר לו את הקמח וסבור שחלה היא.","ומקשים: ומדוע לא נאמר \u0003ותיהוי\u0004 \u0005[ותהא\u0006 זו\u0005]\u0006 \u0003תרומה, ויחזור ויתרום. מי\u0004 \u0005[האם]\u0006 \u0003לא תנן\u0004 \u0005[שנינו]\u0006 כיוצא בזה בהלכות תרומות: אם תרם \u0003מ\u0004פירות שצמחו בכלי \u0003שאינו נקוב על\u0004 פירות שצמחו בכלי \u0003הנקוב\u0004 — הרי זו \u0003תרומה, ויחזור ויתרום!\u0004 ומשיבים: \u0003הא אוקימנא\u0004 \u0005[הרי\u0006 כבר \u0005העמדנו]\u0006 ש\u0003בתרי מאני צאית, בחד מנא לא צאית\u0004 \u0005[בשני כלים\u0006 נבדלים ניכר לו ההבדל ביניהם \u0005ומציית, בכלי אחד אינו מציית].\u0006","על ההנחה הזו תוהים: \u0003ו\u0004כי \u0003לא צאית\u0004 \u0005[מציית]\u0006 אדם לחזור ולתרום אפילו בדבר אחד?! \u0003והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 \u0003התורם קישות\u0004 מן הקישואין לכהן \u0003ונמצא\u0004 שאותה קישות \u0003מרה\u0004 היתה, שאינה ראויה לאכילה, או תרם \u0003אבטיח\u0004 מן האבטיחים \u0003ונמצאת סרוח\u0004 — מה שתרם הרי זה \u0003תרומה, ו\u0004אולם \u0003יחזור ויתרום!\u0004 ומשיבים: \u0003שאני התם\u0004 \u0005[שונה שם]\u0006 \u0003דמדאורייתא\u0004 \u0005[שמן התורה]\u0006 \u0003תרומה מעליא\u0004 \u0005[מעולה,\u0006 גמורה\u0005]\u0006 \u0003היא\u0004 ולכן גם אם לא יציית ולא יתרום לא תצא תקלה מזה.","וכיצד יודעים שתרומה גמורה היא — \u0003מ\u0004דברי \u0003ר' אלעאי.\u0004 ש\u0003אמר ר' אלעאי: מנין לתורם\u0004 ונותן \u0003מן\u0004 התבואה \u0003הרעה על\u0004 (עבור) \u0003היפה שתרומתו תרומה\u0004 — \u0003שנאמר\u0004 בענין תרומה: \u0003\"ולא תשאו עליו חטא בהרימכם את חלבו\u0004 ממנו\u0003\"\u0004 (במדבר יח, לב), ו\"חלבו\" הכוונה לחלק הטוב, המובחר שבו, ומכאן הוא מדייק, שהתורה אומרת שצריך לתת את הדבר הטוב כתרומה, ואם נתן דבר גרוע משמע שעושה בכך עבירה (\"תשאו עליו חטא\"). אך מכל מקום אפשר להבין מכאן שתרומה זו נחשבת, כי \u0003אם אינו קדוש\u0004 ולא חלה התרומה \u0003נשיאות חטא למה?\u0004 שאם לא עשה דבר בהפרשת תרומה זו, נמצא שלא חטא. \u0003מכאן לתורם מן הרעה על היפה שתרומתו תרומה.\u0004","\u0003אמר רבא:\u0004"],["\u0003לא שנו\u0004 במשנתנו שכשאוכלת את התמרות ראשונה ראשונה שאין התמרות מצטרפות לכדי שווה פרוטה \u0003אלא\u0004 כש\u0003אמר לה\u0004 שתתקדש לו \u0003\"בזו ובזו ובזו\",\u0004 שמשמעו שאינה מקודשת אלא לאחר שקיבלה את כולן ומשום כך כל אחת שאכלה נחשבת כמלוה ואינה מקודשת אלא באחרונה בלבד. \u0003אבל\u0004 אם \u0003אמר לה\u0004 שמתקדשת \u0003\"באלו\"\u0004 יחדיו — \u0003אפילו אוכלת\u0004 אחת אחת \u0003נמי\u0004 \u0005[גם כן]\u0006 \u0003מקודשת,\u0004 ואפילו אם היה שווה פרוטה בכולן ביחד, ו\u0003כי קא אכלה\u0004 \u0005[וכאשר היא אוכלת]\u0006 — \u0003מדנפשה קאכלה\u0004 \u0005[משל עצמה היא אוכלת],\u0006 שלאחר שנתן לה אותן ככסף קידושין הרי הן כבר רכושה, ונתקדשה לו בקבלתן.","ומעירים: \u0003תניא כותיה\u0004 \u0005[שנוייה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רבא.\u0004 ששנינו: אמר לאשה \u0003\"התקדשי לי באלון ברמון ובאגוז\", או שאמר לה \"התקדשי לי באלו\", אם יש בכולן שוה פרוטה\u0004 — \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת.\u0004 ואם אמר \u0003\"\u0004התקדשי \u0003בזו ובזו ובזו\", אם יש בכולם שוה פרוטה\u0004 — \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת.\u0004 אמר לה \u0003\"\u0004הרי את מקודשת \u0003בזו\"\u0004 — \u0003נטלתו ואכלתו, \"בזו\"\u0004 — \u0003נטלתו ואכלתו, \"ועוד בזו\" \"ועוד בזו\"\u0004 — \u0003אינה מקודשת עד שיהא באחת מהן שוה פרוטה.\u0004","עד כאן דברי הברייתא, ומעתה מביאים ממנה ראיה: \u0003האי\u0004 \u0005[זה]\u0006 הקטע הראשון באומר \u0003\"באלון ברמון באגוז\", היכי דמי\u0004 \u0005[כיצד בדיוק היה]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אמר לה:\u0004 \u0003\"או באלון, או ברמון, או באגוז\",\u0004 מדוע ההלכה היא ש\u0003אם יש בכולן שוה פרוטה מקודשת? והא\u0004 \u0005[והרי]\u0006 \u0003\"או\" קאמר\u0004 \u0005[אמר],\u0006 שפירש שאינו מקדשה בכולם אלא רק באחד מהם שתרצה וצריך שאחד מהם יהיה שווה פרוטה! \u0003ואלא\u0004 תאמר שאמר לה \u0003\"באלון וברמון ובאגוז\"\u0004 יחד — אם כן \u0003היינו\u0004 \u0005[זהו]\u0006 המקרה של \u0003\"בזו ובזו ובזו\"? אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 מדובר ש\u0003אמר לה\u0004 \u0003\"\u0004הרי את מקודשת \u0003באלו\",\u0004 ואולם \u0003הא מדקתני סיפא\u0004 \u0005[הרי ממה ששנה\u0006 ב\u0005סופה\u0006 בהמשך הברייתא\u0005]\u0006 את המקרה: \u0003או שאמר לה \"התקדשי לי באלו\"\u0004 — \u0003מכלל\u0004 הדברים אתה למד \u0003דרישא לאו\u0004 \u0005[שבראשה לא]\u0006 \u0003ב\u0004מקרה של האומר \u0003\"אלו\" עסקינן\u0004 \u0005[עוסקים אנו]\u0006 ואם כן לכאורה מיותרת הלכה זו בברייתא, אלא שיש להבין את המשנה כדין כללי שאחריו","\u0003פירושי קא מפרש\u0004 \u0005[מפרש\u0006 הוא\u0005]\u0006 התנא את הדברים. וכך יש להבין: אם אמר לאשה \u0003\"התקדשי לי באלון ברמון באגוז\", כיצד? כגון\u0004 ש\u0003אמר לה \"התקדשי לי באלו\".\u0004","וממשיכים בהוכחה \u0003וקתני סיפא\u0004 \u0005[ושנה\u0006 ב\u0005סופה]\u0006 של הברייתא אופן שני שאמר לה הרי את מקודשת \u0003\"בזו\"\u0004 ו\u0003נטלתו ואכלתו, אם יש באחת מהם שוה פרוטה\u0004 — \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת.\u0004","\u0003ואילו רישא\u0004 \u0005[\u0006ב\u0005ראשה],\u0006 בהלכה הראשונה, \u0003לא קא מפליג\u0004 \u0005[אינו מחלק]\u0006 \u0003בין אוכלת\u0004 את התמרות \u0003למנחת\u0004 אותן ברשותה, שבכל אופן היא מקודשת. \u0003שמע מינה\u0004 \u0005[למד מכאן]:\u0006 \u0003כל היכא\u0004 \u0005[מקום]\u0006 ש\u0003אמר לה \"באלו\"\u0004 והיה בכולם שווה פרוטה \u0003כי קא אכלה\u0004 \u0005[כאשר היא אוכלת]\u0006 — \u0003מנפשה קא אכלה\u0004 \u0005[משל עצמה היא אוכלת]\u0006 ואין זה מלוה. ומסכמים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא כדברי רבא.","ושואלים: \u0003הניחא למאן דאמר\u0004 \u0005[\u0006ברייתא \u0005זו נוחה למי שאומר,\u0006 מפרש\u0005]\u0006 (ר' אמי) שההלכה במשנה באוכלת ראשונה ראשונה \u0003אסיפא קאי\u0004 \u0005[על סוף\u0006 המשנה (\"בזו ובזו\") היא \u0005עומדת,\u0006 מתייחסת\u0005]\u0006 \u0003ומאי\u0004 \u0005[ומה]\u0006 פירוש \u0003\"\u0004אינה מקודשת \u0003עד שיהא באחת מהן שוה פרוטה\"\u0004 — הכוונה היא: \u0003עד שיהא באחרונה שוה פרוטה,\u0004 אם כן \u0003הכי נמי\u0004 \u0005[כך גם כן]\u0006 בברייתא אפשר לפרש בדרך זו: \u0003עד שיהא באחרונה שוה פרוטה.\u0004","\u0003אלא ל\u0004דעת \u0003רב ושמואל דאמרי תרוייהו\u0004 \u0005[שאומרים שניהם]:\u0006 שההלכה במשנה בענין אוכלת \u0003ארישא קאי\u0004 \u0005[על תחילת המשנה\u0006 היא \u0005עומדת,\u0006 מתייחסת\u0005]\u0006 \"התקדשי לי בזו, התקדשי לי בזו\" אם יש באחת מהן שוה פרוטה מקודשת, \u0003ואוכלת איצטריכא ליה\u0004 \u0005[הוצרכה לו]\u0006 לומר, אף על פי שיש לה הנאה מיידית, אם אין באחת מהן שווה פרוטה אינה מקודשת — איך נפרש את הברייתא \"עד שיהא באחת מהן שווה פרוטה\", שהרי \u0003הכא\u0004 — \u0003כללי קחשיב, פרטי לא קא חשיב\u0004 \u0005[כאן\u0006 בברייתא \u0005כללים\u0006 הוא \u0005מונה, פרטים אינו מונה]\u0006 שהרי כשאומר \"בזו ובזו ובזו\" אינו דן אותם כפרטים, שתתקדש בכל אחד לחוד, אלא בכולם יחד.","ומשיבים: \u0003הא מני\u0004 \u0005[\u0006הלכה \u0005זו\u0006 שבברייתא כשיטת \u0005מי היא]\u0006 — כשיטת \u0003רבי היא,\u0004 ש\u0003אמר:\u0004 בהלכות פיגול קרבנות, אם אמר שיאכל כזית מהקרבן חוץ לזמנו, וכזית מהקרבן חוץ למקומו \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 אם אומר בלשון \u0003\"כזית כזית\", ולא שנא\u0004 \u0005[ואינו שונה]\u0006 אם הוא אומר \u0003\"כזית וכזית\",\u0004 שניהם \u0003פרטא הוי\u0004 \u0005[פרטים הם],\u0006 שהאומר כן אינו מתכוון לכלול ולצרף את הפרטים, אלא כמתייחס לכל פרט לעצמו. ושיטת רבי אינה כשיטת המשנה, אלא לדעתו \"בזו ובזו\" הם פרטים, ולכן אף שאוכלת מה שנתן לה והנאתה מיידית, אם אין באחת מהן שווה פרוטה — אינה מקודשת.","\u0003אמר רב: המקדש במלוה\u0004 שהלווה לפני כן כסף לאשה, ומקדשה בסכום זה שהיא חייבת לו — \u0003אינה מקודשת,\u0004 כי \u0003מלוה להוצאה ניתנה.\u0004 שכסף ההלוואה במהותו אינו ניתן כדי שישאר בעינו אלא להוציא אותו על ידי הלווה, ולכן מזמן שניתן כסף המלוה אינו נחשב עוד כלל כרכושו של המלווה, ואינו יכול לקדש בו. ומציעים: \u0003נימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שהדבר הזה שנוי במחלוקת \u0005תנאים],\u0006 ששנינו בברייתא: \u0003המקדש במלוה אינה מקודשת, ויש אומרים: מקודשת. מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006דבר \u0005זה\u0006 הם \u0005חלוקים],\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה סבור]\u0006 ש\u0003מלוה להוצאה ניתנה, ומר סבר\u0004 \u0005[וחכם זה\u0006 \u0005סבור]\u0006 \u0003מלוה לאו\u0004 \u0005[לא]\u0006 \u0003להוצאה ניתנה?\u0004","ותוהים: \u0003ותסברא\u0004 \u0005[וסבור אתה]\u0006 שאפשר לומר כן?! \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של אותה ברייתא: \u0003ושוים במכר שזה קנה,\u0004 שיכול המלווה לקנות דבר מה מהלווה על ידי שמקנה ללווה את כסף ההלוואה תמורת החפץ. ועתה \u0003אי אמרת\u0004 \u0005[אם אומר\u0006 \u0005אתה]\u0006 ש\u0003מלוה להוצאה ניתנה,\u0004 אם כן \u0003במאי קני\u0004 \u0005[במה\u0006 הוא \u0005קונה]?!\u0006 והרי אין כאן דבר שיחול הקנין על ידו! אלא ברור שאין להבין ברייתא זו כמשמעה ואין להוכיח ממנה דבר.","\u0003אמר רב נחמן:\u0004 רב \u0003הונא חברין\u0004 \u0005[חבירנו]\u0006 \u0003מוקים לה במילי אוחרי\u0004 \u0005[מעמיד,\u0006 מסביר, \u0005אותה\u0006 את המחלוקת \u0005בדברים אחרים]\u0006 ולא במקרה פשוט, \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — במקרה מסויים, \u0003כגון שאמר לה \"התקדשי לי במנה\" ונמצא\u0004 שהיה ה\u0003מנה חסר דינר\u0004 והרי הוא עליו כמלוה. \u0003מר\u0004 \u0005[חכם זה]\u0006 שאמר: אינה מקודשת \u0003סבר: כסיפא\u0004 \u0005[בושה]\u0006 \u0003לה מילתא למיתבעיה\u0004 \u0005[הדבר לתבוע ממנו]\u0006 את הדינר הנוסף, ונמצא שלא קיים את התנאי, ולא חלו הקידושין. \u0003ומר\u0004 \u0005[וחכם זה]\u0006 \u0003סבר: לא כסיפא\u0004 \u0005[בושה]\u0006 \u0003לה מילתא למיתבעיה\u0004 \u0005[הדבר לתבוע אותו],\u0006 ולכן האיש נחשב כאילו לווה ממנה דינר וישלם אותו במשך הזמן, ולכן היא מקודשת.","ומקשים: \u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר ר' אלעזר:\u0004 אמר לאשה \u0003\"התקדשי לי במנה\" ונתן לה דינר\u0004 — \u0003הרי זו מקודשת, וישלים\u0004 אחר כך את החסר, \u0003לימא כתנאי אמרה לשמעתיה\u0004 \u0005[\u0006האם \u0005לומר\u0006 ש\u0005במה\u0006 שחלקו \u0005תנאים אמר את דבריו]?\u0006 ומשיבים שיש להבדיל בין המקרים, \u0003אמרי\u0004 \u0005[אומרים]:\u0006 במקרה שנתן לה \u0003מנה חסר דינר כסיפא\u0004 \u0005[בושה]\u0006 \u0003לה מילתא למיתבעיה\u0004 \u0005[הדבר לתבוע אותו]\u0006 את הדינר, שהרי נתן לה כמעט את כל הסכום, אבל אם נתן לה \u0003מנה חסר תשעים ותשע לא כסיפא\u0004 \u0005[בושה]\u0006 \u0003לה מילתא למיתבעיה\u0004 \u0005[הדבר לתבוע אותו],\u0006 את ההפרש, שהרי לא נתן לה כמעט ולא כלום ולפיכך היא מקודשת לפי כולם.","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי רב ממה ששנינו בברייתא: \u0003האומר לאשה \"התקדשי לי בפקדון\u0004 שלי \u0003שיש לי בידך\" והלכה ומצאתו שנגנב\u0004 הפקדון \u0003או שאבד, אם נשתייר הימנו\u0004 (ממנו) \u0003שוה פרוטה\u0004 — \u0003מקודשת\u0004 בשווה הפרוטה שנשתייר, \u0003ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת,\u0004 שהרי עתה אין כאן דבר שיכול לקדשה בו. \u0003ו\u0004אולם אם אמר לה שמקדשה \u0003במלוה\u0004 שהילווה לה, \u0003אף על פי שלא נשתייר הימנו שוה פרוטה\u0004 — \u0003מקודשת. ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003ר' מאיר: מלוה\u0004"],["\u0003הרי היא כפקדון.\u0004 ונדייק: \u0003עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא דמר\u0004 \u0005[שחכם זה]\u0006 \u0003סבר: מלוה, אף על גב שלא נשתייר הימנה\u0004 (ממנה) \u0003שוה פרוטה\u0004 אפשר לקדש בו, \u0003ומר סבר: נשתייר הימנה שוה פרוטה\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003לא נשתייר הימנה שוה פרוטה\u0004 — \u0003לא. אבל דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 ה\u0003מקדש במלוה מקודשת!\u0004 וקשה על רב שאמר המקדש במלוה אינה מקודשת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא: ותסברא, הא מתרצתא\u0004 \u0005[וסבור אתה\u0006 ש\u0005זו\u0006 הברייתא \u0005מתורצת\u0006 ומיושבת היא\u0005]?\u0006 \u0003הא משבשתא\u0004 \u0005[זו משובשת]\u0006 \u0003היא,\u0004 שאין גירסתה מדוייקת, ואין להביא ראיה ממנה.","וכיצד אפשר להוכיח שהיא משובשת — \u0003האי\u0004 \u0005[זה]\u0006 ה\u0003פקדון\u0004 שמדובר בו בברייתא \u0003היכי דמי\u0004 \u0005[איך היה בדיוק]?\u0006 \u0003אי דקביל עליה\u0004 \u0005[אם שקיבלה עליה]\u0006 \u0003אחריות\u0004 שאף אם ייגנב או יאבד תתחייב לשלם למפקיד, אם כן \u0003היינו\u0004 \u0005[זה הוא]\u0006 \u0003מלוה,\u0004 שהרי גם לאחר שאבד ולא נשתייר ממנו כלום — חייבת היא לפרוע את דמיו. \u0003אי\u0004 \u0005[אם]\u0006 ש\u0003לא קביל עליה\u0004 \u0005[קיבלה עליה]\u0006 \u0003אחריות\u0004 — \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003אדתני סיפא\u0004 \u0005[עד ש\u0006הוא \u0005שונה\u0006 ב\u0005סוף\u0006 הברייתא\u0005]:\u0006 \u0003ובמלוה, אף על פי שלא נשתייר הימנה שוה פרוטה מקודשת\u0004 — \u0003ניפלוג וניתני בדידה\u0004 \u0005[יחלק וישנה ב\u0006דברי הברייתא \u0005עצמה]\u0006 חלוקה אחרת קרובה יותר: \u0003במה דברים אמורים\u0004 שאם לא נשתייר בפקדון שווה פרוטה אינה מקודשת — זהו דווקא \u0003שלא קבלה עליה אחריות, אבל\u0004 אם \u0003קבלה עליה אחריות, אף על גב\u0004 ש\u0003לא נשתייר הימנה שוה פרוטה\u0004 הריהי \u0003מקודשת!\u0004","\u0003אלא\u0004 כיון שבהכרח עלינו לתקן את גירסת הברייתא, \u0003תריץ הכי\u0004 \u0005[תקן כך]:\u0006 \u0003ובמלוה, אף על פי שנשתייר הימנה שוה פרוטה\u0004 — \u0003אינה מקודשת.\u0004","שנינו בברייתא ש\u0003ר' שמעון בן אלעזר אומר משום\u0004 (בשם) \u0003ר' מאיר: מלוה הרי היא כפקדון.\u0004 ושואלים: \u0003במאי קמיפלגי\u0004 \u0005[במה,\u0006 באיזה עקרון אחר הם \u0005חלוקים]?\u0006 \u0003אמר רבה: אשכחתינהו לרבנן בבי\u0004 \u0005[מצאתים, את החכמים בבית\u0006 מדרשו\u0005]\u0006 של \u0003רב דיתבי וקאמרי\u0004 \u0005[שיושבים ואומרים]:\u0006 \u0003ב\u0004שאלה האם \u0003מלוה\u0004 שלא החל הלווה להוציאו עומד \u0003ברשות\u0004 ה\u0003בעלים\u0004 לקחת אותו ב\u0003חזרה,\u0004 בכל זמן שירצו, \u0003והוא הדין ל\u0004עניין אחריות לגבי \u0003אונסין, קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005]\u0006 על מי חל החיוב,","\u0003דמר סבר\u0004 \u0005[שחכם זה סבור]:\u0006 \u0003מלוה ברשות לוה קיימא\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 \u0003והוא הדין לאונסים,\u0004 שאם אירע אונס ואבד הכסף הרי הוא ברשות הלווה, ואחריותו עליו. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון בן אלעזר, \u0005סבור]:\u0006 \u0003מלוה\u0004 שלא הספיק הלווה להוציאו \u0003ברשות\u0004 ה\u0003בעלים קיימא\u0004 \u0005[\u0006הוא \u0005עומד],\u0006 \u0003והוא הדין לאונסים.\u0004 ומשום כך יכול הוא לקדש אשה בכסף שהלווה לה.","\u0003ואמינא להו\u0004 \u0005[ואמרתי להם]:\u0006 \u0003לאונסים\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם חלוקים]\u0006 כי \u0003ברשות\u0004 ה\u0003לוה קיימי\u0004 \u0005[עומדים\u0006 הם\u0005]\u0006 וחייב באחריותם, \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 — הלוואה \u0003לא גרעא משאלה\u0004 \u0005[אינה גרועה,\u0006 פחותה, \u0005מהשאלה],\u0006 \u0003מה שאלה דהדרה בעינא\u0004 \u0005[ש\u0006החפץ \u0005חוזר בעינו]\u0006 לבעליו ובכל זאת \u0003חייב\u0004 השואל \u0003באונסים\u0004 כמפורש בתורה, \u0003מלוה\u0004 שהוא מוציא אותו ואינו מחזירו בעינו \u0003לא כל שכן\u0004 שהוא נחשב כעומד ברשות הלווה, וחייב באחריותו. \u0003אלא הכא\u0004 \u0005[כאן]\u0006 רק בשאלה של \u0003מלוה ברשות\u0004 ה\u0003בעלים ל\u0004ענין \u0003חזרה איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 הבדל\u0005],\u0006 ובענין זה נחלקו שלדעת חכמים אינו יכול לחזור בו, ולדעת ר' אליעזר בר' שמעון יכול.","ושואלים: \u0003ואלא הא\u0004 \u0005[זו]\u0006 ש\u0003אמר רב הונא: השואל קורדום מחבירו\u0004 למשך זמן מסויים, אם \u0003ביקע בו\u0004 עץ או עשה בו מלאכה אחרת — \u0003קנאו\u0004 לענין ההשאלה, שאין המשאיל יכול לחזור בו ולבקש מיד את הקרדום בחזרה. \u0003לא ביקע בו\u0004 — \u0003לא קנאו. לימא כתנאי אמרה לשמעתיה\u0004 \u0005[האם נאמר\u0006 ש\u0005כ\u0006דבר השנוי במחלוקת \u0005תנאים אמר את הלכתו זו]?\u0006 שהרי כפי שהסביר רבה, בזו נחלקו חכמים ור' שמעון בן אלעזר.","ודוחים: \u0003לא, עד כאן לא\u0004 שמענו כי \u0003פליגי\u0004 \u0005[נחלקו]\u0006 \u0003אלא במלוה\u0004 בהלוואה \u0003דלא הדרה בעינא\u0004 \u0005[שאינה חוזרת בעינה]\u0006 ולכן בעצם מעשה ההלוואה עבר הכסף לרשות הלווה, ומשום כך סבורים חכמים שאינו יכול לחזור. \u0003אבל בשאלה דהדרה בעינא\u0004 \u0005[שחוזרת בעינה]\u0006 ל\u0003דברי הכל,\u0004 דווקא אם \u0003ביקע בו\u0004 — \u0003אין\u0004 \u0005[כן],\u0006 קנה אותו ונתחייב באונסיו, \u0003לא ביקע בו\u0004 — \u0003לא קנאו.\u0004","ומציעים: \u0003נימא כתנאי\u0004 \u0005[האם נאמר\u0006 שדברי רב שמקדש במלוה אינה מקודשת תלויים במחלוקת \u0005תנאים]?\u0006 ששנינו: אמר לאשה \u0003\"התקדשי לי בשטר חוב\", או שהיה לו מלוה ביד אחרים והירשה עליהם,\u0004 שנתן לה הרשאה = ייפוי כח לגבות את המלוה לעצמה — \u0003ר' מאיר אומר: מקודשת, וחכמים אומרים: אינה מקודשת.\u0004 ומעתה נברר: \u0003האי\u0004 \u0005[אותו]\u0006 \u0003שטר חוב היכי דמי\u0004 \u0005[כיצד היה בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003שטר חוב\u0004 ש\u0003אחרים\u0004 חייבים לו — \u0003היינו\u0004 \u0005[זהו]\u0006 אותו מקרה של \u0003מלוה ביד אחרים\u0004 ולמה נכפלו הדברים! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה היא \u0003שטר חוב דידה\u0004 \u0005[שלה]\u0006 שהיא חייבת לו, \u0003ו\u0004אם כן \u0003במקדש במלוה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 האם מחילת המלוה (על ידי החזרת שטר החוב) יכולה להיחשב ככסף קידושין.","ודוחים: \u0003לעולם\u0004 תפרש שמדובר ב\u0003שטר חוב\u0004 של \u0003אחרים, והכא\u0004 \u0005[וכאן]\u0006 \u0003במלוה בשטר ובמלוה על פה קא מיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 שיש שתי בעיות השנויות במחלוקת — הן לגבי הלוואה שיש עליה שטר, והן בזו שאין עליה שטר.","ומסבירים: \u0003במלוה בשטר במאי פליגי\u0004 \u0005[במה\u0006 הם \u0005חלוקים]\u0006 — \u0003בפלוגתא\u0004 \u0005[במחלוקת]\u0006 \u0003רבי ורבנן קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003אותיות,\u0004 כלומר, שטרות \u0003נקנות במסירה,\u0004 שאם מוסר המלווה שטר חוב לאדם שלישי — יכול המקבל לגבותו, אלו \u0003דברי רבי. וחכמים אומרים: בין שכתב\u0004 שטר מכירה על שטר החוב \u0003ולא מסר\u0004 את השטר עצמו, \u0003בין שמסר\u0004 את השטר \u0003ולא כתב\u0004 עליו שטר מכירה — \u0003לא קנה\u0004 המקבל \u0003עד שיכתוב וימסור.\u0004","ונפרש כי \u0003מר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005יש לו,\u0006 הריהו מקבל\u0005]\u0006 את שיטת \u0003רבי\u0004 ולכן יכול לקדש אשה בשטר חוב גם אם לא כתב עליו שטר מכירה. \u0003ומר לית ליה\u0004 \u0005[וחכם זה,\u0006 חכמים \u0005אין לו,\u0006 אינו מקבל\u0005]\u0006 את שיטת \u0003רבי,\u0004 ולפיכך אינה מקודשת שהרי לא קיבלה דבר.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור\u0006 כך\u0005]:\u0006 \u0003דכולי עלמא לית להו\u0004 \u0005[לדעת הכל אין להם,\u0006 אינם מקבלים\u0005]\u0006 את שיטתו של \u0003רבי והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004הלכה של \u0003רב פפא קמיפלגי\u0004 \u0005[חלוקים הם]:\u0006 ש\u0003אמר רב פפא: האי מאן דזבין שטרא לחבריה\u0004 \u0005[מי שמוכר שטר לחבירו],\u0006 \u0003צריך למיכתב ליה\u0004 \u0005[לכתוב לו]\u0006 בנוסח זה: \u0003\"קני\u0004 \u0005[ייקנה]\u0006 \u0003לך הוא וכל שעבודיה\u0004 \u0005[שיעבודיו]\u0006 \u0003\".\u0004 שאם לא כתב כן, לא הקנה לו אלא נייר בלבד. \u0003מר אית ליה\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005יש לו,\u0006 הריהו מקבל את דברי\u0005]\u0006 \u0003רב פפא, ומר לית ליה\u0004 \u0005[וחכם זה,\u0006 ר' מאיר, \u0005אין לו\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003רב\u0004\u0003פפא\u0004 וסבור שגם אם לא כתב בנוסח זה — יש בכך הקנאת החוב, ויכול לקדש בו.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא אית להו\u0004 \u0005[לדעת הכל יש להם,\u0006 הריהם מקבלים\u0005]\u0006 את דברי \u0003רב פפא\u0004 וגם לדעת ר' מאיר מקודשת דווקא אם כתוב בשטר \"קני לך הוא וכל שעבודיה\" \u0003והכא\u0004 \u0005[וכאן]\u0006 \u0003ב\u0004דברים שאמר \u0003שמואל קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 ש\u0003אמר שמואל:\u0004"],["\u0003המוכר שטר חוב לחבירו, וחזר\u0004 המוכר \u0003ומחלו\u0004 ללווה — הרי זה \u0003מחול,\u0004 שכן ההתחייבות של הלווה היתה למלווה בלבד, ובעצם אינה ניתנת להעברה. \u0003ואפילו יורש\u0004 של המלווה \u0003מוחל.\u0004 ונאמר \u0003דמר אית ליה\u0004 \u0005[שחכם זה,\u0006 חכמים, \u0005יש לו,\u0006 הריהו מקבל\u0005]\u0006 את דברי \u0003שמואל\u0004 וכיון שיכול המקדש למחול את החוב, אין האשה סומכת ומקנה את עצמה כשמקבלת שטר חוב בתורת קידושין. \u0003ומר לית ליה\u0004 \u0005[וחכם זה,\u0006 ר' מאיר, \u0005אין לו]\u0006 אינו מקבל את דברי \u0003שמואל\u0004 ומשום כך סומכת האשה דעתה ומתקדשת בשטר החוב.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אית להו\u0004 \u0005[יש להם,\u0006 מקבלים\u0005]\u0006 את דברי \u0003שמואל והכא\u0004 \u0005[וכאן]\u0006 \u0003באשה\u0004 המתקדשת \u0003קמיפלגי\u0004 \u0005[חלוקים הם];\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003אשה סמכה\u0004 \u0005[סומכת]\u0006 \u0003דעתה\u0004 על השטר שקיבלה, כי \u0003מימר אמרה\u0004 \u0005[אומרת\u0006 היא בליבה\u0005]:\u0006 \u0003לא שביק ליה לדידי ומחל ליה לאחריני\u0004 \u0005[אינו\u0006 מסתבר ש\u0005מניח לו לשלי ומוחל אותו לאחרים],\u0006 \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבר]:\u0006 \u0003אשה נמי\u0004 \u0005[גם כן]\u0006 \u0003לא סמכה דעתה,\u0004 שחוששת שמא ימחל את החוב.","והמקדש אשה \u0003במלוה על פה במאי פליגי\u0004 \u0005[במה חלוקים\u0006 הם\u0005]\u0006 — \u0003ב\u0004דברי \u0003רב הונא אמר רב.\u0004 ש\u0003אמר רב הונא אמר רב:\u0004 אומר אדם לחבירו \u0003\"מנה לי בידך\u0004 שאתה חייב לי — \u0003תנהו לפלוני\",\u0004 אם היה זה \u0003במעמד שלשתן,\u0004 שהיו שם יחד המפקיד ומי שהופקד המנה בידיו ופלוני השלישי — \u0003קנה\u0004 האיש השלישי.","\u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003כי קאמר\u0004 \u0005[כאשר אמר]\u0006 \u0003רב הני מילי\u0004 \u0005[דברים אלה]\u0006 שאפשר להקנות במעמד שלושתם, אמרם דווקא \u0003בפקדון\u0004 משום שהחפץ נמצא בעינו, \u0003אבל\u0004 ביחס ל\u0003מלוה\u0004 שניתן להוצאה — \u0003לא\u0004 אמר כן, ולדעתו אינו יכול להעביר בדרך זו דבר שאינו ממשי אלא הוא התחייבות בלבד. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003לא שנא\u0004 \u0005[אינו שונה]\u0006 \u0003מלוה ולא שנא\u0004 \u0005[ואינו שונה]\u0006 \u0003פקדון\u0004 שהאיש השלישי קונה בדרך זו. לפיכך גם האשה מתקדשת כשנתן לה במעמד שלשתם.","ושוב מציעים: \u0003נימא כתנאי\u0004 \u0005[\u0006האם \u0005נאמר\u0006 שדברי רב הם \u0005מחלוקת תנאים]\u0006 בענין מקדש במלווה, ששנינו: אם אמר לאשה \u0003\"התקדשי לי בשטר\"\u0004 — \u0003ר' מאיר אומר: אינה מקודשת, ור' אלעזר אומר: מקודשת, וחכמים אומרים: שמין את הנייר, אם יש בו,\u0004 בנייר עצמו, \u0003שוה פרוטה\u0004 — הריהי \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 — \u0003אינה מקודשת.\u0004","ונברר: \u0003האי שטר היכי דמי\u0004 \u0005[שטר זה כיצד היה בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 שהיה \u0003זה\u0004 \u0003שטר חוב\u0004 של אחרים שחייבים לו — \u0003קשיא\u0004 \u0005[קשים]\u0006 אם כן דברי \u0003ר' מאיר\u0004 על דברי \u0003ר' מאיר\u0004 עצמו, שהרי בברייתא קודמת נאמר שהוא סבור שהאשה מתקדשת על ידי שטר חוב. \u0003אלא\u0004 ודאי מדובר \u0003בשטר חוב דידה\u0004 \u0005[שלה]\u0006 שהיא חייבת לו, \u0003ו\u0004אם כן נמצא כי \u0003במקדש במלוה קא מיפלגי\u0004 \u0005[הם חלוקים]!\u0006","\u0003אמר רב נחמן בר יצחק,\u0004 אפשר לדחות ולומר כי \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים]\u0006 \u0003כגון שקדשה\u0004 לא בשטר חוב אלא \u0003בשטר\u0004 קידושין, אלא \u0003ש\u0004שטר זה \u0003אין עליו עדים.\u0004","\u0003ור' מאיר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר\u0004 לענין גט: \u0003עדי חתימה כרתי\u0004 \u0005[\u0006הם \u0005כורתים,\u0006 גומרים\u0005]\u0006 את קניינו של הגט, והוא הדין לשטר קידושין. וכיון שלא היו עדים חתומים על השטר אין בו ממש. \u0003ור' אלעזר לטעמיה\u0004 \u0005[לטעמו,\u0006 לשיטתו\u0005]\u0006 ש\u0003אמר: עדי מסירה כרתי\u0004 \u0005[כורתים,\u0006 גומרים\u0005]\u0006 את הדבר ואם מסר את השטר בעדים — הריהי מקודשת. \u0003ורבנן מספקא להו\u0004 \u0005[מסופק להם]\u0006 \u0003אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' מאיר, אי\u0004 \u0005[אם]\u0006 \u0003כ\u0004דעת \u0003ר' אלעזר, הלכך\u0004 \u0005[על כן]\u0006 אומרים הם שאין לראות בכך קידושין בשטר אלא דין קידושי כסף ושווה כסף, ולכן \u0003שמין את הנייר,\u0004 ו\u0003אם\u0004 נמצא \u0003ש\u0004\u0003יש בו שוה פרוטה\u0004 — הריהי \u0003מקודשת, ואם לאו\u0004 \u0005[לא]\u0006 \u0003אינה מקודשת.\u0004","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר, שמדובר פה בשטר קידושין, \u0003כגון שכתבו שלא לשמה. וב\u0004דברי \u0003ריש לקיש קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003ריש לקיש\u0004 שאלה זו: \u0003שטר אירוסין\u0004 (קידושין) \u0003שכתבו\u0004 הסופר \u0003שלא לשמה\u0004 של הבעל והאשה, \u0003מהו?\u0004 האם אפשר לקדש בו? וצדדי השאלה: האם \u0003הויה\u0004 (קידושין, היות אשה לאיש) \u0003ליציאה\u0004 (גירושין) \u0003מקשינן\u0004 \u0005[מקישים,\u0006 משווים, \u0005אנו]\u0006 ואומרים: \u0003מה יציאה בעינן\u0004 \u0005[צריכים אנו]\u0006 שייכתב הגט \u0003לשמה, אף הויה,\u0004 שטר של קידושין, \u0003נמי בעינן\u0004 \u0005[גם כן צריכים אנו]\u0006 שיהיה כתוב \u0003לשמה. או דלמא\u0004 \u0005[שמא]:\u0006 \u0003הויות\u0004 דרכי הקידושין השונות \u0003להדדי מקשינן\u0004 \u0005[זו לזו אנו משווים],\u0006 \u0003מה הויה\u0004 שעל ידי \u0003כסף לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהיה הכסף מוטבע \u0003לשמה,\u0004 אלא כל כסף מועיל, \u0003אף הויה\u0004 שעל ידי \u0003שטר לא בעינן\u0004 \u0005[אין אנו צריכים]\u0006 שיהיה \u0003לשמה.\u0004","\u0003בתר דבעיא הדר פשטה\u0004 \u0005[אחר ששאל אותה,\u0006 את השאלה הזו, \u0005חזר ופתרה]\u0006 נאמר: \u0003\"ויצאה\u0004 מביתו והלכה \u0003והיתה\u0004 לאיש אחר\" (דברים כד, ב) ובפסוק זה \u0003מקיש\u0004 \u0005[משווה]\u0006 הכתוב \u0003הויה ליציאה\u0004 לכל דבר, ואם כן כמו בגט גם שטר קידושין שנכתב שלא לשמה — פסול. ונאמר כי \u0003מר אית ליה\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005יש לו,\u0006 הריהו מקבל\u0005]\u0006 את דברי \u0003ריש לקיש\u0004 ואם לא כתב לשמה אינה מקודשת, \u0003ומר לית ליה\u0004 \u0005[וחכם זה,\u0006 ר' אלעזר, \u0005אין לו,\u0006 אינו מקבל\u0005]\u0006 את דברי \u0003ריש לקיש,\u0004 וחכמים מסופקים בדבר ולכן רואים הם בכך קידושי כסף.","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003דכולי עלמא אית להו\u0004 \u0005[שהכל ישל להם,\u0006 הריהם מקבלים\u0005]\u0006 את דברי \u0003ריש לקיש,\u0004 \u0003והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 \u0003שכתבו\u0004 את השטר \u0003לשמה\u0004 של המקדש והמתקדשת \u0003ו\u0004אולם \u0003שלא מדעתה,\u0004 שלא ידעה שעבורה כותב שטר זה. \u0003ובפלוגתא\u0004 \u0005[ובמחלוקת]\u0006 של \u0003רבא ורבינא, ורב פפא ורב שרביא קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 \u0003דאיתמר\u0004 \u0005[שנאמר]\u0006 שנחלקו אמוראים בבעיה זו: שטר קידושין ש\u0003כתבו לשמה ושלא מדעתה, רבא ורבינא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003מקודשת\u0004 בו, \u0003רב פפא ורב שרביא אמרי\u0004 \u0005[אומרים]:\u0006 \u0003אינה מקודשת.\u0004","ושוב מנסים להציע שהמקדש במלוה \u0003נימא כהני תנאי\u0004 \u0005[נאמר\u0006 שהיא מחלוקת \u0005כתנאים אלה]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 נתנה אשה זהב לצורף ואמרה לו \u0003\"עשה לי שירים\u0004 (צמידים) \u0003נזמים וטבעות, ואקדש אני לך\u0004 בשכר עבודתך \u0003\",\u0004 \u0003כיון שעשאן מקודשת,\u0004 אלו \u0003דברי ר' מאיר, וחכמים אומרים: אינה מקודשת עד שיגיע ממון לידה.\u0004","ושואלים: \u0003האי ממון היכי דמי\u0004 \u0005[ממון זה\u0006 שהוזכר \u0005כיצד הוא בדיוק]?\u0006 \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003אותו ממון,\u0004 כלומר, שייתן לה את הנזמים הללו, האם \u0003מכלל\u0004 הדברים תאמר שה\u0003תנא קמא\u0004 \u0005[הראשון],\u0006 ר' מאיר \u0003סבר\u0004 \u0005[סבור]\u0006 ש\u0003אפילו\u0004 אם מחזיר לה כשסיים מלאכתו את \u0003אותו ממון נמי\u0004 \u0005[גם כן\u0006 \u0003לא\u0004 תתקדש! \u0003אלא במאי\u0004 \u0005[אלא במה]?\u0006 הרי רק \u0003בו מקדשא\u0004 \u0005[\u0006היא \u0005מתקדשת],\u0006 שהרי לא נתן לה דבר מלבד התכשיטים! \u0003אלא לאו\u0004 \u0005[\u0006האם \u0005לא]\u0006 הכוונה היא שמתקדשת \u0003בממון אחר,\u0004 בשכר העבודה שהיא חייבת לו. \u0003ושמע מינה\u0004 \u0005[ולמד מכאן]\u0006 כי \u0003במקדש במלוה קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005],\u0006 כיון ששכר העבודה שהיא חייבת לו עבור עשיית הנזמים הוא כמלוה.","ומוסיפים לבאר: וצריכים לומר \u0003וסברי\u0004 \u0005[וסבורים\u0006 הם\u0005]\u0006 \u0003דכולי עלמא\u0004 \u0005[שלדעת הכל]\u0006 \u0003ישנה לשכירות מתחלה ועד סוף.\u0004 כלומר, שהתחייבות לשלם עבור השכירות מתחילה מרגע שמתחיל הפועל במלאכה ובכל שעה שעובד נוסף סכום מסויים בחוב זה. \u0003ו\u0004לפיכך \u0003הוה\u0004 \u0005[הרי\u0006 זה\u0005]\u0006 \u0003מלוה,\u0004 שהרי כשנותן לה את החפץ העשוי כבר התחייבה לו תשלום עבור המלאכה שעשה מתחילת עבודתו. ואם כן \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא בזה\u0006 הם \u0005חלוקים]\u0006 \u0003דמר סבר\u0004 \u0005[שחכם זה,\u0006 ר' מאיר, \u0005סבור]:\u0006 \u0003המקדש במלוה מקודשת, ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003המקדש במלוה אינה מקודשת?\u0004","ודוחים: \u0003לא, דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 אפשר לומר שה\u0003מקדש במלוה אינה מקודשת, והכא\u0004 \u0005[וכאן]\u0006 באמת באותה סברה עצמה — \u0003ב\u0004שאלה האם \u0003ישנה לשכירות מתחלה ועד סוף קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005];\u0006 \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 חכמים, \u0005סבור]:\u0006"],["\u0003אינה לשכירות אלא בסוף,\u0004 כאשר מסיים את מלאכתו ומחזיר לה החפץ, וכיון שאז הוא מוחל על שכרו לשם קידושין נמצא שלא היתה כאן הלוואה כלל. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003ישנה לשכירות מתחלה ועד סוף\u0004 ובסוף השכירות הוא בגדר הלוואה הגדלה והולכת כל זמן השכירות.","\u0003ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]\u0006 באופן אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003ישנה לשכירות מתחלה ועד סוף, ו\u0004תאמר גם כן שה\u0003מקדש במלוה\u0004 — \u0003אינה מקודשת, והכא\u0004 \u0005[וכאן]\u0006 אין אנו עוסקים בשכיר, אלא בקבלן הזכאי לתשלום רק כאשר השלים את מה שקיבל עליו ו\u0003ב\u0004שאלה האם \u0003אומן קונה בשבח כלי קמיפלגי\u0004 \u0005[חלוקים\u0006 הם\u0005].\u0006 כלומר, האם יש לאומן זכות קניינית בחפץ בכך שהעלה את ערכו; \u0003מר סבר\u0004 \u0005[חכם זה,\u0006 ר' מאיר, \u0005סבור]\u0006 \u0003אומן קונה בשבח כלי,\u0004 וכיון שנחשב כאילו יש לו חלק בתכשיטים, הריהו יכול לקדש בהם, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 חכמים, \u0005סבור]:\u0006 \u0003אין אומן קונה בשבח כלי.\u0004","\u0003ואי בעית אימא\u0004 \u0005[ואם תרצה אמור\u0006\u0005]\u0006 באופן אחר: \u0003דכולי עלמא\u0004 \u0005[לדעת הכל]\u0006 \u0003אין אומן קונה בשבח כלי, ו\u0004תאמר גם כן כי \u0003ישנה לשכירות מתחלה ועד סוף, ו\u0004גם שה\u0003מקדש במלוה אינה מקודשת, והכא במאי עסקינן\u0004 \u0005[וכאן במה אנו עוסקים]\u0006 — \u0003כגון שהוסיף לה\u0004 על התכשיט \u0003נופך\u0004 (אבן חן קטנה) \u0003משלו. דמר סבר\u0004 \u0005[שחכם זה סבור]\u0006 שאם אדם מקדש ב\u0003מלוה ו\u0004ב\u0003פרוטה דעתיה\u0004 \u0005[דעתו]\u0006 על ה\u0003פרוטה\u0004 \u0003ומר סבר\u0004 \u0005[וחכם\u0006 \u0003זה סבור]:\u0004 \u0003דעתיה\u0004 \u0005[דעתו]\u0006 על ה\u0003מלוה\u0004 ואף כאן השאלה היא, האם דעתה להתקדש בשכר העבודה (שהוא המלוה), או בנופך משלו.","\u0003ו\u0004לפי הסבר זה מחלוקת זו היא \u0003בפלוגתא דהני תנאי\u0004 \u0005[במחלוקתם של תנאים אלה]\u0006 \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 האומר לאשה \u0003\"\u0004הרי את מקודשת \u0003בשכר שעשיתי עמך\u0004 (עבדתי עבורך) \u0003\"\u0004— \u0003אינה מקודשת\u0004 משום שהוא מלוה, שהרי היא חייבת לו כסף זה. \u0003\"בשכר שאעשה עמך\"\u0004 — הרי זו \u0003מקודשת,\u0004 שהרי בגמר המלאכה כאשר צריך לקבל את שכרו הוא נותן זאת ככסף קידושין. \u0003ר' נתן אומר: \"בשכר שאעשה עמך\"\u0004 — \u0003אינה מקודשת,\u0004 שלדעתו היא מחוייבת לשלם את שכרו כבר מתחילת העבודה ובסוף העבודה הרי זה מלוה, \u0003וכל שכן \"בשכר שעשיתי עמך\".\u0004","\u0003ר' יהודה הנשיא אומר: באמת אמרו,\u0004 כלומר, הלכה היא: \u0003בין\u0004 שאמר לה בלשון \u0003\"בשכר שעשיתי\", בין\u0004 שאמר לה \u0003\"בשכר שאעשה עמך\"\u0004 — \u0003אינה מקודשת. ואם הוסיף לה נופך משלו\u0004 — הריהי \u0003מקודשת.\u0004","ואם כן \u0003בין תנא קמא לר' נתן איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 מחלוקת\u0005]\u0006 בעניין \u0003שכירות,\u0004 האם חיוב תשלום השכירות הוא מתחילה או רק בסוף, \u0003בין ר' נתן לר' יהודה הנשיא איכא בינייהו\u0004 \u0005[יש ביניהם\u0006 מחלוקת\u0005]\u0006 בענין \u0003מלוה ופרוטה. מר סבר\u0004 \u0005[חכם זה,\u0006 ר' נתן, \u0005סבור]:\u0006 \u0003מלוה ופרוטה דעתיה\u0004 \u0005[דעתו]\u0006 על ה\u0003מלוה\u0004 והנופך שלו אינו נחשב, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבי, \u0005סבור]:\u0006 \u0003דעתיה\u0004 \u0005[דעתו]\u0006 על ה\u0003פרוטה\u0004 ומקודשת בנופך שהוסיף.","אמר לאשה \u0003\"התקדשי לי בכוס זה של יין\" ונמצא\u0004 שהיה \u0003של דבש,\u0004 או שאמר \u0003\"\u0004התקדשי לי בכוס \u0003של דבש\" ונמצא\u0004 שהיה \u0003של יין,\u0004 אוש אמר לה \u0003\"\u0004התקדשי לי \u0003בדינר זה של כסף\" ונמצא\u0004 שהיה דינר \u0003של זהב,\u0004 או \u0003\"\u0004בדינר \u0003של זהב\" ונמצא של כסף,\u0004 או אמר לה \u0003\"על מנת שאני עשיר\" ונמצא\u0004 שבשבעת הקידושין היה \u0003עני,\u0004 או \u0003\"\u0004על מנת שאני \u0003עני\" ונמצא\u0004 שבאותה שעה היה \u0003עשיר\u0004 — בכל אלה \u0003אינה מקודשת,\u0004 שהרי התקדשה רק על מנת שיתקיימו התנאים שקבע. \u0003ר' שמעון אומר: אם הטעה\u0004 אותה \u0003לשבח,\u0004 שאם מה שהוא נותן לה (או שמצבו) טוב יותר ממה שהתנה עימה בקידושין הרי היא \u0003מקודשת.\u0004","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 האומר לאשה \u0003\"התקדשי לי בכוס זה\"\u0004 ולא פרט יותר, \u0003תני חדא\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחת]:\u0006 שמעריכים את דמי הקידושין \u0003בו,\u0004 בכוס עצמה, \u0003ו\u0004גם \u0003במה שבתוכו, ותניא אידך\u0004 \u0005[ושנויה\u0006 ברייתא \u0005אחרת]:\u0006 שכוונתו לקדש \u0003בו ולא במה שבתוכו. ותניא אידך\u0004 \u0005[ושנויה\u0006 עוד ברייתא \u0005אחרת]\u0006 שמעריכים \u0003במה שבתוכו ולא בו.\u0004 ומעירים: \u0003ולא קשיא\u0004 \u0005[ואין\u0006 זה \u0005קשה]\u0006 מברייתא אחת על השניה: \u0003הא\u0004 \u0005[זה]\u0006 — \u0003במיא\u0004 \u0005[במים],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003בחמרא\u0004 \u0005[ביין],\u0006 \u0003הא\u0004 \u0005[זה]\u0006 — \u0003בציהרא\u0004 \u0005[בשמן],\u0006 שאם מקדשה בכוס מים הריהו מתכוון שתתקדש בכוס ולא במים, בכוס יין — מתכוון לקדשה ביין שתשתה ולא בכוס, ובשמן — מתכוון לשמן ולכוס יחד לפי שמשתמשים בשמן במשך זמן ממושך וצריך לכוס כדי להחזיק את השמן.","שנינו במשנה שר' שמעון אומר ש\u0003אם הטעה לשבח הרי זו מקודשת.\u0004 ושואלים: \u0003ולית ליה\u0004 \u0005[ו\u0006האם \u0005אין לו]\u0006 \u0003לר' שמעון,\u0004 האם אינו סבור כדברי המשנה שאם מכר אדם לחבירו \u0003יין ונמצא חומץ,\u0004 או מכר \u0003חומץ ונמצא יין\u0004 — \u0003שניהם,\u0004 גם הקונה וגם המוכר, \u0003יכולין לחזור בהם,\u0004 ואינו נידון כאונאה במסחר, אף שהיין שווה יותר מהחומץ ואין אומרים שרק זה שהוטעה רשאי לחזור בו. \u0003אלמא, איכא דניחא ליה בחלא ואיכא דניחא ליה בחמרא\u0004 \u0005[מכאן,\u0006 ש\u0005יש\u0006 מי \u0005שנוח לו בחומץ ויש שנוח לו ביין],\u0006 ואין אומרים שאם קיבל יין היה זה שינוי לשבח. ואם כן, \u0003הכא נמי\u0004 \u0005[כאן גם כן]:\u0006 \u0003איכא ניחא ליה בכספא\u0004 \u0005[יש\u0006 ש\u0005נוח לו בכסף]\u0006 \u0003ולא ניחא ליה בדהבא\u0004 \u0005[נוח לו בזהב]!\u0006 ומדוע \u0003לר'\u0004 שמעון מקודשת אם נתן לה זהב במקום כסף?","\u0003אמר רב שימי בר אשי: אשכחתיה\u0004 \u0005[מצאתי]\u0006 \u0003לאביי דיתיב וקמסבר ליה לבריה\u0004 \u0005[שיושב ומסביר לו לבנו]\u0006 משנה זו: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה,\u0006 באיזה אופן \u0005אנו עוסקים]\u0006 — \u0003כגון שאמר לשלוחו \"הלויני דינר של כסף, ולך וקדש לי\u0004 בו \u0003אשה פלונית\" והלך והלוה\u0004 וקידש ב\u0003של זהב. מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא \u0005סבור]\u0006 שיש במה שפירש שיהיו הקידושין בכסף \u0003קפידא\u0004 \u0005[\u0006\u0005הקפדה]\u0006 שיעשה השליח דווקא בדרך זו, וכיון שלא עשה השליח את שליחותו — אינה מקודשת. \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון, \u0005סבור]:\u0006 \u0003מראה מקום הוא לו.\u0004 שלא אמר \"של כסף\" אלא כהנחיה כללית אבל גם לשל זהב הוא מסכים.","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 שמדובר פה בשליח מדוע הוא אומר \u0003\"התקדשי לי\"? \"התקדשי לו\" מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לומר\u0005]!\u0006 ועוד: \u0003הטעה\u0004 אותה \u0003לשבח? הטעהו לשבח מיבעי ליה\u0004 \u0005[צריך היה לו\u0006 לתנא לומר\u0005]!\u0006 שהרי לא את האשה הטעה השליח אלא את המשלח. וכן קשה הלשון \u0003\"נמצא\u0004 של זהב \u0003\"\u0004שהרי \u0003מעיקרא נמי\u0004 \u0005[מתחילה,\u0006 כשנתן השליח לאשה \u0005גם כן]\u0006 של \u0003זהב הוה\u0004 \u0005[היה]!\u0006 ואם כן אין לשון המשנה מתיישבת היטב באופן זה.","\u0003אלא אמר רבא: אני וארי\u0004 (הגדול) \u0003שבחבורה תרגימנא\u0004 \u0005[תרגמנו,\u0006 הסברנו\u0005]\u0006 זאת. ומעירים: \u0003ומנו\u0004 \u0005[ומיהו]\u0006 אותו \"ארי שבחבורה\" — \u0003ר' חייא בר אבין: הכא במאי עסקינן\u0004 \u0005[כאן במה,\u0006 באיזה אופן \u0005אנו עוסקים]\u0006 — \u0003כגון שאמרה היא לשלוחה \"צא וקבל לי קדושי מפלוני, שאמר לי \"התקדשי לי בדינר של כסף\", והלך\u0004 המקדש \u0003ונתן לו\u0004 לשליח \u0003דינר של זהב; מר סבר\u0004 \u0005[חכם זה,\u0006 תנא קמא, \u0005סבור]\u0006 שיש בכך \u0003קפידא\u0004 \u0005[הקפדה]\u0006 והתכוונה דווקא לכסף ולא לזהב, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 ר' שמעון, \u0005סבור]:\u0006 \u0003מראה מקום היא לו\u0004 ואינה מדקדקת בכך, אלא מה בכוונתה שמה שיתן יקח השליח. \u0003ומאי\u0004 \u0005[ומה\u0006 פירוש הלשון\u0005]\u0006 \u0003\"נמצא\",\u0004 שהרי לכאורה ידוע היה שהוא של זהב — מדובר \u0003דקא צייר בבליתא\u0004 \u0005[שהיה צרור בסמרטוט]\u0006 ולא ידע השליח שהוא מקבל דינר אחר מכפי שאמרה לו.","\u0003אמר אביי: ר' שמעון ורבן שמעון בן גמליאל ור' אלעזר כולהו סבירא להו\u0004 \u0005[כולם סבורים הם]\u0006 שבכל הנחיה כזו בשליחות \u0003מראה מקום הוא לו,\u0004 ואם עושה השליח שינוי בדבר שאינו משמעותי — אין אומרים שיש בכך הקפדה ולפיכך אין השינוי מבטל את השליחות. ומפרטים: \u0003ר' שמעון\u0004 — \u0003הא דאמרן\u0004 \u0005[זו שאמרנו]\u0006 כאן, \u0003רבן שמעון בן גמליאל\u0004 — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006"],["\u0003גט פשוט,\u0004 כלומר, סתם גט, \u0003עדיו\u0004 חתומים \u0003מתוכו,\u0004 בתוך השטר, מתחת לכתוב, כנהוג ברוב השטרות. גט \u0003מקושר,\u0004 שתופרים אותו, \u0003עדיו\u0004 חותמים \u0003מאחוריו,\u0004 מאחורנית על התפר. גט \u0003פשוט שכתבו עדיו מאחוריו,\u0004 או \u0003מקושר שכתבו עדיו מתוכו\u0004 — \u0003שניהם פסולים,\u0004 כיון שלא נעשו כתקנת חכמים. \u0003ר' חנינא בן גמליאל אומר: מקושר שכתבו עדיו מתוכו\u0004 — \u0003כשר, ש\u0004הרי \u0003יכול לעשותו פשוט,\u0004 שיפתח את התפרים ויימצא זה גט פשוט. \u0003רבן שמעון בן גמליאל אומר: הכל כמנהג המדינה,\u0004 שאם נהוג גט פשוט ועשה מקושר או להיפך — הגט פסול.","\u0003והוינן בה\u0004 \u0005[והיינו עוסקים,\u0006 מתקשים, \u0005ב\u0006משנה \u0005זו]:\u0006 \u0003ו\u0004כי ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003לית ליה\u0004 \u0005[אין לו,\u0006 אינו סבור\u0005]\u0006 שהולכים כ\u0003מנהג המדינה? ואמר רב אשי\u0004 הסבר לשיטותיהם של רבן שמעון בן גמליאל והתנא הראשון: \u0003באתרא דנהיגי\u0004 \u0005[במקום שנוהגים]\u0006 לכתוב \u0003ב\u0004גט \u0003פשוט ועבד ליה\u0004 \u0005[ועשה\u0006 \u0003לו,\u0004 אותו\u0005]\u0006 \u0003מקושר, אי נמי\u0004 \u0005[או גם כן]:\u0006 \u0003באתרא דנהיגי\u0004 \u0005[במקום שנוהגים]\u0006 לכתוב \u0003במקושר ועבד ליה\u0004 \u0005[ועשה\u0006 \u0003לו,\u0004 אותו\u0005]\u0006 \u0003פשוט\u0004 — \u0003כולי עלמא לא פליגי\u0004 \u0005[הכל אינם\u0006 \u0003חלוקים]\u0004 ש\u0003ודאי\u0004 במינוי השליחות יש \u0003קפידא\u0004 \u0005[הקפדה]\u0006 שיעשה השליח כמנהג המדינה, ואם שינה — נפסל הגט.","\u0003כי פליגי\u0004 \u0005[כאשר חלוקים\u0006 הם\u0005],\u0006 הרי זה \u0003באתרא דנהיגי\u0004 \u0005[במקום שנוהגים]\u0006 \u0003בין בפשוט בין במקושר, ואמר ליה\u0004 \u0005[לו]\u0006 לסופר: \u0003\"עביד\u0004 \u0005[עשה]\u0006 \u0003לי\u0004 גט \u0003פשוט\", ואזל ועבד ליה\u0004 \u0005[והלך ועשה לו]\u0006 \u0003מקושר. מר סבר\u0004 \u0005[חכם זה,\u0006 התנא הראשון ר' חנינא בן גמליאל, \u0005סבור]:\u0006 \u0003קפידא\u0004 \u0005[הקפדה]\u0006 היא, \u0003ומר סבר\u0004 \u0005[וחכם זה,\u0006 רבן שמעון בן גמליאל, \u0005סבור]:\u0006 \u0003מראה מקום הוא לו,\u0004 שלא הקפיד שיהיה דווקא כזה. והוכחנו איפוא שרבן שמעון בן גמליאל מקבל את ההנחה של \"מראה מקום\".","וגם \u0003ר' אלעזר\u0004 מקבל סברה זו — \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 \u0003האשה שאמרה\u0004 לשלוחה \u0003\"התקבל לי גיטי\u0004 מבעלי \u0003ממקום פלוני\", וקבל לה גיטה ממקום אחר\u0004 — \u0003פסול. ור' אלעזר מכשיר. אלמא קסבר\u0004 \u0005[מכאן\u0006 שהוא \u0005סבור]:\u0006 \u0003מראה מקום היא לו,\u0004 שרק אמרה לו היכן לקחת את הגט, אבל לא הקפידה שיקבלנו דווקא באותו מקום.","\u0003אמר עולא:\u0004 ה\u0003מחלוקת\u0004 במשנתנו בין התנא הראשון ור' שמעון היא דווקא כשהטעה אותה \u0003בשבח ממון,\u0004 כלומר, שהמקדש נתן לאשה דבר שהיה מבחינה ממונית משובח יותר ממה שדובר לפני כן, \u0003אבל\u0004 אם הטעה אותה \u0003בשבח יוחסין,\u0004 שחשבה שיש לו ייחוס פחות, ונמצא ייחוסו גדול יותר — \u0003דברי הכל אינה מקודשת. מאי טעמא\u0004 \u0005[מה טעם]\u0006 הדבר — שיש לומר שהאשה אומרת \u0003\"מסאנא דרב מכרעאי לא בעינא\"\u0004 \u0005[\"נעל הגדולה מרגלי אינני רוצה\"],\u0006 כלומר, שאינה רוצה להנשא לאדם שמעמדו הרבה יותר גבוה ממעמדה. \u0003תניא נמי הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 במפורש: \u0003מודה ר' שמעון,\u0004 ש\u0003אם הטעה לשבח יוחסים\u0004 ש\u0003אינה מקודשת.\u0004","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 כהבנה זו. \u0003דקתני\u0004 \u0005[ששנה]\u0006 במשנה הבאה: המקדש אשה \u0003\"על מנת שאני כהן\" ונמצא\u0004 שהוא \u0003לוי,\u0004 או \u0003\"\u0004על מנת שאני \u0003לוי\" ונמצא\u0004 שהוא \u0003כהן,\u0004 או שאמר שהוא \u0003נתין\u0004 (מבני הגבעונים) שאסורים לבוא בקהל מדברי סופרים \u0003ונמצא\u0004 שהוא \u0003ממזר\u0004 האסור לבוא בקהל מן התורה, או שאמר לה \u0003\"\u0004על מנת שאני \u0003ממזר\" ונמצא\u0004 שהוא \u0003נתין\u0004 — אינה מקודשת. \u0003ולא פליג\u0004 \u0005[חלק]\u0006 \u0003ר' שמעון\u0004 על כך. משמע שבמטעה לשבח יוחסין אף הוא מודה.","\u0003מתקיף לה\u0004 \u0005[מקשה על כך]\u0006 \u0003מר בר רב אשי: אלא\u0004 זו \u0003דקתני\u0004 \u0005[ששנה]\u0006 באותה משנה: האומר לאשה שמקדש אותה \u0003\"על מנת שיש לי בת או שפחה מגודלת\" ואין לו,\u0004 או \u0003על מנת שאין לו ויש לו,\u0004 שדבר זה \u0003שבח ממון הוא,\u0004 שהרי ההבדל בין מי שיש לו שפחה או שאין לו משמעותי רק מבחינה ממונית, חמרית, לגבי מידת הטירחה שתצטרך האשה לטרוח אחר כך בבית. ואף שם \u0003הכי נמי דלא פליג\u0004 \u0005[כך גם כן\u0006 תאמר \u0005שאינו חולק]\u0006 מפני שלא מוזכר שם שר' שמעון חולק?!","\u0003אלא\u0004 יש לומר ש\u0003פליג ברישא\u0004 \u0005[\u0006ש\u0005חולק ב\u0006משנה ה\u0005ראשונה,\u0006 משנתינו\u0005]\u0006 לענין שבח ממון \u0003והוא הדין לסיפא\u0004 \u0005[לסוף,\u0006 במשנה הבאה\u0005],\u0006 שגם בענין זה הוא חולק, אלא שלא היה צריך לומר זאת פעם שניה. ואם כן \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 לענין שבח יוחסין אין להסיק מסקנה לעמדת ר' שמעון בשבח יוחסין מכך שלא חלק במפורש כי אפשר לומר שהוא \u0003פליג ברישא\u0004 \u0005[חלק בראש,\u0006 במשנה ראשונה\u0005]\u0006 \u0003והוא הדין לסיפא\u0004 \u0005[לסוף].\u0006","ודוחים: \u0003הכי השתא\u0004 \u0005[איך אתה משווה]?\u0006 \u0003התם\u0004 \u0005[שם]\u0006 אפשר לומר: \u0003אידי ואידי\u0004 \u0005[זה וזה]\u0006 הם טעות של \u0003שבח ממון\u0004 ואפשר לומר ש\u0003פליג ברישא\u0004 \u0005[חולק בראש]\u0006 \u0003והוא הדין בסיפא\u0004 \u0005[בסוף]\u0006 ולכן לא פירש את מחלוקתו, \u0003הכא\u0004 \u0005[כאן]\u0006 ש\u0003שבח יוחסים הוא\u0004 והוא בודאי נושא שונה, \u0003אם איתא דפליג\u0004 \u0005[אם יש\u0006 מקום לומר \u0005ש\u0006ר' שמעון \u0005חולק],\u0006 אם כן \u0003נתני\u0004 \u0005[שישנה]\u0006 זאת במפורש! ולכן העובדה שלא נזכרת מחלוקת בשבח יוחסין — ראיה היא שאינו חולק.","\u0003איבעית אימא\u0004 \u0005[אם תרצה אמור]\u0006 באופן אחר: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 בבת מגודלת הוא \u0003שבח יוחסים, מי סברת\u0004 \u0005[האם סבור אתה]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 פירוש בת \u0003מגודלת\u0004 שהיא \u0003גדולה ממש\u0004 בגיל, שהיא יכולה לעזור? לא, \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003מגודלת\u0004 — \u0003גדלת\u0004 (קולעת שערות, ספרית). ומדוע יכולה האשה לראות דבר זה כחסרון — \u0003דאמרה\u0004 \u0005[שאומרת]\u0006 \u0003היא,\u0004 המתקדשת: \u0003לא ניחא\u0004 \u0005[נוח]\u0006 \u0003לי\u0004 בה \u0003דשקלה מילי מינאי ואזלא נדיא קמי שיבבותיי\u0004 \u0005[ש\u0006היא \u0005תיקח,\u0006 תשמע, \u0005דברים ממני ותלך\u0006 ו\u0005תעביר\u0006 אותם \u0005לפני שכנותיי]\u0006 ותספר להן אודות מעשיי.","\u0003תנו רבנן\u0004 \u0005[שנו חכמים]:\u0006 אם אומר אדם לאשה שהוא מקדש אותה \u0003\"על מנת שאני קריינא\"\u0004 (קריין, יודע לקרוא בתורה); \u0003כיון שקרא שלשה פסוקים בבית הכנסת\u0004 — \u0003הרי זו מקודשת. ר' יהודה אומר\u0004 הכוונה היא \u0003עד שיקרא ויתרגם.\u0004 ושואלים: האם הכוונה היא \u0003יתרגם מדעתיה\u0004 \u0005[מדעתו]?!\u0006 \u0003והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 ש\u0003ר' יהודה\u0004 עצמו \u0003אומר: המתרגם פסוק כצורתו,\u0004 כלומר, מלה במלה — \u0003הרי זה בדאי,\u0004 שאין זו כוונת הכתוב. \u0003ו\u0004להיפך, \u0003המוסיף עליו\u0004 תרגום משלו — \u0003הרי זה מחרף ומגדף. אלא מאי\u0004 \u0005[מה]\u0006 פירוש \u0003תרגום\u0004 — \u0003תרגום דידן\u0004 \u0005[שלנו]\u0006 התרגום המקובל, שהוא יודע גם לקרוא וגם לתרגם.","\u0003והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא באופן ש\u0003אמר לה\u0004 בלשון \u0003\"קריינא\"\u0004 \u0005[\"קריין\"],\u0006 \u0003אבל\u0004 אם \u0003אמר לה\u0004 בלשון \u0003\"קרא אנא\"\u0004 \u0005[אני קרא],\u0006 שמשמעו: בקי במקרא — הכוונה היא \u0003עד דקרי אורייתא נביאי וכתובי בדיוקא\u0004 \u0005[עד ש\u0006הוא יודע \u0005לקרוא\u0006 ב\u0005תורה נביאים וכתובים בדיוק].\u0006","ועוד, אם אמר לאשה \u0003\"\u0004התקדשי לי \u0003על מנת שאני שונה\", חזקיה אמר:\u0004 הכוונה היא שונה \u0003הלכות, ור' יוחנן אמר: תורה.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על דברי ר' יוחנן ממה ששנינו: \u0003איזו היא משנה? ר' מאיר אומר: הלכות, ר' יהודה אומר: מדרש,\u0004 והרי שאין אחד מהם אומר שזו תורה!"],["\u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003תורה\u0004 שאמר ר' יוחנן — הכוונה היא ל\u0003מדרש תורה. והני מילי\u0004 \u0005[ודברים אלה]\u0006 אמורים דווקא כש\u0003אמר לה \"תנינא\"\u0004 \u0005[\"שניתי\"],\u0006 \u0003אבל\u0004 אם \u0003אמר לה \"תנא אנא\"\u0004 \u0005[\"שונה אני\"]\u0006 — \u0003עד דתני\u0004 \u0005[ש\u0006הוא \u0005שונה]\u0006 \u0003הילכתא\u0004 \u0005[הלכה,\u0006 משנה\u0005],\u0006 \u0003ספרא\u0004 (מדרש ההלכה לספר ויקרא), \u0003וסיפרי\u0004 (מדרש ההלכה לספרי במדבר ודברים), \u0003ותוספתא.\u0004","אם אומר \"התקדשי לי \u0003על מנת שאני תלמיד\u0004 חכם\" \u0003אין אומרים\u0004 שיהיה תלמיד חכם \u0003כשמעון בן עזאי וכשמעון בן זומא\u0004 שנקראו תלמידים משום שלא הספיקו לסמוך אותם, אף שהיו מגדולי חכמי ישראל, \u0003אלא, כל ששואלין אותו בכל מקום דבר אחד בתלמודו ואומרו, ואפילו במסכתא דכלה,\u0004 באותה מסכת שלומדים אותה באותה שעה בישיבה. האומר \u0003\"על מנת שאני חכם\"\u0004 — \u0003אין אומרים\u0004 שיהיה \u0003כחכמי יבנה, כר' עקיבא וחביריו, אלא, כל ששואלים אותו דבר חכמה בכל מקום\u0004 בתורה \u0003ואומרה.\u0004","וכן האומר \u0003\"על מנת שאני גבור\" אין אומרים\u0004 עד שיהיה גיבור \u0003כאבנר בן נר וכיואב בן צרויה, אלא כל שחביריו מתיראים ממנו מפני גבורתו. \"על מנת שאני עשיר\"\u0004 — \u0003אין אומרים\u0004 עד שיהא עשיר \u0003כר' אלעזר בן חרסום וכר' אלעזר בן עזריה\u0004 שהיו עשירים מופלגים, \u0003אלא כל שבני עירו מכבדים אותו מפני עושרו.\u0004","אם \u0003אמר \"על מנת שאני צדיק\"\u0004 — \u0003אפילו\u0004 היה \u0003רשע גמור\u0004 — הריהי \u0003מקודשת, שמא הרהר\u0004 בינתיים \u0003תשובה בדעתו\u0004 ומשום כך עכשיו צדיק הוא. וכן אם אמר \u0003\"על מנת שאני רשע\"\u0004 — \u0003אפילו\u0004 היה \u0003צדיק גמור מקודשת, שמא הרהר דבר עבודה זרה בדעתו,\u0004 והרהור עבודה זרה נחשב לעבירה חמורה שהעושה אותה נחשב בשל כך לרשע.","אגב דיון זה בהגדרתן של תכונות שונות מביאים מאמר בנושא קרוב. \u0003עשרה קבים\u0004 (מידות) \u0003חכמה ירדו לעולם, תשעה\u0004 מתוכם \u0003נטלה ארץ ישראל ואחד,\u0004 העשירי, נטל \u0003כל העולם כולו. עשרה קבים\u0004 של \u0003יופי ירדו לעולם, תשעה\u0004 מהם \u0003נטלה ירושלים, ואחד כל העולם כולו. עשרה קבים עשירות ירדו לעולם, תשעה נטלו רומי, ואחד כל העולם כולו. עשרה קבים עניות ירדו לעולם, תשעה נטלה בבל ואחד כל העולם כולו. עשרה קבים גסות\u0004 הרוח, גאוה, \u0003ירדו לעולם, תשעה נטלה עילם, ואחד כל העולם כולו.\u0004","ושואלים: \u0003וגסות לבבל לא נחית\u0004 \u0005[ירדה],\u0006 וכי אין שם גסות הרוח? \u0003והכתיב\u0004 \u0005[והרי נאמר]:\u0006 \u0003\"ואשא עיני וארא והנה שתים נשים יוצאות ורוח בכנפיהם ולהנה כנפים ככנפי החסידה ותשנה את האיפה בין הארץ ובין השמים. ואומר אל המלאך הדבר בי אנה המה מולכות את האיפה. ויאמר אלי לבנות לה בית בארץ שנער\"\u0004 (זכריה ה, ט–יא) ושנער היא בבל. \u0003ואמר ר' יוחנן: זו חנופה וגסות הרוח שירדו לבבל,\u0004 ומשמע שלבבל ירדה גם גסות הרוח!","ומשיבים: \u0003אין, להכא נחית\u0004 \u0005[כן, לכאן,\u0006 לבבל \u0005ירדה]\u0006 \u0003ואשתרבובי הוא דאשתרבובי להתם\u0004 \u0005[והשתרבבה\u0006 והגיעה \u0005לשם]\u0006 לעילם. \u0003דיקא נמי\u0004 \u0005[מדוייק גם כן]\u0006 \u0003דקתני\u0004 \u0005[שנאמר]:\u0006 \u0003\"לבנות לה בית\"\u0004 לומר שהכוונה מראש היתה לבבל, אבל לא נעשה הדבר כן ולבסוף נקבע המקום דווקא בעילם. ומעירים: אכן, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שכן הוא.","ועוד שואלים: \u0003איני\u0004 \u0005[כן הוא]?!\u0006 \u0003והאמר מר\u0004 \u0005[והרי אמר החכם]:\u0006 \u0003סימן לגסות\u0004 — \u0003עניות, ועניות בבבל הוא דאיכא\u0004 \u0005[שישנה]\u0006 ולא בעילם! ומשיבים: \u0003מאי\u0004 \u0005[מהי]\u0006 \u0003עניות\u0004 שאמרנו כאן כסימן לגסות — זו \u0003עניות\u0004 של \u0003תורה,\u0004 ועניות בתורה היא בעילם דווקא. \u0003דכתיב\u0004 \u0005[ש\u0006כן \u0005נאמר]\u0006 \u0003\"אחות לנו קטנה ושדים אין לה\"\u0004 (שיר השירים ח, ח), \u0003ואמר ר' יוחנן: זו עילם שזכתה ללמוד, ולא זכתה ללמד,\u0004 שלא הוציאה מתוכה חכמים הראויים ללמד.","ועוד, \u0003עשרה קבים גבורה ירדו לעולם, תשעה\u0004 מהם \u0003נטלו פרסיים ו\u0004אחד כל העולם. \u0003עשרה קבים כנים ירדו לעולם, תשעה\u0004 מהם \u0003נטלה מדי\u0004 ואחד כל העולם. \u0003עשרה קבים כשפים ירדו לעולם, תשעה\u0004 מהם \u0003נטלה מצרים\u0004 ואחד כל העולם. \u0003עשרה קבים נגעים ירדו לעולם, תשעה\u0004 מהם \u0003נטלו חזירים\u0004 שהם מלאים נגעים שונים, ואחד כל העולם. \u0003עשרה קבים זנות ירדו לעולם, תשעה\u0004 מהם \u0003נטלה ערביא\u0004 ואחד כל העולם.","\u0003עשרה קבים עזות ירדו לעולם, תשעה\u0004 מהם \u0003נטלה מישן\u0004 הסמוכה לבבל, ואחד כל העולם. \u0003עשרה קבים שיחה ירדו לעולם, תשעה\u0004 מהם \u0003נטלו נשים\u0004 ואחד כל העולם. \u0003עשרה קבים שכרות ירדו לעולם, תשעה\u0004 מהם \u0003נטלו כושים\u0004 ואחד כל העולם. \u0003עשרה קבים שינה ירדו לעולם, תשעה\u0004 מהם \u0003נטלו עבדים ואחד נטלו כל העולם כולו.\u0004","אמר לאשה \u0003\"\u0004הרי את מקודשת לי \u0003על מנת שאני כהן\" ונמצא\u0004 שהוא \u0003לוי,\u0004 או שאמר \u0003\"\u0004על מנת שאני \u0003לוי\" ונמצא\u0004 שהוא \u0003כהן.\u0004 אמר \u0003\"\u0004על מנת שאני \u0003נתין\"\u0004 (מצאצאי הגבעונים), שהוא פסול לנישואין עם קהל ישראל מדברי סופרים, \u0003ונמצא\u0004 שהוא \u0003ממזר\u0004 שאסור בישראלית מן התורה. או שאמר \u0003\"\u0004על מנת שאני \u0003ממזר\" ונמצא\u0004 שהוא \u0003נתין.\u0004 אמר \"על מנת שאני \u0003בן עיר\u0004 קטנה\" \u0003ונמצא\u0004 שהוא \u0003בן כרך\u0004 גדול, או שאמר \u0003\"\u0004על מנת \u0003שאני\u0004 \u0003בן כרך\" ונמצא\u0004 שהוא \u0003בן עיר.\u0004 או \u0003\"על מנת שביתי קרוב למרחץ\" ונמצא\u0004 שביתו \u0003רחוק,\u0004 או שאמר \"על מנת שביתי \u0003רחוק\u0004 מן המרחץ\" \u0003ונמצא\u0004 שהוא \u0003קרוב.\u0004","\u0003\"על מנת שיש לו בת או שפחה מגודלת\" ואין לו, או\u0004 אמר \u0003\"על מנת שאין לו\u0004 בת או שפחה מגודלת \u0003\"\u0004— \u0003ויש לו.\u0004 או שאמר \u0003\"על מנת שאין לו בנים\" ויש לו, או על מנת שיש לו ואין לו. ובכולם, אף על פי שאמרה\u0004 אחר כך: \u0003\"בלבי היה להתקדש לו\"\u0004 בין כה וכה בלא להתחשב בתנאי זה — \u0003אף על פי כן\u0004 \u0003אינה מקודשת. וכן היא שהטעתו,\u0004 שאם קידש אותה על פי תנאי מסויים שלה, ולא נתקיים — בכל אלה בטלים הקידושין.","מסופר: \u0003ההוא גברא דזבין לנכסיה אדעתא למיסק\u0004 \u0005[אדם אחד שמכר את נכסיו על דעת לעלות]\u0006 \u0003לארץ ישראל, ובעידנא דזבין לא אמר ולא מידי\u0004 \u0005[דבר],\u0006 ולבסוף אירע שלא יכול היה לעלות, ורצה לחזור בו מן המכירה. \u0003אמר רבא:\u0004 כיון שלא אמר בפירוש שמוכר בתנאי שיעלה לארץ ישראל, \u0003הוי\u0004 \u0005[הרי\u0006 זה\u0005]\u0006 \u0003דברים שבלב, ודברים שבלב אינם דברים.\u0004 ושואלים: \u0003מנא ליה\u0004 \u0005מניין לו\u0006 \u0003לרבא הא\u0004 \u0005[\u0006דבר \u0005זה]\u0006 שדברים שבלב אינם נחשבים? \u0003אילימא מהא דתנן\u0004 \u0005[אם תאמר מזו ששנינו]\u0006 בברייתא:"]]};
